var RANKED=[{"id":6325,"bg":"При тази ситуация пресичането на линията, сигнализирана с конусите, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60317.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":53,"es":"En esta situación, cruzar la línea señalizada con conos está:","explain":"Prohibido: la fila de conos delimita una línea de organización TEMPORAL del tráfico, y cruzarla equivale a cruzar una línea continua. Los conos redistribuyen los carriles (obras, incidente): ignorarlos te mete en la zona cerrada o en el sentido contrario.","val":53,"fase":1},{"id":5428,"bg":"На какво разстояние зад МПС, принудително спряло на автомагистрала, се поставя предупредителният светлоотразителен триъгълник?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"не по-малко от 100 м","ok":true,"i":null,"es":"no menos de 100 m"},{"t":"не по-малко от 30 м","ok":false,"i":null,"es":"no menos de 30 m"},{"t":"не по-малко от 50 м","ok":false,"i":null,"es":"no menos de 50 m"},{"t":"не по-малко от 70 м","ok":false,"i":null,"es":"no menos de 70 m"}],"f":49,"es":"¿A qué distancia detrás de un vehículo parado forzosamente en autopista se coloca el triángulo de emergencia?","explain":"En autopista rige la distancia de vías rápidas: mínimo 100 m. El tráfico llega a 130 km/h y recorre 36 m por segundo: con 30 o 50 m nadie tendría tiempo de reaccionar ante el vehículo averiado.","val":49,"fase":1},{"id":5658,"bg":"В населено място предупредителният светлоотразителен триъгълник, се поставя:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"на разстояние не по-малко от 30 м от повреденото ППС","ok":true,"i":null,"es":"a no menos de 30 m del vehículo averiado"},{"t":"в пътната лента, заета от повреденото ППС","ok":true,"i":null,"es":"en el carril ocupado por el vehículo averiado"},{"t":"срещу посоката на движение на превозните средства които заобикалят повреденото ППС","ok":true,"i":null,"es":"en sentido contrario a la circulación de los vehículos que rodean el averiado"},{"t":"на тротоара","ok":false,"i":null,"es":"en la acera"}],"f":50,"es":"En zona urbana, el triángulo de emergencia reflectante se coloca: (3 respuestas correctas) (3 correctas)","explain":"En ciudad el triángulo se coloca: a mínimo 30 m del vehículo, EN el mismo carril ocupado (no en la acera, donde los conductores no lo verían asociado al obstáculo) y de cara al tráfico que se aproxima, para que su reflectante funcione.","val":50,"fase":1},{"id":11733,"bg":"На пътища с разрешена скорост за движение, по-висока от 90 km/h, предупредителният светлоотразителен триъгълник се поставя на разстояние от автомобила, не по-малко от:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"100 метра","ok":true,"i":null,"es":"100 metros"},{"t":"30 метра","ok":false,"i":null,"es":"30 metros"},{"t":"50 метра","ok":false,"i":null,"es":"50 metros"},{"t":"150 метра","ok":false,"i":null,"es":"150 metros"}],"f":53,"es":"En carreteras con velocidad permitida superior a 90 km/h, el triángulo de emergencia se coloca a no menos de:","explain":"En vías con límite SUPERIOR a 90 km/h el triángulo va a mínimo 100 m: a esas velocidades el que llega necesita mucho más espacio para percibir, reaccionar y frenar. Compara: hasta 90 km/h bastan 30 m.","val":53,"fase":1},{"id":6327,"bg":"Белият бастун, носен от пешеходец, означава, че той е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"сляп","ok":true,"i":null,"es":"ciego"},{"t":"глухоням","ok":false,"i":null,"es":"sordomudo"},{"t":"много възрастен","ok":false,"i":null,"es":"muy anciano"}],"f":53,"es":"El bastón blanco que lleva un peatón significa que es:","explain":"El bastón blanco identifica al peatón CIEGO: es el símbolo universal reconocido por la ley. Ante él debes extremar la precaución y cederle el paso siempre: no puede verte ni calcular tu velocidad. No existe distintivo de bastón para sordomudos o ancianos.","val":53,"fase":1},{"id":6326,"bg":"При тази ситуация конусите очертават линия, пресичането на която е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60367.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":46,"es":"En esta situación, los conos delimitan una línea cuyo cruce está:","explain":"Prohibido: misma regla que su gemela: los conos forman una línea infranqueable de señalización temporal. Su color llamativo no es decorativo: sustituyen a la marca continua mientras dura la situación especial.","val":46,"fase":1},{"id":11734,"bg":"На пътища с разрешена скорост за движение до 90 km/h, предупредителният светлоотразителен триъгълник се поставя на разстояние от автомобила не по-малко от:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"30 метра","ok":true,"i":null,"es":"30 metros"},{"t":"50 метра","ok":false,"i":null,"es":"50 metros"},{"t":"70 метра","ok":false,"i":null,"es":"70 metros"},{"t":"100 метра","ok":false,"i":null,"es":"100 metros"}],"f":47,"es":"En carreteras con velocidad permitida hasta 90 km/h, el triángulo de emergencia se coloca a no menos de:","explain":"Hasta 90 km/h el triángulo se coloca a mínimo 30 m. Es la pareja de la regla anterior: ≤90 km/h → 30 m; >90 km/h → 100 m. Truco: velocidad 'normal' = distancia corta, velocidad alta = distancia larga.","val":47,"fase":1},{"id":6034,"bg":"При кое от посочените средства за сигнализиране съществува опасност от внезапна поява на деца на платното за движение?","p":2,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26647.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26648.png","es":""},{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26649.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26650.png","es":""}],"f":50,"es":"¿En qué medio de señalización existe peligro de aparición repentina de niños en la calzada? (múltiple) (3 correctas)","explain":"Los tres medios correctos señalizan lugares con presencia de NIÑOS (advertencia de niños, zona escolar/peatonal, parada donde suben y bajan): ahí pueden irrumpir en la calzada de golpe. El cuarto no guarda relación con niños: señaliza otra cosa. Ante cualquiera de los tres: pie fuera del acelerador.","val":50,"fase":1},{"id":6324,"bg":"Временната пътна маркировка се разпознава по:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"цвета на маркировката","ok":true,"i":null,"es":"el color de la señalización"},{"t":"широчината на линиите","ok":false,"i":null,"es":"el ancho de las líneas"},{"t":"коефициента на светлоотразяване","ok":false,"i":null,"es":"el coeficiente de reflexión"}],"f":22,"es":"La señalización vial temporal se reconoce por:","explain":"La señalización temporal se reconoce por el COLOR: las marcas temporales son amarillas o naranjas frente al blanco de las permanentes. Ni el grosor de línea ni la reflectancia son el criterio distintivo legal.","val":22,"fase":4},{"id":6307,"bg":"Разрешено ли е пресичането на единичната непрекъсната линия между съседните пътни ленти?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60617.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":18,"es":"¿Está permitido cruzar la línea continua simple entre carriles adyacentes?","explain":"No: continua simple entre carriles adyacentes = infranqueable. Es la formulación más escueta de la familia: la respuesta es siempre la misma, se pregunte como se pregunte.","val":18,"fase":4},{"id":6315,"bg":"Разрешено ли е пресичането на единичната непрекъсната линия, очертаваща границата на платното за движение?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59834.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":17,"es":"¿Está permitido cruzar la línea continua simple que delimita el borde de la calzada?","explain":"Sí: es la línea continua simple que delimita el BORDE de la calzada, no una separadora de carriles. Se cruza legalmente para abandonar la calzada (arcén, entrada a garaje o propiedad). Trampa del examen: te enseñaron 'continua = prohibido cruzar', pero eso aplica ENTRE carriles/sentidos. Borde de calzada = cruzarla está permitido.","val":17,"fase":4},{"id":6309,"bg":"Пресичането на единичната непрекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59594.png","v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"},{"t":"забранено, освен за спиране от другата страна на пътя","ok":false,"i":null,"es":"prohibido salvo para parar al otro lado de la vía"}],"f":21,"es":"Cruzar la línea continua simple entre carriles adyacentes está:","explain":"Prohibido en todos los casos: la continua simple entre carriles adyacentes no se cruza nunca: ni para adelantar, ni para girar, ni 'para parar al otro lado' (el distractor recurrente). La discontinua existe exactamente para permitir lo que la continua niega.","val":21,"fase":4},{"id":6330,"bg":"“Изкуствената неравност” върху платното за движение е предназначена за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"ограничаване скоростта на ППС","ok":true,"i":null,"es":"limitar la velocidad de los vehículos"},{"t":"обозначаване на препятствие върху платното за движение","ok":false,"i":null,"es":"señalizar un obstáculo en la calzada"},{"t":"сигнализиране на площи забранени за движение","ok":false,"i":null,"es":"señalizar zonas prohibidas al tráfico"}],"f":22,"es":"El 'resalto artificial' (badén) en la calzada está diseñado para:","explain":"El badén ('policía tumbado') tiene una única función legal: obligar a REDUCIR LA VELOCIDAD mediante un obstáculo físico. No señaliza obstáculos ni delimita zonas prohibidas: para eso existen señales y marcas.","val":22,"fase":4},{"id":6308,"bg":"Пресичането на единичната непрекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57911.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":20,"es":"Cruzar la línea continua simple entre carriles adyacentes está:","explain":"Prohibido: continua simple entre carriles = muro pintado. Es la versión directa de la familia: sin excepciones ni matices.","val":20,"fase":4},{"id":6312,"bg":"Пресичането на единичната прекъсната линия между съседните пътни ленти е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59734.png","v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":20,"es":"Cruzar la línea discontinua simple entre carriles adyacentes está:","explain":"Permitido: la línea DISCONTINUA existe precisamente para poder cruzarla (cambios de carril, adelantamientos), siempre con seguridad y señalizando. El par continua-prohibido/discontinua-permitido es la base de todas las marcas longitudinales.","val":20,"fase":4},{"id":6317,"bg":"При тази ситуация на кой от автомобилите е разрешено да пресече пътната маркировка?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60017.png","v":null,"a":[{"t":"синия","ok":true,"i":null,"es":"al azul"},{"t":"червения","ok":false,"i":null,"es":"al rojo"},{"t":"на двата автомобила","ok":false,"i":null,"es":"a ambos vehículos"}],"f":20,"es":"En esta situación, ¿a cuál de los vehículos le está permitido cruzar la señalización vial?","explain":"Al AZUL: en su lado la marca es discontinua (cruzable); el rojo tiene la continua en su lado y no puede pisarla. En las líneas dobles mixtas manda el trazo de TU lado: es la regla que esta imagen enseña.","val":20,"fase":4},{"id":6322,"bg":"При тази ситуация пътната маркировка, поставена напречно на пътя, сигнализира:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60283.png","v":null,"a":[{"t":"изкуствена неравност на платното за движение","ok":true,"i":null,"es":"un resalto artificial (badén)"},{"t":"участък от пътя в ремонт","ok":false,"i":null,"es":"un tramo en obras"},{"t":"линия за изчакване","ok":false,"i":null,"es":"una línea de espera"},{"t":"място за задължително спиране","ok":false,"i":null,"es":"un lugar de parada obligatoria"}],"f":22,"es":"En esta situación, la señalización transversal en la calzada indica:","explain":"Es un RESALTO artificial (badén, 'policía tumbado'): la banda transversal señalizada en la calzada que obliga físicamente a reducir. No es línea de espera ni parada obligatoria: es el aviso del obstáculo moderador de velocidad.","val":22,"fase":4},{"id":6328,"bg":"При несъответствие между временната пътна маркировка и постоянната пътна маркировка, водачите:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":null,"v":null,"a":[{"t":"трябва да се съобразяват с временната пътна маркировка","ok":true,"i":null,"es":"deben atenerse a la señalización temporal"},{"t":"трябва да се съобразяват с постоянната пътна маркировка","ok":false,"i":null,"es":"deben atenerse a la señalización permanente"},{"t":"не трябва да се съобразяват с пътната маркировка","ok":false,"i":null,"es":"no deben atenerse a ninguna señalización"}],"f":24,"es":"Cuando la señalización temporal y la permanente no coinciden, los conductores:","explain":"Cuando la señalización temporal (amarilla, de obras) contradice a la permanente, obedeces la TEMPORAL: refleja la situación real actual de la vía. La permanente quedó desactivada por las circunstancias que motivaron la temporal.","val":24,"fase":4},{"id":11610,"bg":"При тази ситуация, кой от пътните знаци трябва да спазва водачът на синия автомобил?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123582022.png","v":null,"a":[{"t":"поставения на платното за движение преносим пътен знак","ok":true,"i":null,"es":"la señal portátil colocada en la calzada"},{"t":"постоянно поставения пътен знак","ok":false,"i":null,"es":"la señal fija instalada permanentemente"}],"f":18,"es":"En esta situación, ¿qué señal de tráfico debe respetar el conductor del vehículo azul?","explain":"Debe obedecer la señal PORTÁTIL colocada en la calzada: las señales temporales (obras, desvíos, emergencias) prevalecen sobre las fijas porque reflejan la situación REAL y actual de la vía. Mientras la portátil esté puesta, la permanente queda anulada. Jerarquía a memorizar: agente regulador > semáforo > señal temporal > señal fija > marcas viales.","val":18,"fase":4},{"id":12056,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":48,"a":[{"t":"да спра в разделителната ивица между платната на релсовия път, където е спрял другият автомобил","ok":false,"i":null,"es":"parar en la mediana donde está parado el otro coche"},{"t":"да спра, преди да завия наляво","ok":true,"i":null,"es":"parar ANTES de girar a la izquierda"},{"t":"да завия наляво, за да не възпрепятствам движението на автомобилите зад мен","ok":false,"i":null,"es":"girar a la izquierda para no obstaculizar el tráfico de atrás"}],"f":21,"es":"¿Qué debe hacer en esta situación? (VIDEO)","explain":"Quiero girar a la izquierda cruzando las vías del tranvía y en el espejo ya asoma un tranvía: lo correcto es DETENERME antes de iniciar el giro y dejarlo pasar. Pararme en la franja divisoria sobre las vías (donde quedó atrapado el otro coche del video) me dejaría en el camino del tranvía; y girar 'para no estorbar a los de atrás' antepone su comodidad a la seguridad. Nunca te detengas sobre raíles.","val":31,"fase":3},{"id":6314,"bg":"При тази ситуация пресичането на единичната непрекъсната линия, очертаваща границата на платното за движение, е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59817.png","v":null,"a":[{"t":"разрешено","ok":true,"i":null,"es":"permitido"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":17,"es":"En esta situación, cruzar la línea continua que delimita el borde de la calzada está:","explain":"Permitido: esta línea continua NO separa carriles ni sentidos — marca el BORDE de la calzada. Cruzarla para salir de la calzada (detenerse en el arcén, entrar a una propiedad) está permitido. La regla 'continua = infranqueable' vale para la que separa flujos de tráfico; la línea de borde es la excepción clásica que el examen explota.","val":17,"fase":4},{"id":6321,"bg":"Върху маркираната с коси успоредни линии част от платното за движение навлизането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60234.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"entrar (prohibido en todos los casos)"},{"t":"разрешено само при изпреварване","ok":false,"i":null,"es":"entrar solo al adelantar"},{"t":"разрешено само за спиране за престой","ok":false,"i":null,"es":"entrar solo para parar"}],"f":26,"es":"En la zona delimitada con líneas oblicuas paralelas está prohibido:","explain":"La zona de líneas oblicuas paralelas (zebrado) es superficie EXCLUIDA del tráfico: prohibido entrar en todos los casos: ni para adelantar ni para parar. Canaliza el tráfico y protege espacios (isletas, bifurcaciones): es un 'no pisar' pintado.","val":26,"fase":4},{"id":12054,"bg":"При тази ситуация трябва да намалите скоростта, с готовност за спиране заради:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":46,"a":[{"t":"мотоциклета","ok":true,"i":null,"es":"la moto"},{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"},{"t":"велосипедиста","ok":false,"i":null,"es":"el ciclista"}],"f":17,"es":"En esta situación debe reducir velocidad con disposición de frenar por: (VIDEO)","explain":"En la escena final una moto sale de un camino lateral por la izquierda con trayectoria que corta la mía: aunque circulo por la vía con prioridad (rombo amarillo Б3), reduzco con disposición de frenar POR LA MOTO — tener prioridad no te protege si el otro no la respeta (conducción defensiva). El coche azul viene de frente por su propio carril y el ciclista no invade mi trayectoria: no son la amenaza real.","val":26,"fase":3},{"id":12058,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":50,"a":[{"t":"изчаквам на коловозите","ok":false,"i":null,"es":"espero sobre las vías"},{"t":"внимателно пресичам релсите","ok":false,"i":null,"es":"cruzo las vías con cuidado"},{"t":"изчаквам пред прелеза","ok":true,"i":null,"es":"espero ANTES del paso a nivel"}],"f":15,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO - paso a nivel)","explain":"Tras el paso a nivel el tráfico está retenido y apenas hay hueco al otro lado: espero ANTES del paso a nivel y solo entro cuando pueda cruzarlo POR COMPLETO. 'Esperar sobre los raíles' es la trampa mortal del examen y de la vida real; 'cruzar con cuidado' tampoco sirve si no hay espacio libre después. Un paso a nivel se cruza entero o no se entra.","val":22,"fase":3},{"id":6311,"bg":"При тази ситуация, на водача на лекия автомобил е разрешено да пресече единичната непрекъсната линия за да спре от другата страна на пътя.","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59668.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":21,"es":"En esta situación, al conductor del turismo le está permitido cruzar la línea continua para aparcar al otro lado. Esto es:","explain":"INCORRECTO: cruzar la continua 'para aparcar al otro lado' no existe como excepción: es la misma trampa de la 6310 formulada al revés. La línea continua es absoluta: el aparcamiento no la perdona.","val":21,"fase":4},{"id":6313,"bg":"При тази ситуация, на водача на лекия автомобил е разрешено да пресече единичната прекъсната линия за да спре от другата страна на пътя.","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59734.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":17,"es":"En esta situación, al conductor del turismo le está permitido cruzar la línea discontinua para aparcar al otro lado. Esto es:","explain":"Correcto: la línea DISCONTINUA simple es franqueable por definición — el conductor puede cruzarla para pasar al otro lado de la calzada y detenerse allí, cediendo antes al tráfico en sentido contrario. 'Incorrecto' sería la respuesta si la línea fuera CONTINUA entre carriles: esa sí es infranqueable. Discontinua = se puede pisar y cruzar.","val":17,"fase":4},{"id":12057,"bg":"Искате да продължите движението си направо. Как трябва да постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":49,"a":[{"t":"спирам непосредствено зад жълтото превозно средство","ok":false,"i":null,"es":"paro inmediatamente detrás del vehículo amarillo"},{"t":"спирам пред кръстовището","ok":true,"i":null,"es":"paro ANTES de la intersección"},{"t":"спирам между жълтото и синьото превозно средство","ok":false,"i":null,"es":"paro entre el amarillo y el azul"}],"f":14,"es":"Quiere continuar recto. ¿Cómo debe actuar en esta situación? (VIDEO - semáforo)","explain":"El semáforo está en VERDE pero al otro lado del cruce la cola está detenida (la furgoneta amarilla no avanza): paro ANTES de la intersección. El verde autoriza a entrar solo si también puedes SALIR; detenerte dentro — detrás del amarillo o entre el amarillo y el azul — bloquea el cruce para los demás flujos. Regla de oro: no entres a un cruce que no puedas abandonar.","val":22,"fase":3},{"id":6316,"bg":"Разрешено ли е пресичането на единичната прекъсната линия, очертаваща границата на платното за движение?","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59885.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":20,"es":"¿Está permitido cruzar la línea discontinua que delimita el borde de la calzada?","explain":"Sí: la línea discontinua del BORDE de la calzada puede cruzarse: por ejemplo para parar en el arcén o incorporarte desde él. Si el borde fuera continuo, cruzarlo estaría prohibido salvo emergencia: el tipo de trazo decide.","val":20,"fase":4},{"id":6323,"bg":"Върху площта, очертана с жълтата начупена линия е разрешено да спрете за:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/88414.png","v":null,"a":[{"t":"престой","ok":true,"i":null,"es":"parada breve (prestoy)"},{"t":"паркиране","ok":false,"i":null,"es":"aparcar"},{"t":"престой и паркиране","ok":false,"i":null,"es":"parada breve y aparcamiento"}],"f":23,"es":"En la zona delimitada con la línea amarilla quebrada está permitido parar para:","explain":"La línea amarilla quebrada junto al bordillo delimita una zona donde solo se permite el престой: detención breve (subir/bajar pasajeros, cargar/descargar) sin abandonar la actividad. Паркиране (dejar estacionado el vehículo) está prohibido sobre ella — por eso 'aparcar' y 'parada breve y aparcamiento' son falsas. Amarillo en el bordillo = régimen especial, nunca estacionamiento libre.","val":23,"fase":4},{"id":5845,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24421.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"El conductor ve al agente DE PECHO (de frente): pecho y espalda son 'muro' — paso PROHIBIDO en todas las direcciones. Girar a la derecha, a la izquierda o en U también es 'pasar', así que las tres opciones de giro son falsas. Regla geométrica de toda la familia: ¿qué me muestra el agente? Pecho/espalda = alto; costado = puerta (recto o derecha).","val":17,"fase":3},{"id":6523,"bg":"При тази ситуация кой от автомобилите трябва да пропуснете?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57175.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al vehículo ROJO"},{"t":"синия автомобил","ok":false,"i":null,"es":"al vehículo azul"}],"f":9,"es":"En esta situación, ¿a cuál vehículo debe dejar pasar?","explain":"Al ROJO. Tienes un STOP, así que debes ceder a quien circula por la vía transversal, y el rojo va justo por ella cruzando tu trayectoria. El azul, en cambio, está en TU misma vía, de frente: no te cruza y no le cedes nada. Ahí está la trampa — con un STOP se tiende a ceder a todo lo que se mueve, pero solo obliga con quien circula por la vía con prioridad.","val":13,"fase":3},{"id":12053,"bg":"При тази ситуация трябва да:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":45,"a":[{"t":"осигурите предимство на зеления автомобил","ok":true,"i":null,"es":"ceder el paso al coche verde"},{"t":"осигурите предимство на червения автомобил","ok":false,"i":null,"es":"ceder el paso al coche rojo"},{"t":"изчакате преминаването на велосипедиста","ok":true,"i":null,"es":"esperar al ciclista"}],"f":16,"es":"En esta situación debes: (VIDEO) ⚠️ 2 correctas","explain":"Giro a la izquierda desde la vía preferente (rombo Б3): cedo el paso al coche VERDE que viene de frente — girar a la izquierda nunca da prioridad sobre el sentido contrario, ni siquiera en vía preferente — y espero a que el CICLISTA termine de cruzar. El coche rojo llega por la vía sin prioridad: él me cede a mí. Orden al girar a la izquierda: primero el sentido contrario, luego los vulnerables, después el giro.","val":24,"fase":3},{"id":12062,"bg":"Искате да продължите по пътя с предимство. Какво трябва да очаквате при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":53,"a":[{"t":"че децата ще слязат на платното за движение","ok":true,"i":null,"es":"que los niños bajen a la calzada"},{"t":"че микробусът ще продължи движението си по пътя с предимство","ok":false,"i":null,"es":"que el microbús continúe por la vía preferente"},{"t":"че водачът на червения автомобил няма да ме види навреме","ok":true,"i":null,"es":"que el conductor del coche rojo no me vea a tiempo"}],"f":18,"es":"Quiere continuar por la vía preferente. ¿Qué debe esperar? (VIDEO) ⚠️ 2 correctas","explain":"El microbús naranja está detenido junto a la acera dejando pasajeros mientras la vía preferente tuerce a la izquierda: debo esperar que aparezcan NIÑOS bajando a la calzada ocultos por el microbús, y que el conductor del coche rojo, con la visión tapada por él, NO me vea a tiempo. Que 'el microbús continúe su marcha' no es el peligro: está parado. Vehículo detenido = cortina que oculta peatones.","val":27,"fase":3},{"id":5416,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla, incluso donde esté interrumpida"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta (cambio de sentido)"},{"t":"да се движи назад","ok":true,"i":null,"es":"circular marcha atrás"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para reparar una avería"}],"f":8,"es":"Conduciendo por vía rápida (autopista), al conductor le está PROHIBIDO: (3 correctas)","explain":"Prohibido en vía rápida: entrar o cruzar la mediana (aunque esté interrumpida), dar la vuelta y circular marcha atrás: las tres maniobras van contra el flujo de alta velocidad. Parar para reparar una avería es la excepción permitida.","val":8,"fase":4},{"id":5610,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на велосипедна пътека","ok":true,"i":null,"es":"en un carril bici"},{"t":"на разстояние, по-малко от 5 метра преди велосипедна пътека","ok":true,"i":null,"es":"a menos de 5 metros ANTES de un carril bici"},{"t":"на разстояние, по-малко от 5 метра след велосипедна пътека","ok":false,"i":null,"es":"a menos de 5 metros DESPUÉS de un carril bici"}],"f":6,"es":"La parada breve (prestoy) está prohibida: (2 correctas)","explain":"Parada breve prohibida SOBRE el carril bici y a menos de 5 m ANTES de él: taparías al ciclista que llega justo donde cruza tu trayectoria. Después del carril la prohibición no rige.","val":3,"fase":4},{"id":12059,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":61,"a":[{"t":"да се движа възможно най-вляво","ok":true,"i":null,"es":"me muevo todo lo posible a la izquierda"},{"t":"продължавам движението си в заеманата лента","ok":false,"i":null,"es":"continúo en mi carril"},{"t":"намалявам скоростта си на движение","ok":true,"i":null,"es":"reduzco la velocidad"}],"f":22,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO) ⚠️ 2 correctas","explain":"La escena final muestra un triángulo de preseñalización y un incidente en el lado derecho de la autovía: la reacción correcta es doble — REDUCIR la velocidad y apartarme todo lo posible a la IZQUIERDA para dar espacio lateral al lugar del accidente. Seguir en mi carril sin cambiar nada ignora el peligro. Regla: ante incidente u obstáculo en el margen, velocidad abajo + máxima distancia lateral.","val":11,"fase":4},{"id":5888,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39253.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución redoblada'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Cede el paso a los que circulan por la vía transversal'"}],"f":11,"es":"El significado de esta señal del agente regulador es:","explain":"La misma señal que en la 5885, pero vista por la ESPALDA del agente: brazo levantado en vertical = «¡Atención, para!». Por eso existen las dos preguntas: pecho o espalda, el brazo en alto obliga a parar igual, no hay dirección privilegiada. No la confundas con los brazos extendidos en horizontal, que sí distinguen: alto para quien ve pecho o espalda, paso para quien ve los costados.","val":16,"fase":3},{"id":5914,"bg":"Този сигнал на светофара означава, че е забранено навлизането в кръстовището на ППС, които:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43602.png","v":null,"a":[{"t":"преминават направо","ok":true,"i":null,"es":"continúan recto"},{"t":"завиват наляво","ok":true,"i":null,"es":"giran a la izquierda"},{"t":"завиват надясно","ok":false,"i":null,"es":"giran a la derecha"}],"f":10,"es":"Esta señal de semáforo significa que está PROHIBIDO entrar en la intersección a los vehículos que: (2 correctas)","explain":"MULTIRESPUESTA. El disco ROJO encendido detiene a todos; la sección adicional con flecha verde libera un único movimiento, el giro a la DERECHA. Por eso quedan prohibidos los que siguen recto y los que giran a la izquierda. Regla: con el rojo encendido, lo único que puedes hacer es la dirección que ilumine la flecha verde de la sección adicional.","val":15,"fase":3},{"id":5935,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103109.png","v":null,"a":[{"t":"през кръстовището преминават ППС, които имат разрешаващ сигнал от светофара","ok":true,"i":null,"es":"pasan los vehículos con semáforo en verde"},{"t":"завиващите наляво ППС на разрешаващ сигнал пропускат насрещнодвижещите","ok":true,"i":null,"es":"los que giran a la izquierda en verde ceden al tráfico de frente"},{"t":"ППС на разрешаващ сигнал, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los vehículos con verde entre sí aplican la regla de prioridad de la derecha"}],"f":8,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: Con semáforo verde, pasan los que tienen verde Y quien gira a la izquierda cede al tráfico contrario. La regla de la derecha NO se aplica entre vehículos con semáforo — eso es incorrecto.","val":11,"fase":3},{"id":12055,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":47,"a":[{"t":"да намаля скоростта и при необходимост да спра","ok":true,"i":null,"es":"reducir velocidad y si es necesario parar"},{"t":"да осигуря предимство на автомобила, който се движи в кръстовището с кръгово движение","ok":true,"i":null,"es":"ceder el paso al vehículo que circula dentro de la glorieta"},{"t":"да включа десен пътепоказател","ok":false,"i":null,"es":"activar el intermitente derecho"}],"f":14,"es":"¿Qué debe hacer en esta situación? (VIDEO - glorieta) ⚠️ 2 correctas","explain":"Llego a una glorieta (ceda el paso Б1 + señal de circulación giratoria) y un coche azul ya circula dentro: reduzco y, si hace falta, PARO — quien está dentro de la glorieta tiene prioridad sobre quien entra. El intermitente derecho no se pone al entrar: se usa al SALIR de la glorieta para avisar la salida; aquí es el distractor. Entrar = ceder; salir = señalizar.","val":22,"fase":3},{"id":5722,"bg":"Превозването на предмети върху покрива на автомобила води до увеличаване на разхода на гориво.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":13,"es":"Transportar objetos en el techo del coche aumenta el consumo de combustible. Esto es:","explain":"Correcto: la carga en el techo aumenta la resistencia aerodinámica y con ella el consumo, incluso con el portaequipajes vacío. Por eso conviene retirarlo cuando no se usa.","val":6,"fase":4},{"id":6310,"bg":"При тази ситуация пресичането на единичната непрекъсната линия е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59668.png","v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено, освен за спиране от другата страна на пътя","ok":false,"i":null,"es":"prohibido salvo para aparcar al otro lado"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":29,"es":"En esta situación, cruzar la línea continua simple está:","explain":"Prohibido en TODOS los casos: la línea continua simple no se cruza jamás, y no existe la excepción 'para aparcar al otro lado': esa opción es el gancho. Si necesitas el otro lado, busca dónde la línea sea discontinua o gira legalmente.","val":29,"fase":4},{"id":5873,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37386.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":14,"es":"La señal del agente regulador significa que:","explain":"PROHIBIDO pasar: el agente te muestra el pecho (o la espalda): equivale a semáforo en ROJO para ti. Ningún giro está permitido contra el pecho del agente: esperas a que cambie de posición.","val":20,"fase":3},{"id":5900,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41967.png","v":null,"a":[{"t":"„Преминаването е забранено”","ok":true,"i":null,"es":"'El paso está prohibido'"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Внимание, спри!”","ok":false,"i":null,"es":"'¡Atención, para!'"}],"f":9,"es":"El significado de esta señal de semáforo es:","explain":"'El paso está prohibido'. Están encendidas la ROJA y la ÁMBAR a la vez. Esa combinación no autoriza a pasar: avisa de que el verde está a punto de llegar para que prepares la salida, pero hasta que aparezca sigues detenido. '¡Atención!' corresponde al ámbar intermitente y '¡Atención, para!' al ámbar fijo solo. Truco: si la roja está encendida, da igual lo que la acompañe.","val":14,"fase":3},{"id":6332,"bg":"Когато, на жп прелез без бариери, след преминаването на влака червените светлини на светофара продължават да светят, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не трябва да навлиза с автомобила на жп прелеза","ok":true,"i":null,"es":"NO debe entrar al paso a nivel"},{"t":"може да премине внимателно през жп прелеза","ok":false,"i":null,"es":"puede cruzar con cuidado"},{"t":"трябва да слезе от автомобила и да провери какво се случва","ok":false,"i":null,"es":"debe bajar del coche a comprobar"},{"t":"може да премине, като включи аварийните светлини","ok":false,"i":null,"es":"puede cruzar con las luces de emergencia encendidas"}],"f":10,"es":"En un paso a nivel sin barreras, después del paso del tren las luces rojas del semáforo siguen encendidas. El conductor:","explain":"Si las luces rojas siguen activas tras pasar el tren, NO entres: puede venir OTRO tren por la segunda vía (es el caso típico de accidente mortal). El semáforo manda mientras esté en rojo; ni el cuidado ni las luces de emergencia lo anulan.","val":14,"fase":3},{"id":6608,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51516.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак за задължителна посока за движение в кръстовището","ok":true,"i":null,"es":"la señal de dirección obligatoria en la intersección"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"f":10,"es":"En esta situación, al pasar por la intersección debes atenerte a: (2 correctas)","explain":"MULTIRESPUESTA: el SEMÁFORO y la señal de DIRECCIÓN OBLIGATORIA. El verde está encendido, y el disco azul con flecha recta obliga a seguir de frente; el verde autoriza a pasar pero no habilita una dirección que otra señal impone. La de prioridad NO cuenta: mientras el semáforo funciona, deja sin efecto a las señales de prioridad. Orden: semáforo > señales de prioridad; la dirección obligatoria sigue viva.","val":15,"fase":3},{"id":7967,"bg":"При тази ситуация трябва да премина преди:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64918031.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтия автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"f":8,"es":"En esta situación debes pasar antes que: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: según las reglas de prioridad de esta intersección específica tienes prioridad sobre el azul Y el rojo. Analiza la imagen para identificar quién tiene la derecha.","val":13,"fase":3},{"id":12061,"bg":"На кое превозно средство трябва да осигурите предимство, преди да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":52,"a":[{"t":"на трактора","ok":false,"i":null,"es":"al tractor"},{"t":"на мотоциклета","ok":true,"i":null,"es":"a la moto"},{"t":"на превозните средства, идващи отляво","ok":true,"i":null,"es":"a los vehículos que vienen por la izquierda"}],"f":19,"es":"¿A qué vehículo debes ceder el paso antes de girar a la derecha? (VIDEO) ⚠️ 2 correctas","explain":"Estoy en un ceda el paso (señal Б1 + triángulo pintado en el asfalto) incorporándome a la derecha: debo ceder a la MOTO que circula por la vía principal y a todo lo que venga por mi IZQUIERDA, porque su trayectoria cruza la mía al incorporarme. El tractor ya se aleja por la vía y no corta mi camino: es el distractor. En un Б1 la prioridad es siempre de la vía a la que te incorporas.","val":28,"fase":3},{"id":5391,"bg":"На автомобилен път е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"леки автомобили с ремаркета","ok":false,"i":null,"es":"turismos con remolque"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"}],"f":10,"es":"En autopista está PROHIBIDA la circulación de: (3 correctas)","explain":"En autopista no pueden circular ciclomotores, tractores ni bicicletas: no alcanzan la velocidad mínima segura para ese tráfico. Los turismos CON remolque sí están permitidos (con su límite de 100 km/h).","val":10,"fase":4},{"id":5544,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42178.png","v":null,"a":[{"t":"е забранено спирането за престой","ok":true,"i":null,"es":"está prohibida la parada breve (prestoy)"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está prohibido aparcar"},{"t":"е разрешено спирането за престой","ok":false,"i":null,"es":"está permitida la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está permitido aparcar"}],"f":6,"es":"Después de esta señal: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: esta señal prohíbe TANTO la parada breve (prestoy) COMO el aparcamiento. Zona de prohibición total de detención.","val":3,"fase":4},{"id":5839,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24291.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":15,"es":"¿Para qué conductores es una señal de paso la posición del agente regulador? (2 correctas)","explain":"Pasan el ROJO y el VERDE: los flancos (costados) del agente equivalen a luz VERDE: los coches que ven al agente de lado tienen paso libre. El amarillo y el azul le ven el pecho o la espalda: para ellos es rojo. Memoriza: costados = pasa, pecho/espalda = stop.","val":23,"fase":3},{"id":5859,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36529.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":12,"es":"¿Para qué conductor la señal del agente significa STOP?","explain":"STOP para el coche ROJO: el brazo del agente y su posición le muestran al rojo el frente/gesto de detención. Los demás colores tienen otras posiciones relativas. Lee siempre la geometría: ¿qué le muestra el agente a CADA coche: costado o pecho?","val":18,"fase":3},{"id":5906,"bg":"Значението на този сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42214.png","v":null,"a":[{"t":"„Преминаването е разрешено”","ok":true,"i":null,"es":"'El paso está permitido'"},{"t":"„Разрешено е преминаването във всички посоки”","ok":false,"i":null,"es":"'Permitido pasar en todas las direcciones'"},{"t":"„Разрешено е преминаването направо и надясно”","ok":false,"i":null,"es":"'Permitido pasar recto y a la derecha'"}],"f":10,"es":"El significado de esta señal de semáforo es:","explain":"Disco VERDE encendido, sin flecha: el paso está permitido. No es 'en todas las direcciones': el verde solo autoriza lo que ya permitan las marcas viales y las señales, no habilita un giro prohibido por otra señal. Y 'recto y a la derecha' describiría un verde con FLECHAS. Regla corta: disco = paso; flecha = únicamente esa dirección.","val":14,"fase":3},{"id":11584,"bg":"Значението на този немигащ сигнал на светофара е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1098228160.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Преминаването е разрешено”, но водачите са длъжни да бъдат внимателни и предпазливи","ok":false,"i":null,"es":"'El paso está permitido', pero los conductores están obligados a ser atentos y prudentes"},{"t":"„Преминаването е разрешено”","ok":false,"i":null,"es":"'El paso está permitido'"}],"f":11,"es":"El significado de esta señal fija de semáforo es:","explain":"Ámbar FIJO (no intermitente) = «Внимание, спри!» / «¡Atención, para!»: hay que detenerse, salvo que ya no puedas frenar sin crear peligro. Las dos falsas dicen «el paso está permitido»: ese es el VERDE, y la variante «pero con precaución» es el ámbar INTERMITENTE. Fijo manda parar, intermitente deja pasar con cuidado: esa es toda la pregunta.","val":17,"fase":3},{"id":5944,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82624.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"от пътните знаци относно предимството","ok":false,"i":null,"es":"las señales verticales relativas a la prioridad"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación de los vehículos"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"}],"f":10,"es":"En esta situación el orden de paso de los vehículos en la intersección lo determina:","explain":"Las señales del REGULADOR. Aunque en el cruce haya señales verticales de prioridad, el agente está por encima de ellas: regulador > semáforo > señales verticales > marcas viales > reglas generales. Por eso caen los tres distractores: mientras el agente dirija, ni el rombo de prioridad, ni la dirección de marcha, ni la regla de la derecha deciden nada.","val":14,"fase":3},{"id":6333,"bg":"Задължително ли е спирането на ППС пред жп прелеза, когато е включена само звуковата сигнализация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Es obligatorio parar antes del paso a nivel cuando solo suena la señal acústica?","explain":"Sí: la señal acústica activa por sí sola ya obliga a parar. Cualquier señal del paso a nivel (sonido, luz roja o barrera) significa 'tren aproximándose' y todas tienen el mismo valor imperativo.","val":12,"fase":3},{"id":6339,"bg":"На водача е забранено да навлиза на железопътния прелез:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"преди да се е убедил, че към прелеза не се приближава влак","ok":true,"i":null,"es":"antes de asegurarse de que no se aproxima ningún tren"},{"t":"когато от другата страна на прелеза няма достатъчно място за продължаване на движението","ok":true,"i":null,"es":"cuando al otro lado no hay espacio suficiente para continuar"},{"t":"когато на прелеза трябва да се размине с друго ППС","ok":false,"i":null,"es":"cuando en el paso debe cruzarse con otro vehículo"},{"t":"когато на прелеза няма съоръжения за подаване на звуков и светлинен сигнал","ok":false,"i":null,"es":"cuando no hay señales acústicas ni luminosas"}],"f":8,"es":"Al conductor le está PROHIBIDO entrar al paso a nivel: (2 correctas)","explain":"Prohibido entrar sin haber comprobado que no viene tren, y cuando al otro lado no hay hueco para salir (quedarías atrapado sobre las vías). Cruzarse con otro vehículo o la ausencia de señales no prohíben la entrada: solo exigen más precaución.","val":12,"fase":3},{"id":6472,"bg":"За кои водачи са задължителни сигналите за спиране, подавани от застаналия на прелеза железопътен служител?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"за водачите от двете страни на жп прелеза","ok":true,"i":null,"es":"para los conductores de ambos lados del paso"},{"t":"само за водачите, които се приближават от тази страна на прелеза, от която се намира жп служителя","ok":false,"i":null,"es":"solo para los que se aproximan desde el lado donde está el ferroviario"},{"t":"сигналите на жп служителя не са задължителни за водачите на МПС","ok":false,"i":null,"es":"las señales del ferroviario no son obligatorias para vehículos"}],"f":9,"es":"¿Para qué conductores son obligatorias las señales de stop del ferroviario en el paso a nivel?","explain":"Las señales de stop del agente ferroviario obligan a los conductores de AMBOS lados del paso: el peligro (el tren) amenaza a ambos sentidos por igual. Sus señales tienen carácter obligatorio como las de cualquier agente regulador.","val":13,"fase":3},{"id":6558,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66983.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"⚠️ TRAMPA: la imagen muestra una situación donde el rojo NO tiene prioridad a pesar de lo que pueda parecer. Analiza quién viene por la derecha o quién está en vía preferente.","val":13,"fase":3},{"id":11891,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 метра","ok":true,"i":null,"es":"no menos de 2 metros"},{"t":"не повече от 2 метра","ok":false,"i":null,"es":"no más de 2 metros"},{"t":"възможно най-малкото","ok":false,"i":null,"es":"la menor posible"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"f":8,"es":"Cuando la posición de parada antes del paso a nivel se determina respecto a los raíles, la distancia debe ser:","explain":"No menos de 2 metros del raíl: distancia MÍNIMA de seguridad (el tren y su carga sobresalen del raíl). 'No más de 2 m' invierte la regla acercándote al peligro, y la norma no deja la distancia a criterio del conductor.","val":12,"fase":3},{"id":12060,"bg":"Какъв е правилният начин на действие при тази ситуация? Спирам, изключвам двигателя и:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":51,"a":[{"t":"напускам тунела през най-близкия авариен изход","ok":true,"i":null,"es":"abandono el túnel por la salida de emergencia más cercana"},{"t":"изчаквам в превозното средство на мястото на инцидента, докато пътят се освободи","ok":false,"i":null,"es":"espero en el vehículo hasta que se despeje la vía"},{"t":"спирам автомобила извън лентата за принудително спиране","ok":true,"i":null,"es":"paro el coche fuera del carril de emergencia"}],"f":17,"es":"¿Cuál es la actuación correcta? Paro, apago el motor y... (VIDEO) ⚠️ 2 correctas","explain":"Incendio dentro del túnel (humo, conos, gente corriendo hacia las salidas verdes): paro, apago el motor y hago dos cosas — dejo el coche FUERA del carril de detención de emergencia, que debe quedar libre para los servicios de rescate, y abandono el túnel por la salida de emergencia MÁS CERCANA. Esperar dentro del vehículo junto al incendio es la opción letal: en un túnel el humo mata antes que el fuego.","val":26,"fase":3},{"id":5414,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar fuera de los lugares señalizados para aparcar"},{"t":"да навлиза в разделителната ивица","ok":true,"i":null,"es":"entrar en la mediana"},{"t":"да пресича разделителната ивица, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"cruzar la mediana incluso donde esté interrumpida"},{"t":"да се движи с прикачено ремарке","ok":false,"i":null,"es":"circular con remolque enganchado"}],"f":11,"es":"Conduciendo por autopista al conductor le está PROHIBIDO: (3 correctas)","explain":"En autopista está prohibido: parar fuera de los lugares señalizados, entrar en la mediana y cruzarla aunque esté interrumpida (esos huecos son para servicios de emergencia). Circular con remolque SÍ está permitido: por eso esa opción es falsa.","val":11,"fase":4},{"id":8276,"bg":"На скоростен път е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"движението на превозни средства с рекламна цел","ok":true,"i":null,"es":"la circulación de vehículos con fines publicitarios"},{"t":"провеждането на технически изпитания на автомобили","ok":true,"i":null,"es":"la realización de pruebas técnicas de vehículos"},{"t":"движението на рекламни и други шествия","ok":true,"i":null,"es":"la circulación de caravanas publicitarias y desfiles"},{"t":"движението на автомобили с товар над 10 т","ok":false,"i":null,"es":"la circulación de vehículos con carga superior a 10 t"}],"f":8,"es":"En una vía rápida está prohibido: (3 correctas)","explain":"En vía rápida están prohibidas las actividades que entorpecen el flujo: circulación con fines publicitarios, pruebas técnicas de vehículos y caravanas o desfiles. El peso de la carga (10 t) no es motivo de prohibición: los camiones circulan con normalidad.","val":8,"fase":4},{"id":8280,"bg":"В кои случаи автомобилът, спрян върху площадката за принудително спиране на скоростен път, задължително се сигнализира?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"през нощта","ok":true,"i":null,"es":"de noche"},{"t":"при намалена видимост","ok":true,"i":null,"es":"con visibilidad reducida"},{"t":"винаги","ok":false,"i":null,"es":"siempre"},{"t":"при ограничена видимост","ok":false,"i":null,"es":"con visibilidad limitada"}],"f":8,"es":"¿En qué casos debe estar señalizado el coche parado en el área de parada forzosa de vía rápida? (2 correctas)","explain":"El vehículo parado en el área de parada forzosa debe señalizarse de NOCHE y con visibilidad REDUCIDA (niebla, lluvia): cuando los demás no pueden verlo a tiempo. No 'siempre' (de día despejado se ve) y la visibilidad 'limitada' es un concepto geométrico de curvas, no de esta regla.","val":8,"fase":4},{"id":11354,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta (cambio de sentido)"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular en el carril contrario"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":10,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (2 correctas)","explain":"En vía rápida está prohibido dar la vuelta y circular por el carril contrario: maniobras contra el flujo a alta velocidad. Remolcar con barra rígida SÍ se permite (máx. 70 km/h): es la opción trampa.","val":10,"fase":4},{"id":11639,"bg":"На водача е забранено да управлява пътно превозно средство, което е спряно от движение и няма издадено разрешение за временно движение:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":8,"es":"Al conductor le está prohibido conducir un vehículo retirado de la circulación y sin autorización de circulación temporal emitida. Esto es:","explain":"Correcto: un vehículo retirado de la circulación solo puede moverse con una autorización TEMPORAL emitida al efecto. Sin ella, conducirlo está prohibido: el vehículo no existe administrativamente para la vía.","val":4,"fase":4},{"id":5869,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е забранено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36662.png","v":null,"a":[{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"}],"f":10,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa 'Paso PROHIBIDO'? (3 correctas)","explain":"Prohibido para el VERDE, el AMARILLO y el AZUL — las tres correctas. El único que pasa es el ROJO, porque es el que ve al agente de costado: la geometría de siempre en esta familia, costado = puerta abierta, pecho o espalda = muro. Ojo con la redacción: te preguntan a quién se le PROHÍBE, no a quién se le permite; su gemela 5837 hace la misma pregunta del revés.","val":15,"fase":3},{"id":5876,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37468.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"El conductor tiene al agente de CARA (le ve el pecho): paso PROHIBIDO en todas las direcciones — recto, derecha, izquierda y giro en U cruzarían el 'muro'. La posición del brazo no lo salva: mientras veas pecho o espalda, no hay dirección habilitada. Solo quien ve el costado puede moverse, y únicamente recto o a la derecha.","val":17,"fase":3},{"id":5882,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37566.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"е разрешено да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"е разрешено да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"е разрешено да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"Aquí el agente da la ESPALDA al conductor: igual que el pecho, es 'muro' — paso prohibido en cualquier dirección. Girar también es 'pasar', así que ninguna opción de giro esquiva la prohibición. Memoriza el par de esta familia: pecho/espalda = alto total; costado = puerta abierta solo para recto y derecha.","val":17,"fase":3},{"id":5928,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44560.png","v":null,"a":[{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está colocado"},{"t":"„Задължителна посока за движение”","ok":false,"i":null,"es":"'Dirección obligatoria'"},{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está colocado"},{"t":"„Място за задължително спиране” в пътната лента, над която е поставен","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"f":8,"es":"El significado de esta señal luminosa es:","explain":"⚠️ TRAMPA clásica: flecha verde hacia abajo = ENTRADA PERMITIDA en ese carril. Confúndela con la X roja = entrada prohibida. Identifica bien el símbolo.","val":11,"fase":3},{"id":5934,"bg":"Когато и двете секции на този светофар не работят и няма пътен знак за броя и посоките на движение по пътните ленти, това означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/45488.png","v":null,"a":[{"t":"навлизането по пътната лента, над която е поставен светофарът, е забранено","ok":true,"i":null,"es":"la entrada al carril sobre el que está colocado el semáforo está PROHIBIDA"},{"t":"навлизането по пътната лента, над която е поставен светофарът, е разрешено","ok":false,"i":null,"es":"la entrada está permitida"},{"t":"водачът трябва да спре на линията, на която е поставен светофарът","ok":false,"i":null,"es":"el conductor debe parar en la línea del semáforo"}],"f":12,"es":"Cuando ambas secciones de este semáforo no funcionan y no hay señal de tráfico:","explain":"Con ambas secciones apagadas y sin señal: la entrada al carril bajo ese semáforo (de control de carril) está PROHIBIDA: sin confirmación de que el carril está abierto, se asume cerrado. La duda, en carriles reversibles, siempre juega a prohibido.","val":18,"fase":3},{"id":6069,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59751.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":8,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"Analiza si el vehículo está correctamente posicionado respecto a las líneas de carril y el lado de la calzada correspondiente.","val":12,"fase":3},{"id":6077,"bg":"По този път извън населено място водачът трябва да се движи:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102157.png","v":null,"a":[{"t":"възможно най-вдясно по платното за движение, когато лентите не са очертани с пътна маркировка","ok":true,"i":null,"es":"todo lo posible a la derecha cuando los carriles no están marcados"},{"t":"в дясната пътна лента, когато лентите са очертани с пътна маркировка","ok":true,"i":null,"es":"en el carril derecho cuando los carriles están marcados"},{"t":"в по-удобната за него пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента винаги, когато е свободна","ok":false,"i":null,"es":"siempre en el carril izquierdo cuando esté libre"}],"f":9,"es":"Por esta carretera fuera de población el conductor debe circular: (2 correctas)","explain":"MULTIRESPUESTA. Fuera de población la regla es ir a la derecha, y se aplica de dos formas según el firme: si hay marcas que delimiten carriles, por el carril derecho; si no las hay, lo más a la derecha posible de la calzada. Las otras dos son justo lo contrario: elegir el carril 'más cómodo' vale en población, no fuera, y viajar por el izquierdo porque esté libre nunca vale.","val":14,"fase":3},{"id":6492,"bg":"При тази ситуация водачът на бавнодвижещото се ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65857.png","v":null,"a":[{"t":"е задължен да използва най-дясната пътна лента","ok":true,"i":null,"es":"está obligado a usar el carril más a la derecha"},{"t":"може да използва средната пътна лента при заобикаляне","ok":true,"i":null,"es":"puede usar el carril central al rodear un obstáculo"},{"t":"може да използва крайната лява лента при завиване","ok":true,"i":null,"es":"puede usar el carril izquierdo al girar"},{"t":"може да използва крайната лява лента при изпреварване","ok":false,"i":null,"es":"puede usar el carril izquierdo al adelantar"}],"f":9,"es":"En esta situación el conductor del vehículo lento: (3 correctas)","explain":"MULTIRESPUESTA. La señal marca tres carriles y el vehículo lento debe ir por el MÁS A LA DERECHA. Puede salir de él en dos casos concretos: usar el central para rodear un obstáculo, y el izquierdo para girar. Lo que no puede es usar el izquierdo para ADELANTAR, que es el distractor. Regla: el lento sale de su carril para esquivar o para girar, nunca para adelantar.","val":13,"fase":3},{"id":6229,"bg":"Преди отклонение встрани, за навлизане в съседна пътна лента, водачът:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"трябва да подаде сигнал със съответния пътепоказател","ok":true,"i":null,"es":"debe activar el intermitente correspondiente"},{"t":"трябва да се убеди, че няма да създаде опасност за другите участници в движението","ok":true,"i":null,"es":"debe asegurarse de no crear peligro para otros participantes"},{"t":"трябва да пропусне ППС, които се движат по тази лента","ok":true,"i":null,"es":"debe dejar pasar los vehículos que circulan por ese carril"},{"t":"трябва да пропусне ППС движещи се по нея, само ако тази лента е за насрещното движение","ok":false,"i":null,"es":"debe dejar pasar solo los del carril contrario"}],"f":5,"es":"Antes de desplazarse lateralmente para cambiar de carril, el conductor: (3 correctas)","explain":"Antes de cambiar de carril: intermitente, comprobar que no creas peligro y CEDER a quienes ya circulan por el carril de destino: ellos tienen la prioridad. No se trata del 'carril contrario', sino del carril al que te desplazas.","val":8,"fase":4},{"id":6359,"bg":"Когато мястото за спиране преди жп прелеза се определя по отношение на релсите, разстоянието от първата релса трябва да бъде:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не по-малко от 2 м","ok":true,"i":null,"es":"no menos de 2 m"},{"t":"не повече от 1 м","ok":false,"i":null,"es":"no más de 1 m"},{"t":"не повече от 5 м","ok":false,"i":null,"es":"no más de 5 m"},{"t":"по преценка на водача","ok":false,"i":null,"es":"a criterio del conductor"}],"f":11,"es":"Cuando la posición de parada antes del paso a nivel se determina respecto a los raíles, la distancia debe ser:","explain":"Mínimo 2 m desde el raíl más cercano: garantiza que ninguna parte del vehículo (ni la carga del tren, que sobresale del raíl) pueda tocarte. 'No más de 1 m' te pondría bajo el tren y 'a criterio del conductor' no existe en la norma.","val":17,"fase":3},{"id":6525,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57314.png","v":null,"a":[{"t":"само червения автомобил","ok":true,"i":null,"es":"solo al coche rojo"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"и двата автомобила","ok":false,"i":null,"es":"a los dos coches"}],"f":9,"es":"En esta situación debo dejar pasar:","explain":"Solo al ROJO. El rombo amarillo dice que vas por la vía con prioridad, y vas a girar a la izquierda. El rojo viene de frente por esa misma vía prioritaria: al girar a la izquierda debes cederle el paso. El azul sale de la vía secundaria, así que es él quien te cede a ti. Ojo: ir por la vía con prioridad no te libra de ceder al que viene de frente cuando giras.","val":14,"fase":3},{"id":6539,"bg":"При тази ситуация жълтият автомобил трябва да премине преди синия и червения автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65468.png","v":null,"a":[{"t":"се намира на пътя с предимство","ok":true,"i":null,"es":"está en la vía preferente"},{"t":"се намира от дясната страна на синия автомобил","ok":true,"i":null,"es":"está a la derecha del coche azul"},{"t":"завива надясно","ok":false,"i":null,"es":"gira a la derecha"},{"t":"не напуска пътят с предимство","ok":false,"i":null,"es":"no abandona la vía preferente"}],"f":8,"es":"En esta situación el coche amarillo debe pasar antes que el azul y el rojo porque: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el amarillo tiene prioridad porque está en vía preferente Y porque está a la derecha del azul. Dos razones independientes que se suman.","val":12,"fase":3},{"id":6546,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68490.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al rojo"},{"t":"да пропусна синия автомобил","ok":false,"i":null,"es":"dejar pasar al azul"}],"f":11,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: paso antes que el rojo y antes que el azul. ATENCIÓN, esta pregunta es especial — léela entera.\n\nEL AZUL se entiende sin problema: llega por mi izquierda, así que por la regla de la derecha es él quien me cede a mí.\n\nEL ROJO es el caso raro. Viene de frente siguiendo recto y yo giro a la izquierda. El artículo 37 de la ley dice que quien gira a la izquierda debe ceder el paso a los que vienen en sentido contrario y siguen de frente o giran a la derecha. Por la ley, yo tendría que cederle. Y sin embargo el banco oficial marca 'cedo al rojo' como respuesta FALSA.\n\nEL MOTIVO DE FONDO es que aquí se forma un bucle cerrado de prioridad: yo cedo al rojo, el rojo cede al azul (que cruzando de izquierda a derecha le entra por su derecha), y el azul me cede a mí. Nadie puede arrancar sin que otro ceda primero. La ley búlgara no resuelve estos atascos con una regla: se salen por acuerdo entre conductores.\n\nEN EL EXAMEN marca 'paso antes que los dos'. Es lo que puntúa.\n\nEN LA CARRETERA haz lo contrario: si giras a la izquierda, cede SIEMPRE al que viene de frente. Si hay accidente, el artículo 37 es el que se aplica y responde el que gira. Esta es la única pregunta de las 1487 donde el examen y la práctica no coinciden.","val":17,"fase":3},{"id":6561,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68387.png","v":null,"a":[{"t":"двата автомобила","ok":true,"i":null,"es":"a los dos coches"},{"t":"само синия автомобил","ok":false,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"}],"f":9,"es":"En esta situación el conductor del coche verde debe dejar pasar:","explain":"A los DOS. El verde va a girar a la izquierda para incorporarse a la vía transversal. El azul llega por su derecha, así que por la regla de la derecha le cede. Y el rojo ya circula por la vía a la que el verde quiere entrar, de modo que también pasa primero. Quien se incorpora cede a quien ya está circulando: son dos motivos distintos para el mismo resultado.","val":13,"fase":3},{"id":6569,"bg":"При тази ситуация трябва да пропусна червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68269.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación debo dejar pasar al coche rojo. Esto es:","explain":"⚠️ TRAMPA: la pregunta afirma que debes ceder al rojo, pero es INCORRECTO. Según la imagen eres tú quien tiene prioridad. Lee siempre la situación antes de elegir.","val":12,"fase":3},{"id":6598,"bg":"При тази ситуация преминавам преди синия автомобил защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56819.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":10,"es":"En esta situación paso antes que el coche azul porque voy recto. Esto es:","explain":"INCORRECTO. En mi acceso hay un triángulo invertido de CEDA EL PASO, mirando hacia mí. Con esa señal debo dejar pasar a todos los que circulan por la vía con prioridad, y el azul es uno de ellos. Ir recto no otorga preferencia: la dirección que yo lleve es irrelevante cuando tengo un ceda el paso. Regla: el ceda el paso no se anula por seguir de frente.","val":15,"fase":3},{"id":5378,"bg":"При тази ситуация кой от автомобилите нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41573.png","v":null,"a":[{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":8,"es":"En esta situación ¿qué vehículo incumple las normas de autopista?","explain":"Ambos vehículos infringen alguna norma de autopista en esta imagen. Identifica qué hace mal cada uno (carril incorrecto, velocidad, distancia...).","val":8,"fase":4},{"id":5385,"bg":"На автомагистрала с три пътни ленти за движение в една посока, на водача на състав от ППС с дължина над 7 метра е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено да се движи в най-дясната пътна лента","ok":true,"i":null,"es":"permitido circular en el carril más a la derecha"},{"t":"разрешено да се движи в средната пътна лента","ok":true,"i":null,"es":"permitido circular en el carril central"},{"t":"забранено да се движи в крайната лява лента","ok":true,"i":null,"es":"prohibido circular en el carril más a la izquierda"},{"t":"разрешено да навлиза в крайната лява лента при изпреварване","ok":false,"i":null,"es":"permitido entrar en el carril izquierdo para adelantar"}],"f":9,"es":"En una autopista de 3 carriles, al conductor de un convoy de vehículos le está: (3 correctas)","explain":"En autopista de 3 carriles, un convoy puede usar el carril derecho y el central, pero el IZQUIERDO le está prohibido siempre: ni siquiera para adelantar. Por eso 'entrar en el izquierdo para adelantar' es falsa.","val":9,"fase":4},{"id":5412,"bg":"На автомобилен път спирането за престой е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"само на специално обозначените места за паркиране","ok":true,"i":null,"es":"solo en los lugares señalizados para aparcar"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"en el extremo derecho de la calzada"},{"t":"само извън платното за движение","ok":false,"i":null,"es":"solo fuera de la calzada"},{"t":"най-вдясно на пътното платно","ok":false,"i":null,"es":"en el extremo derecho del firme"}],"f":8,"es":"En vía rápida la parada está permitida:","explain":"Solo en los lugares señalizados para aparcar: en vía rápida no existe la parada 'a la derecha' ni 'fuera de la calzada' por libre. Todo lo que no sea zona habilitada o emergencia real es infracción.","val":8,"fase":4},{"id":5415,"bg":"При движение по автомагистрала на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla incluso donde esté interrumpida"},{"t":"да се движи по лентата за принудително спиране","ok":true,"i":null,"es":"circular por el carril de emergencia"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":9,"es":"Conduciendo por autopista al conductor le está PROHIBIDO: (3 correctas)","explain":"En autopista está prohibido dar la vuelta, entrar o cruzar la mediana (aunque esté interrumpida) y circular por el carril de emergencia. Remolcar con barra rígida un averiado sí está permitido para sacarlo por la salida más próxima.","val":9,"fase":4},{"id":8279,"bg":"Теглене с гъвкава връзка по скоростен път е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само за изтегляне до най-близкото място за напускане на пътя","ok":true,"i":null,"es":"permitido solo para salir por la salida más cercana"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"забранено само в тъмната част от денонощието","ok":false,"i":null,"es":"prohibido solo de noche"}],"f":12,"es":"El remolque con cable flexible en vía rápida está:","explain":"El remolque con cable FLEXIBLE en vía rápida solo está permitido para llegar a la salida más próxima y abandonarla: el cable no da control suficiente a alta velocidad. Ni está permitido sin límites ni prohibido del todo.","val":12,"fase":4},{"id":11712,"bg":"Когато няма други ограничения, водачът на МПС от категория В при движение по скоростен път не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"120 km/h","ok":true,"i":null,"es":"120 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"130 кkm/h","ok":false,"i":null,"es":"130 km/h"}],"f":10,"es":"Sin otras restricciones, el conductor de categoría B en vía rápida puede circular a máximo:","explain":"120 km/h: límite de los turismos categoría B en vía rápida (скоростен път). Ojo a la diferencia con autopista, donde el mismo turismo puede ir a 140 km/h.","val":10,"fase":4},{"id":12067,"bg":"Какво трябва да направите при тази ситуация? Оставам в заеманата лента, като:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":58,"a":[{"t":"се движа в средата на лентата","ok":false,"i":null,"es":"circulo por el centro del carril"},{"t":"се движа възможно най-вдясно","ok":true,"i":null,"es":"circulo todo lo posible a la derecha"},{"t":"се движа възможно най-вляво","ok":false,"i":null,"es":"circulo todo lo posible a la izquierda"}],"f":23,"es":"¿Qué debes hacer en esta situación? Me quedo en mi carril y... (VIDEO)","explain":"En la escena final una moto se abre paso por mi IZQUIERDA entre el tráfico denso de la autovía (camión frenando a la derecha): me quedo en mi carril pero circulando todo lo posible a la DERECHA para dejarle hueco seguro. Por el centro o pegado a la izquierda le cerraría el paso. Regla: cuando una moto filtra o adelanta por un lado, libera ese lado dentro de tu carril.","val":11,"fase":4},{"id":5585,"bg":"При тази ситуация кой от автомобилите е паркиран неправилно?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43351.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"}],"f":8,"es":"En esta situación ¿qué vehículo está aparcado incorrectamente?","explain":"El coche azul infringe alguna norma de aparcamiento en esta imagen — demasiado cerca de una esquina, sobre paso de peatones, o en zona prohibida. Analiza la señalización.","val":4,"fase":4},{"id":6675,"bg":"След кой от тези знаци, при преминаване през кръстовището, трябва да пропуснем ППС, идващи по пътя отдясно?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"55266"},{"t":"","ok":false,"es":"","i":"55265"},{"t":"","ok":true,"es":"","i":"55267"},{"t":"","ok":false,"es":"","i":"55247"}],"f":10,"es":"Después de cuál de estas señales, al cruzar la intersección, debemos ceder el paso a los vehículos que vienen por el camino de la DERECHA?","explain":"La señal de ceder el paso (triángulo invertido) obliga a dejar pasar a los vehículos que vienen por la vía que intersectas. Identifica cuál de las imágenes muestra esa señal.","val":14,"fase":3},{"id":6320,"bg":"Върху маркираната с коси успоредни линии част от платното за движение навлизането е:","p":2,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60183.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibida"},{"t":"разрешено за паркиране","ok":false,"i":null,"es":"permitida para aparcar"},{"t":"разрешено само за спиране за престой","ok":false,"i":null,"es":"permitida solo para parada breve"}],"f":24,"es":"La entrada a la zona marcada con líneas diagonales paralelas está:","explain":"Prohibida: el zebrado diagonal marca superficie vetada al tráfico, sin excepciones de aparcamiento ni parada breve. Misma doctrina que su gemela: la zona rayada es intocable.","val":24,"fase":4},{"id":5850,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/35032.png","v":null,"a":[{"t":"мога да премина направо","ok":true,"i":null,"es":"continuar recto"},{"t":"мога да завия надясно","ok":true,"i":null,"es":"girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"girar en sentido contrario"}],"f":11,"es":"La señal del agente regulador significa que puedo: (2 correctas)","explain":"El conductor ve el COSTADO del agente (el eje de sus hombros/brazos apunta hacia él): es la 'puerta abierta' — permitido seguir RECTO y girar a la DERECHA, las dos correctas. Nunca a la izquierda ni en U: eso cruzaría el flujo que el agente mantiene abierto delante y detrás de sí. Costado = recto y derecha, nada más.","val":16,"fase":3},{"id":5885,"bg":"Значението на този сигнал на регулировчика е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39187.png","v":null,"a":[{"t":"„Внимание, спри!”","ok":true,"i":null,"es":"'¡Atención, para!'"},{"t":"„Премини с повишено внимание”","ok":false,"i":null,"es":"'Pasa con precaución redoblada'"},{"t":"„Внимание”","ok":false,"i":null,"es":"'¡Atención!'"},{"t":"„Пропусни движещите се по пресичания път”","ok":false,"i":null,"es":"'Cede el paso a los que circulan por la vía transversal'"}],"f":11,"es":"El significado de esta señal del agente regulador es:","explain":"Brazo levantado en vertical = «Внимание, спри!» / «¡Atención, para!», el equivalente al amarillo fijo del semáforo: deben detenerse todos los que se acercan, vengan por donde vengan, y solo termina de cruzar quien ya estaba dentro. Aquí ves al agente de frente, pero el punto de vista no cambia nada: es la única señal del regulador que vale idéntica en las cuatro direcciones. Las otras tres te invitan a moverte, y «¡Atención!» a secas tampoco vale porque le falta justo la orden: «спри» = para.","val":17,"fase":3},{"id":6097,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63641.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":7,"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"El coche rojo está correctamente posicionado — circula por el lado derecho de la calzada de forma adecuada según la situación mostrada.","val":11,"fase":3},{"id":6234,"bg":"При тази ситуация с предимство е водачът на автомобила, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69702.png","v":null,"a":[{"t":"се намира отдясно","ok":true,"i":null,"es":"se encuentra a la derecha"},{"t":"се намира отляво","ok":false,"i":null,"es":"se encuentra a la izquierda"},{"t":"първи е подал сигнал за маневра","ok":false,"i":null,"es":"primero señalizó la maniobra"},{"t":"е по-напред от другия","ok":false,"i":null,"es":"está más adelantado que el otro"}],"f":10,"es":"En esta situación tiene prioridad el conductor del vehículo que:","explain":"El de la DERECHA. En un cruce de vías de igual valor decide la regla de la derecha y nada más. Los otros tres suenan razonables y son inventos: venir por la izquierda no da preferencia; señalizar primero la maniobra tampoco (el intermitente avisa, no otorga derechos) y aquí los dos coches lo llevan puesto; y estar más adelantado no es tener prioridad, porque llegar antes no es lo mismo que tener preferencia.","val":14,"fase":3},{"id":6335,"bg":"При тази ситуация преминавам с предимство преди трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70746.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación paso con prioridad antes que el tranvía. Esto es:","explain":"⚠️ TRAMPA: los tranvías tienen prioridad sobre los vehículos de motor en la mayoría de situaciones. Afirmar que tienes prioridad sobre el tranvía es INCORRECTO.","val":11,"fase":3},{"id":6426,"bg":"При изпреварване водачът на изпреварваното ППС длъжен ли е да не увеличава скоростта?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"Al adelantar, ¿está obligado el conductor del vehículo adelantado a no aumentar la velocidad?","explain":"Sí: el adelantado tiene prohibido aumentar la velocidad durante el adelantamiento. Acelerar alargaría la maniobra del otro justo cuando está expuesto en el carril contrario.","val":8,"fase":4},{"id":6433,"bg":"Водач, който изпреварва, е длъжен:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури достатъчно странично разстояние между своето и изпреварваното ППС","ok":true,"i":null,"es":"garantizar distancia lateral suficiente entre su vehículo y el adelantado"},{"t":"когато навлиза в лента за насрещното движение, да не създава опасност за превозните средства, движещи се по нея","ok":true,"i":null,"es":"al invadir el carril contrario, no crear peligro para los vehículos de frente"},{"t":"да се убеди, че с безопасна скорост, може да извърши изпреварването за кратко време","ok":true,"i":null,"es":"asegurarse de que a velocidad segura puede completar el adelantamiento rápidamente"},{"t":"да се движи в непосредствена близост до изпреварваното превозно средство","ok":false,"i":null,"es":"circular muy próximo al vehículo adelantado"}],"f":5,"es":"El conductor que adelanta está obligado a: (3 correctas)","explain":"El que adelanta debe: garantizar distancia lateral suficiente, no crear peligro al tráfico de frente al invadir su carril, y poder completar la maniobra RÁPIDO a velocidad segura. Pegarse al adelantado es lo contrario: elimina la visibilidad y el margen.","val":7,"fase":4},{"id":5896,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48224.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO — la imagen muestra una señal o situación que prohíbe específicamente girar a la derecha en este punto. Puede ser semáforo rojo, señal prohibitiva o agente.","val":13,"fase":3},{"id":6521,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64819.png","v":null,"a":[{"t":"червеният автомобил, защото приближава кръстовището от дясната страна на зеления автомобил","ok":true,"i":null,"es":"el coche rojo, porque se aproxima por la derecha del verde"},{"t":"зеленият автомобил, защото се движи направо","ok":false,"i":null,"es":"el coche verde, porque va recto"},{"t":"червеният автомобил, защото се намира на пътя с предимство","ok":false,"i":null,"es":"el coche rojo, porque está en la vía preferente"}],"f":9,"es":"En esta situación tiene prioridad:","explain":"El ROJO, porque se aproxima por la DERECHA del verde. Fíjate en que la opción que también señala al rojo da un motivo falso — 'porque está en la vía preferente' — y en el examen una respuesta correcta con motivo equivocado sigue siendo errónea. Aquí lo que decide es la posición relativa. Y 'el verde porque va recto' falla dos veces: coche equivocado y motivo inventado.","val":13,"fase":3},{"id":6522,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63240.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En esta situación yo tengo prioridad. Esto es:","explain":"CORRECTO — según la situación mostrada (vía preferente o regla de la derecha) tienes prioridad de paso.","val":10,"fase":3},{"id":6529,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61585.png","v":null,"a":[{"t":"да пропусна трамвая","ok":true,"i":null,"es":"dejar pasar al tranvía"},{"t":"да премина преди лекия автомобил","ok":true,"i":null,"es":"pasar antes que el turismo"},{"t":"да пропусна лекия автомобил","ok":false,"i":null,"es":"dejar pasar al turismo"},{"t":"да премина преди трамвая","ok":false,"i":null,"es":"pasar antes que el tranvía"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el tranvía tiene prioridad sobre ti (debes cederle) PERO tú tienes prioridad sobre el turismo (puedes pasar antes que él). Dos acciones distintas simultáneas.","val":10,"fase":3},{"id":6545,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна червения автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al rojo porque está en vía preferente"},{"t":"да пропусна жълтия автомобил, защото се намира на пътя с предимство","ok":true,"i":null,"es":"dejar pasar al amarillo porque está en vía preferente"},{"t":"да премина преди синия автомобил, защото той завива наляво","ok":false,"i":null,"es":"pasar antes que el azul porque gira a la izquierda"}],"f":11,"es":"En esta situación debo: (2 correctas)","explain":"Cedes a los tres. El rojo y el amarillo porque circulan por la vía con prioridad —esas son las dos correctas— y el azul también, aunque esté girando a la izquierda: girar no le quita la prioridad a quien va por la vía preferente, y tú llegas por la secundaria. Compárala con su gemela 6544, que usa la misma imagen: allí las correctas son ceder al azul y al amarillo, y niega que puedas pasar antes que el rojo. Juntas dicen lo mismo: cedes a todos.","val":17,"fase":3},{"id":6554,"bg":"При тази ситуация пропускам червения автомобил, защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66883.png","v":null,"a":[{"t":"се намира от дясната ми страна","ok":true,"i":null,"es":"está a mi derecha"},{"t":"се движи направо","ok":false,"i":null,"es":"va recto"},{"t":"завивам наляво","ok":false,"i":null,"es":"yo giro a la izquierda"}],"f":10,"es":"En esta situación dejo pasar al coche rojo porque:","explain":"Porque está a MI DERECHA. Cruce de vías de igual valor y sin señales: decide la regla de la derecha, y solo eso. 'Porque va recto' es falso: lo que haga el otro no le da preferencia; si el rojo girara, yo seguiría cediendo por estar a mi derecha. 'Porque giro a la izquierda' también es falso: mi maniobra no crea la obligación. Aunque yo fuera recto, cedería igual. La prioridad la da la POSICIÓN, no el movimiento.","val":15,"fase":3},{"id":6557,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68421.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"al coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"al coche azul"}],"f":10,"es":"En esta situación debo dejar pasar:","explain":"Al ROJO. Está a mi derecha, así que le cedo. El azul está a mi izquierda: es él quien me cede a mí. Es la regla de la derecha aplicada a los dos lados a la vez, y es lo que hace la pregunta: te pone un coche a cada lado para ver si sabes que solo uno de los dos te obliga. Truco: mira de qué lado llega cada uno y olvídate de hacia dónde van.","val":15,"fase":3},{"id":6571,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премина преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el coche azul"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: cedo al AZUL y paso antes que el ROJO. El azul llega por mi derecha, así que tiene preferencia sobre mí. El rojo llega por mi izquierda, así que soy yo quien pasa primero. Un coche a cada lado y solo uno te obliga: mira siempre de qué lado llega cada uno antes de pensar en hacia dónde va.","val":13,"fase":3},{"id":6582,"bg":"При този немигащ сигнал на светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103275.png","v":null,"a":[{"t":"е забранено да премина през кръстовището","ok":true,"i":null,"es":"está prohibido pasar por la intersección"},{"t":"мога да премина, но с повишено внимание","ok":false,"i":null,"es":"puedo pasar pero con precaución"},{"t":"преминаването е разрешено само за пешеходци","ok":false,"i":null,"es":"el paso está permitido solo para peatones"}],"f":6,"es":"Con esta señal fija del semáforo:","explain":"Semáforo rojo fijo = PROHIBIDO entrar en la intersección. No hay excepciones de precaución — es prohibición absoluta.","val":9,"fase":4},{"id":6583,"bg":"При този немигащ сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103326.png","v":null,"a":[{"t":"забранено освен в случаите, когато не можем да спрем, без да създадем опасност за движението","ok":true,"i":null,"es":"prohibido, salvo cuando no se puede parar sin crear peligro para la circulación"},{"t":"разрешено, без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"}],"f":11,"es":"Con esta señal fija del semáforo, entrar en la intersección está:","explain":"Amarillo FIJO (no intermitente): prohibido entrar en el cruce, salvo que ya no puedas detenerte sin crear peligro para la circulación. Esa excepción es toda la pregunta: «prohibido en todos los casos» es falso porque frenar en seco con alguien pegado detrás es más peligroso que continuar. Y no lo confundas con el amarillo intermitente, que significa «pasa con precaución».","val":16,"fase":3},{"id":5369,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41063.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"coche azul"}],"f":10,"es":"En esta situación tiene prioridad el conductor del:","explain":"El rojo tiene prioridad según la imagen — sea por vía preferente, por la derecha o por señalización específica.","val":10,"fase":4},{"id":5399,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"мотоциклети с кош","ok":false,"i":null,"es":"motos con sidecar"},{"t":"автомобили превозващи живи животни","ok":false,"i":null,"es":"vehículos transportando animales vivos"}],"f":9,"es":"En autopista está PROHIBIDA la circulación de: (2 correctas)","explain":"Ciclomotores y tractores no pueden entrar en autopista: demasiado lentos para ese flujo. Las motos CON sidecar sí pueden (son vehículos de motor rápidos) y transportar animales vivos no está prohibido.","val":9,"fase":4},{"id":5402,"bg":"Движението назад по автомагистрала е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibida en todos los casos"},{"t":"разрешено само в лентата за принудително спиране","ok":false,"i":null,"es":"permitida solo en el carril de emergencia"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitida sin restricciones"},{"t":"забранено само през нощта","ok":false,"i":null,"es":"prohibida solo de noche"}],"f":11,"es":"La marcha atrás en autopista está:","explain":"Prohibida en todos los casos: en autopista nunca se circula marcha atrás, ni siquiera por el carril de emergencia. Un vehículo retrocediendo contra tráfico a 130 km/h es de lo más letal que existe en carretera.","val":11,"fase":4},{"id":5405,"bg":"Разрешено ли е водач, който отмине пътния възел за излизане от автомагистрала, да се придвижи обратно назад по лентата за принудително спиране?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"да, ако разстоянието е по-малко от 100 м","ok":false,"i":null,"es":"sí, si la distancia es menos de 100 m"},{"t":"да, ако е с включени аварийни светлини","ok":false,"i":null,"es":"sí, con las luces de emergencia encendidas"}],"f":11,"es":"Si un conductor se pasa la salida de la autopista, ¿puede ir marcha atrás para alcanzarla?","explain":"No: si te pasas la salida, continúas hasta la siguiente. La marcha atrás en autopista está prohibida sin excepciones: ni distancias cortas ni luces de emergencia la legalizan.","val":11,"fase":4},{"id":8282,"bg":"По кой от посочените начини се сигнализира автомобил, спрян върху площадката за принудително спиране на скоростен път, през нощта и при намалена видимост?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с предупредителен светлоотразителен триъгълник","ok":true,"i":null,"es":"con triángulo reflectante de advertencia"},{"t":"с включен авариен сигнал","ok":true,"i":null,"es":"con la señal de avería activada (luces de emergencia)"},{"t":"с включени дълги светлини","ok":false,"i":null,"es":"con las luces largas encendidas"}],"f":9,"es":"¿De qué forma se señaliza el vehículo parado en el área de emergencia de vía rápida? (2 correctas)","explain":"En el área de emergencia el vehículo se señaliza con el triángulo reflectante Y las luces de emergencia: ambos avisan al tráfico que llega. Las luces largas no señalizan nada parado y deslumbrarían de frente.","val":9,"fase":4},{"id":5561,"bg":"Спряното за престой превозно средство трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не спира преминаването на другите превозни средства","ok":true,"i":null,"es":"no impedir el paso a los demás vehículos"},{"t":"да бъде с работещ двигател","ok":false,"i":null,"es":"tener el motor en marcha"},{"t":"да бъде с включени къси светлини","ok":false,"i":null,"es":"tener las luces cortas encendidas"}],"f":12,"es":"El vehículo en parada breve (prestoy) debe:","explain":"En parada breve (престой) la única exigencia de la opción correcta es no impedir el paso de los demás. No hay obligación de mantener el motor en marcha ni las luces cortas encendidas.","val":6,"fase":4},{"id":5571,"bg":"Правилно ли е паркиран товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42806.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está correctamente aparcado el camión?","explain":"SÍ — en la imagen el camión cumple con las normas de aparcamiento según su posición y la señalización del lugar.","val":4,"fase":4},{"id":5600,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43536.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"SÍ — el camión cumple con las condiciones del prestoy en esta imagen.","val":4,"fase":4},{"id":5602,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43503.png","v":null,"a":[{"t":"да, защото е възможно най-вдясно на пътното платно","ok":true,"i":null,"es":"sí, porque está todo lo posible a la derecha de la plataforma vial"},{"t":"не, защото трябва да е извън платното за движение","ok":false,"i":null,"es":"no, porque debe estar fuera de la calzada"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":10,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"CORRECTO — el camión está todo lo posible a la derecha del firme, que es la norma básica del prestoy en carretera sin zona específica señalizada.","val":5,"fase":4},{"id":5731,"bg":"Какво влияние оказва ниското налягане на въздуха в гумите върху поведението на превозното средство?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава управляемостта на превозното средство","ok":true,"i":null,"es":"empeora la manejabilidad del vehículo"},{"t":"увеличава разхода на гориво","ok":true,"i":null,"es":"aumenta el consumo de combustible"},{"t":"не оказва влияние","ok":false,"i":null,"es":"no tiene ningún efecto"}],"f":10,"es":"¿Qué efecto tiene la presión baja de los neumáticos en el comportamiento del vehículo? (2 correctas)","explain":"La presión baja tiene doble efecto: empeora la manejabilidad (neumático que flexa) y aumenta el consumo (más superficie de contacto = más resistencia a la rodadura). No es en absoluto neutra.","val":5,"fase":4},{"id":5736,"bg":"Ако по време на движение при натискане спирачният педал “потъне” и спирачките не се задействат, водачът трябва:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да отпусне бързо педала и пак да го натисне","ok":true,"i":null,"es":"soltar rápido el pedal y volver a pisarlo"},{"t":"да продължи да натиска педала, без да го отпуска","ok":false,"i":null,"es":"seguir pisando sin soltarlo"},{"t":"да натисне педала на съединителя","ok":false,"i":null,"es":"pisar el pedal del embrague"}],"f":9,"es":"Si al frenar el pedal de freno 'se hunde' y los frenos no responden, el conductor debe:","explain":"Si el pedal 'se hunde': suelta rápido y vuelve a pisar (bombear) para recuperar presión hidráulica. Mantenerlo pisado no restaura la presión perdida y el embrague no tiene nada que ver con frenar.","val":4,"fase":4},{"id":6487,"bg":"Този знак:","p":3,"s":"Раздел 4","i":"66215","v":null,"a":[{"t":"указва място за излизане на пешеходците от автомагистрала","ok":false,"i":null,"es":"indica salida de peatones de la autopista"},{"t":"сигнализира авариен изход в тунел","ok":true,"i":null,"es":"señaliza una salida de emergencia en túnel"},{"t":"обозначава вход на пешеходен подлез","ok":false,"i":null,"es":"indica la entrada a un paso subterráneo peatonal"}],"f":8,"es":"Esta señal:","explain":"El hombre corriendo hacia una puerta = SALIDA DE EMERGENCIA en túnel. No es una salida peatonal de autopista ni un paso subterráneo.","val":12,"fase":3},{"id":11604,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123579205.png","v":null,"a":[{"t":"намалена видимост","ok":true,"i":null,"es":"visibilidad reducida"},{"t":"настъпило пътнотранспортно произшествие","ok":false,"i":null,"es":"accidente de tráfico ocurrido"},{"t":"възможна е поява на силен страничен вятър","ok":false,"i":null,"es":"posible viento lateral fuerte"},{"t":"образувано задръстване","ok":false,"i":null,"es":"retención formada"}],"f":7,"es":"Esta señal de tráfico advierte de:","explain":"Esta señal específica advierte de visibilidad reducida — niebla, lluvia intensa o condiciones atmosféricas que limitan la visión.","val":7,"fase":4},{"id":5871,"bg":"Сигналът на регулировчика означава, че е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/37240.png","v":null,"a":[{"t":"разрешено да завия наляво","ok":true,"i":null,"es":"permitido girar a la izquierda"},{"t":"разрешено да премина направо","ok":true,"i":null,"es":"permitido continuar recto"},{"t":"забранено да завия надясно","ok":false,"i":null,"es":"prohibido girar a la derecha"},{"t":"забранено да завия в обратна посока","ok":false,"i":null,"es":"prohibido cambiar de sentido (media vuelta)"}],"f":9,"es":"La señal del agente regulador significa que está: (2 correctas)","explain":"MULTIRESPUESTA: izquierda y recto. El agente tiene el brazo derecho extendido al frente y yo lo veo por su COSTADO IZQUIERDO. Desde ese lado se abre todo: recto, izquierda, derecha y media vuelta. Por eso las otras dos son falsas: dicen que la derecha y la media vuelta están prohibidas, y desde el costado izquierdo ambas están permitidas. Truco: brazo al frente + estás a su izquierda = todas las direcciones.","val":14,"fase":3},{"id":5922,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават, че преминаването е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено","ok":false,"i":null,"es":"permitido"}],"f":13,"es":"La luz roja parpadeante o dos rojas parpadeando alternativamente significa que el paso está:","explain":"Prohibido: la luz roja parpadeante (una o dos alternándose) significa PASO PROHIBIDO: es la señal típica del paso a nivel activado. Roja parpadeando = tren viniendo = ni un metro más.","val":20,"fase":3},{"id":5923,"bg":"Мигащата червена светлина или две последователно мигащи една след друга червени светлини означават:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44332.png","v":null,"a":[{"t":"че преминаването е забранено","ok":true,"i":null,"es":"que el paso está prohibido"},{"t":"че преминаването е разрешено","ok":false,"i":null,"es":"que el paso está permitido"},{"t":"че това е сигнал само за водачите на релсови превозни средства","ok":false,"i":null,"es":"que es una señal solo para conductores de vehículos sobre raíles (tranvías)"},{"t":"„Внимание!”","ok":false,"i":null,"es":"'¡Atención!'"}],"f":11,"es":"La luz roja intermitente, o dos luces rojas que parpadean alternadamente una tras otra, significan:","explain":"Rojo intermitente —o dos rojas parpadeando alternadamente una tras otra— significa paso PROHIBIDO: hay que detenerse antes de la línea. Es el semáforo de los pasos a nivel, puentes móviles, transbordadores y salidas de bomberos, y te obliga a ti aunque no veas venir nada: por eso «solo para vehículos sobre raíles» es falso. La trampa está en «¡Atención!»: ese es el significado del AMARILLO intermitente, no del rojo.","val":17,"fase":3},{"id":6071,"bg":"Кой от автомобилите се движи неправилно по пътното платно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59984.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"и двата автомобила","ok":false,"i":null,"es":"los dos vehículos"}],"f":8,"es":"¿Qué vehículo circula incorrectamente por la calzada?","explain":"El azul circula incorrectamente — probablemente por el carril equivocado, en sentido contrario o demasiado al centro. El rojo sí va bien.","val":12,"fase":3},{"id":6084,"bg":"Кой от автомобилите се движи правилно по този път извън населеното място?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61432.png","v":null,"a":[{"t":"синият автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червеният автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"двата автомобила","ok":false,"i":null,"es":"los dos"}],"f":10,"es":"¿Qué vehículo circula correctamente por esta carretera fuera de población?","explain":"El AZUL. Fuera de población hay que circular lo más a la derecha posible, y el azul lo hace, pegado al borde derecho. El rojo va desplazado hacia el centro sin estar adelantando, y ahí está la infracción: el espacio de la izquierda es para adelantar y volver, no para viajar. 'Los dos' se cae solo: si uno infringe, no pueden ir bien ambos.","val":15,"fase":3},{"id":6435,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64344.png","v":null,"a":[{"t":"трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"debo cambiar al carril derecho"},{"t":"трябва да премина в лявата пътна лента","ok":false,"i":null,"es":"debo cambiar al carril izquierdo"},{"t":"мога да продължа движението си в същата пътна лента","ok":false,"i":null,"es":"puedo continuar en el mismo carril"}],"f":8,"es":"En esta situación:","explain":"Debes cambiar al carril derecho — la señal o la situación mostrada indica que el carril actual termina o está prohibido continuar por él.","val":12,"fase":3},{"id":6449,"bg":"С този пътен знак се обозначава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66102.png","v":null,"a":[{"t":"пътна лента за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"carril exclusivo para transporte público de línea regular"},{"t":"платно за движение само на превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"calzada exclusiva para transporte público de línea regular"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"път за движение само на автобуси","ok":false,"i":null,"es":"camino exclusivo para autobuses"}],"f":8,"es":"Esta señal designa: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: la señal puede designar tanto un carril específico como una calzada completa de uso exclusivo para transporte público regular. No es vía rápida ni solo autobuses.","val":12,"fase":3},{"id":6458,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може водачите на мотопеди да използват за движение пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"пътният банкет да е разположен отдясно по посока на движението им и да е годен за това","ok":true,"i":null,"es":"el arcén debe estar a la derecha en el sentido de marcha y apto para ello"},{"t":"да няма специално предназначена за тях пътна лента","ok":true,"i":null,"es":"no debe haber carril especial destinado a ellos"},{"t":"да не пречат на другите участници в движението","ok":true,"i":null,"es":"no deben molestar a los demás participantes en el tráfico"},{"t":"пътният банкет да е сигнализиран с пътен знак","ok":false,"i":null,"es":"el arcén debe estar señalizado con señal de tráfico"}],"f":10,"es":"¿Qué condiciones deben cumplirse para que los ciclomotores usen el arcén? (3 correctas)","explain":"Tres condiciones para que un ciclomotor use el arcén: que esté a su DERECHA y sea apto, que no exista carril especial para ellos, y que no moleste a los demás. No hace falta que el arcén esté señalizado con ninguna señal.","val":15,"fase":3},{"id":9837,"bg":"При тази ситуация, на водача е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043111.png","v":null,"a":[{"t":"да навлиза в средната пътна лента при изпреварване","ok":true,"i":null,"es":"entrar en el carril central para adelantar"},{"t":"да навлиза в средната пътна лента при заобикаляне","ok":true,"i":null,"es":"entrar en el carril central para rodear un obstáculo"},{"t":"да се движи в най-удобната за него пътна лента","ok":false,"i":null,"es":"circular en el carril más cómodo"},{"t":"да навлизат в крайната лява лента при изпреварване","ok":false,"i":null,"es":"entrar en el carril izquierdo para adelantar"}],"f":7,"es":"En esta situación, al conductor le está PERMITIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: puedes usar el carril central para adelantar Y para rodear obstáculos. El carril izquierdo para adelantar está prohibido aquí. El más cómodo tampoco.","val":10,"fase":3},{"id":6269,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70217.png","v":null,"a":[{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"}],"f":8,"es":"En esta situación debo:","explain":"Debes pasar ANTES que el rojo — según la imagen tienes prioridad sobre él (vía preferente o regla de la derecha a tu favor).","val":11,"fase":3},{"id":6389,"bg":"Този пътен знак сигнализира, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67460.png","v":null,"a":[{"t":"навлизането след него е разрешено, ако пътят е свободен","ok":true,"i":null,"es":"entrar después de ella está permitido si el camino está libre"},{"t":"навлизането след него е забранено","ok":false,"i":null,"es":"entrar después de ella está prohibido"},{"t":"навлизането след него е разрешено във всички случаи","ok":false,"i":null,"es":"entrar está permitido en todos los casos"},{"t":"движението след знака е двупосочно","ok":false,"i":null,"es":"la circulación es bidireccional"}],"f":8,"es":"Esta señal indica que:","explain":"Esta señal (probablemente 'ceda el paso' o similar) permite entrar SOLO si el camino está libre. No es prohibición total pero tampoco permiso incondicional.","val":11,"fase":3},{"id":6417,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"пред пешеходна пътека, когато изпреварваното превозно средство закрива видимостта към пешеходната пътека","ok":true,"i":null,"es":"ante un paso de peatones cuando el vehículo adelantado oculta la visibilidad"},{"t":"на пътища с двупосочно движение","ok":false,"i":null,"es":"en vías con doble sentido de circulación"}],"f":7,"es":"El adelantamiento de vehículos (excepto ciclomotores y motos sin sidecar) está PROHIBIDO: (3 correctas)","explain":"Prohibido adelantar (salvo a ciclomotores y motos sin sidecar): en intersecciones de vías equivalentes, en pasos a nivel SIN barreras y ante pasos de peatones cuando el adelantado te tapa la visibilidad del paso. En vías de doble sentido adelantar es normal y legal.","val":11,"fase":3},{"id":6431,"bg":"Водач, който ще предприеме изпреварване, след като подаде сигнал е длъжен да се убеди, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"има свободен път на разстояние, достатъчно за изпреварване","ok":true,"i":null,"es":"hay vía libre a distancia suficiente para adelantar"},{"t":"може да заеме място в пътната лента пред изпреварваното пътно превозно средство","ok":true,"i":null,"es":"puede ocupar el carril delante del vehículo adelantado"},{"t":"няма да принуждава изпреварваното ППС да намалява скоростта или да изменя посоката на движение","ok":true,"i":null,"es":"no obliga al vehículo adelantado a reducir velocidad ni cambiar de trayectoria"},{"t":"че водачът на изпреварвания автомобил е превключил на по-ниска предавка","ok":false,"i":null,"es":"el conductor adelantado ha puesto una marcha inferior"}],"f":5,"es":"El conductor que va a adelantar, después de señalizar, debe asegurarse de que: (3 correctas)","explain":"Tras señalizar, comprueba: vía libre suficiente, que podrás ocupar hueco DELANTE del adelantado, y que no le obligarás a frenar ni desviarse. Él no tiene por qué reducir marcha ni facilitarte nada activamente.","val":7,"fase":4},{"id":5330,"bg":"При приближаване към кръстовище водачът трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"своевременно да прецени как се определя реда за преминаване през кръстовището","ok":true,"i":null,"es":"evaluar a tiempo cómo se determina el orden de paso"},{"t":"своевременно да заеме пътна лента, която е предназначена за неговата посока на движение","ok":true,"i":null,"es":"ocupar a tiempo el carril correspondiente a su dirección"},{"t":"да има готовност за намаляване на скоростта","ok":true,"i":null,"es":"estar listo para reducir velocidad"},{"t":"да увеличи скоростта за да премине по-бързо през кръстовището","ok":false,"i":null,"es":"acelerar para pasar más rápido"}],"f":9,"es":"Al aproximarse a una intersección el conductor debe: (3 correctas)","explain":"Al aproximarte a un cruce: evalúa a tiempo QUIÉN pasa primero (señales, semáforo, regla de la derecha), ocupa el carril de tu dirección y prepárate para reducir. Acelerar 'para pasar rápido' es exactamente lo contrario de la conducción defensiva.","val":13,"fase":3},{"id":5894,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48207.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":10,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"NO. En el poste de la derecha hay una señal circular AZUL con flecha blanca hacia arriba: 'solo recto'. Es señal de obligación, y obligar a seguir recto equivale a prohibir el giro. Encima lleva el triángulo invertido de ceda el paso, que regula la prioridad, no la dirección. Truco: azul redonda = lo que DEBES hacer; la dirección que no dibuja la flecha, no se toma.","val":15,"fase":3},{"id":5926,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48294.png","v":null,"a":[{"t":"от пътните знаци относно предимството","ok":true,"i":null,"es":"las señales de prioridad"},{"t":"с правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"f":7,"es":"El orden de paso de estos vehículos en la intersección lo determinan:","explain":"Cuando hay señales de prioridad (vía preferente, ceda el paso) éstas determinan el orden. La regla de la derecha solo aplica cuando NO hay señalización.","val":11,"fase":3},{"id":5942,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51152.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с предписанията на пътните знаци относно предимството","ok":false,"i":null,"es":"las señales de prioridad"}],"f":7,"es":"En esta situación al pasar por la intersección debes atenerte a:","explain":"El agente regulador tiene prioridad absoluta sobre todo lo demás — semáforos y señales incluidas. Cuando hay agente, solo obedeces al agente.","val":11,"fase":3},{"id":5945,"bg":"При тази ситуация редът за преминаване на автомобилите през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51266.png","v":null,"a":[{"t":"от сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente regulador"},{"t":"от сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"},{"t":"с „правилото на десния”","ok":false,"i":null,"es":"la regla de la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de marcha de los vehículos"}],"f":11,"es":"En esta situación el orden de paso en la intersección lo determinan:","explain":"Hay un regulador dirigiendo el cruce: mandan sus señales y anulan todo lo demás. Memoriza la jerarquía en este orden: agente > semáforo > señales verticales > marcas viales. Por eso el semáforo que ves en la imagen no decide nada mientras el agente esté ahí, y tampoco la regla de la derecha ni hacia dónde vaya cada coche.","val":17,"fase":3},{"id":6351,"bg":"Как ще сигнализирате през нощта, за да спрете влака, ако автомобилът, който управлявате, поради повреда остане върху релсите?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"с кръгово движение на ръката, в която се държи запалена факла или фенер","ok":true,"i":null,"es":"con movimiento circular del brazo sosteniendo una antorcha o linterna encendida"},{"t":"със запален до релсите огън","ok":false,"i":null,"es":"con un fuego encendido junto a los raíles"},{"t":"с вдигната ръка, в която се държи привличащ вниманието предмет","ok":false,"i":null,"es":"con el brazo levantado sosteniendo un objeto llamativo"},{"t":"със светлоотразителна стоп-палка","ok":false,"i":null,"es":"con pala reflectante de stop"}],"f":8,"es":"¿Cómo señalizarás de noche para detener el tren si tu vehículo está averiado en el paso a nivel?","explain":"De noche el tren se detiene con el movimiento CIRCULAR del brazo sosteniendo antorcha o linterna ENCENDIDA: el maquinista necesita ver luz en movimiento circular. Un fuego junto a los raíles o un objeto sin luz no son la señal reglamentaria.","val":11,"fase":3},{"id":6469,"bg":"Как трябва да постъпите при тази ситуация, ако водачът на синия автомобил, който трябва да ви пропусне, не показва с действията си, че ще спре?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53047.png","v":null,"a":[{"t":"трябва да намаля скоростта","ok":true,"i":null,"es":"debo reducir velocidad"},{"t":"трябва да управлявам с готовност за спиране","ok":true,"i":null,"es":"debo circular listo para frenar"},{"t":"не съм длъжен да се съобразявам с него, защото съм с предимство","ok":false,"i":null,"es":"no tengo que considerarlo porque tengo prioridad"}],"f":8,"es":"¿Cómo debes actuar en esta situación si el conductor del coche azul, que debe cederte el paso, no muestra con sus acciones que vaya a parar? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: incluso teniendo prioridad, si el otro no cede DEBES reducir velocidad Y circular listo para frenar. La prioridad no es excusa para ignorar el peligro real.","val":12,"fase":3},{"id":6531,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/61976.png","v":null,"a":[{"t":"само трамвая","ok":true,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"},{"t":"двете превозни средства","ok":false,"i":null,"es":"a los dos vehículos"}],"f":13,"es":"En esta situación debo dejar pasar:","explain":"Solo al TRANVÍA: el tranvía tiene prioridad sobre los no ferroviarios en vías equivalentes: siempre le cedes. Al coche no le debes paso en esta configuración: cederle a él también sería un error de examen (por eso 'a los dos' es falsa).","val":19,"fase":3},{"id":6540,"bg":"При тази ситуация водачът на зеления автомобил трябва да пропусне:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68541.png","v":null,"a":[{"t":"само синия автомобил","ok":true,"i":null,"es":"solo al coche azul"},{"t":"само червения автомобил","ok":false,"i":null,"es":"solo al coche rojo"},{"t":"двата автомобила","ok":false,"i":null,"es":"a los dos coches"}],"f":11,"es":"En esta situación el conductor del coche verde debe dejar pasar:","explain":"Solo al AZUL. Cruce de vías de igual valor, sin señales de prioridad ni semáforo: manda la regla de la derecha. El azul llega por la derecha del verde, así que el verde le cede. El rojo llega por su izquierda, así que es el rojo quien cede. Que el verde lleve puesto el intermitente izquierdo no cambia nada: girar a la izquierda no obliga a ceder a quien viene por tu izquierda. 'A los dos' es el cebo para quien cree que girar obliga a cederlo todo.","val":17,"fase":3},{"id":6581,"bg":"След подаването на този сигнал от светофара:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103424.png","v":null,"a":[{"t":"навлизането в кръстовището е забранено","ok":true,"i":null,"es":"está prohibido entrar en la intersección"},{"t":"трябва да се подготвя за потегляне","ok":true,"i":null,"es":"debo prepararme para arrancar"},{"t":"може да завия надясно, но с повишено внимание","ok":false,"i":null,"es":"se puede girar a la derecha con precaución"},{"t":"навлизането в кръстовището е разрешено","ok":false,"i":null,"es":"está permitido entrar en la intersección"}],"f":6,"es":"Después de esta señal del semáforo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: semáforo rojo + amarillo simultáneos = prohibido entrar AUN Y debes prepararte para arrancar. Es la fase previa al verde — no puedes pasar todavía.","val":9,"fase":3},{"id":6589,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56379.png","v":null,"a":[{"t":"трябва да спра, преди да премина през кръстовището","ok":true,"i":null,"es":"debo parar antes de cruzar la intersección"},{"t":"мога да премина, без да спирам, но трябва да пропусна ППС от другия път","ok":false,"i":null,"es":"puedo pasar sin parar pero cediendo el paso"},{"t":"мога да премина без да спирам, ако няма други ППС","ok":false,"i":null,"es":"puedo pasar sin parar si no hay otros vehículos"}],"f":12,"es":"En esta situación:","explain":"En la escena hay señal Б2 (STOP): obliga a DETENERSE por completo antes de entrar al cruce, siempre, aunque no venga nadie. Por eso la B es falsa (cruzar cediendo sin parar solo vale con Б1 'ceda el paso') y la C también: que no haya otros vehículos no elimina la obligación — el STOP exige detención incondicional y después ceder a los del camino con prioridad.","val":18,"fase":3},{"id":6595,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57101.png","v":null,"a":[{"t":"лекият автомобил, защото се движи по пътя с предимство","ok":true,"i":null,"es":"el turismo porque circula por la vía preferente"},{"t":"мотоциклетистът, защото се намира от дясната страна на лекия автомобил","ok":false,"i":null,"es":"el motorista porque está a la derecha del turismo"},{"t":"мотоциклетистът, защото се движи направо","ok":false,"i":null,"es":"el motorista porque va recto"}],"f":11,"es":"En esta situación tiene prioridad:","explain":"Tiene prioridad el turismo porque circula por la vía con prioridad: el rombo amarillo que ves en el cruce vence a las otras dos razones que ofrece la pregunta. Estar a la derecha solo decide cuando las dos vías son del mismo rango; si una tiene prioridad señalizada, la regla de la derecha ni se aplica. E ir recto no da prioridad por sí mismo: es la trampa más repetida del examen (la misma de la 6543).","val":16,"fase":3},{"id":6668,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54674.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy una señal acústica o luminosa de que voy a pasar"}],"f":10,"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"MULTIRESPUESTA. El brazo levantado en vertical significa '¡Atención, alto!' y detiene a todos. Solo se salvan dos casos: quien ya tenía el paso autorizado antes de esa señal, y quien está tan cerca que no puede detenerse con seguridad. Dar una señal acústica o luminosa no autoriza nada: avisar no es tener derecho. El brazo en alto no es 'prepárate', es 'párate'.","val":15,"fase":3},{"id":5350,"bg":"Автомагистралата е път:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"по който действат специални правила за движение","ok":true,"i":null,"es":"en la que rigen reglas especiales de circulación"},{"t":"предназначен за движение с високи скорости","ok":true,"i":null,"es":"destinada a la circulación a alta velocidad"},{"t":"по който движението се извършва без ограничение на скоростта","ok":false,"i":null,"es":"por la que se circula sin límite de velocidad"}],"f":8,"es":"La autopista es una vía: (2 correctas)","explain":"La autopista se define por dos rasgos: reglas especiales de circulación y diseño para ALTA velocidad. Pero alta velocidad no significa ilimitada: el límite general es 140 km/h para turismos.","val":8,"fase":4},{"id":5375,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41441.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":12,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"INCORRECTA — el vehículo no está correctamente posicionado respecto a los carriles o el lado correcto de la calzada en esta imagen.","val":12,"fase":4},{"id":5380,"bg":"Кое от превозните средства нарушава правилата за движение по автомагистрала?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41655.png","v":null,"a":[{"t":"и трите превозни средства","ok":true,"i":null,"es":"los tres vehículos"},{"t":"само тракторът","ok":false,"i":null,"es":"solo el tractor"},{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"}],"f":12,"es":"¿Qué vehículo incumple las normas de autopista?","explain":"Los tres infringen — cada uno por una razón diferente (carril incorrecto, vehículo prohibido en autopista, etc.).","val":12,"fase":4},{"id":5419,"bg":"Разрешено ли е лентата за принудително спиране на автомагистрала да се използва за движение при теглене на повредено МПС?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, когато се тегли с гъвкава връзка","ok":false,"i":null,"es":"sí, cuando se remolca con cable flexible"},{"t":"да, но само през нощта","ok":false,"i":null,"es":"sí, pero solo de noche"},{"t":"да, но само при теглене с твърда връзка","ok":false,"i":null,"es":"sí, pero solo remolcando con barra rígida"}],"f":9,"es":"¿Está permitido usar el carril de emergencia de autopista para circular cuando hay retención?","explain":"No: el carril de emergencia se reserva para emergencias reales y vehículos prioritarios. Usarlo para saltarse una retención está prohibido a cualquier hora y con cualquier tipo de remolcado.","val":9,"fase":4},{"id":6707,"bg":"С този пътен знак се обозначава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40609.png","v":null,"a":[{"t":"автомагистрала","ok":true,"i":null,"es":"autopista"},{"t":"автомобилен път","ok":false,"i":null,"es":"vía rápida"},{"t":"път, за движение само на леки автомобили","ok":false,"i":null,"es":"vía solo para turismos"},{"t":"пътен възел","ok":false,"i":null,"es":"nudo de autopista"}],"f":10,"es":"Esta señal designa:","explain":"Esta señal específica (azul con silueta de autopista) designa AUTOPISTA. La vía rápida tiene una señal diferente. No confundirlas.","val":10,"fase":4},{"id":7792,"bg":"При навлизане на автомагистрала задължени ли сте да пропуснете превозните средства, които се движат по нея?","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато има пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"sí, pero solo cuando hay señal de ceda el paso"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"Al entrar en autopista ¿está obligado a ceder el paso a los vehículos que circulan por ella?","explain":"Sí, en todos los casos: al incorporarte a la autopista cedes el paso a quienes ya circulan, exista o no señal de ceda. El carril de aceleración es para igualar velocidad y entrar sin estorbar, no para reclamar hueco.","val":9,"fase":4},{"id":11351,"bg":"При движение по скоростен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън обозначените за това места","ok":true,"i":null,"es":"parar fuera de lugares señalizados para ello"},{"t":"да пресича разделителната ивица, включително на местата, където тя е прекъсната","ok":true,"i":null,"es":"cruzar la mediana incluso donde esté interrumpida"},{"t":"да се движи в платното за насрещно движение","ok":true,"i":null,"es":"circular por el carril contrario"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para eliminar una avería del vehículo"}],"f":12,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"En vía rápida está prohibido: parar fuera de los lugares señalizados, cruzar la mediana (incluso interrumpida) y circular por el carril contrario. Parar para reparar una avería NO está prohibido: la avería es precisamente la excepción de fuerza mayor.","val":12,"fase":4},{"id":11718,"bg":"Когато еднопосочното платно на автомагистрала е с две пътни ленти за движение в една посока, в лявата лента движението е разрешено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"когато дясната пътна лента е заета","ok":true,"i":null,"es":"cuando el carril derecho está ocupado"},{"t":"при изпреварване","ok":true,"i":null,"es":"para adelantar"},{"t":"винаги, когато лентата е свободна","ok":false,"i":null,"es":"siempre que esté libre"},{"t":"само когато е разрешено движение със скорост над 90 km/h","ok":false,"i":null,"es":"solo con velocidad permitida superior a 90 km/h"}],"f":8,"es":"Cuando la calzada de autopista tiene dos carriles en un sentido, el carril izquierdo puede usarse: (2 correctas)","explain":"Con dos carriles por sentido, el izquierdo se usa para adelantar y cuando el derecho está ocupado. No es un carril de crucero 'si está libre': la regla base es circular por la derecha. La velocidad no da derecho al carril izquierdo.","val":8,"fase":4},{"id":5570,"bg":"Правилно ли е спрян за престой товарният автомобил?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42773.png","v":null,"a":[{"t":"да, защото е извън платното за движение","ok":true,"i":null,"es":"sí, porque está fuera de la calzada"},{"t":"не, защото е паркиран след знак, който забранява изпреварването","ok":false,"i":null,"es":"no, porque está parado después de señal que prohíbe adelantar"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":7,"es":"¿Está el camión correctamente detenido para una parada breve?","explain":"SÍ — estar fuera de la calzada es la condición correcta para el prestoy en carretera. Las señales de adelantamiento no afectan al prestoy.","val":3,"fase":4},{"id":5575,"bg":"Престоят от лявата страна на еднопосочните улици в населените места е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешен, ако не се пречи на движението на ППС","ok":true,"i":null,"es":"está permitida si no se obstaculiza la circulación"},{"t":"забранен","ok":false,"i":null,"es":"está prohibida"},{"t":"разрешен без ограничение","ok":false,"i":null,"es":"está permitida sin restricciones"},{"t":"разрешен, но само за товарно-разтоварна дейност","ok":false,"i":null,"es":"está permitida solo para carga y descarga"}],"f":6,"es":"La parada breve (prestoy) en el lado izquierdo de calles de sentido único en población:","explain":"En calle de sentido único la parada breve en el lado izquierdo está permitida SI no obstaculiza la circulación: esa condición es la clave. Ni prohibida, ni libre sin condiciones, ni limitada a carga y descarga.","val":3,"fase":4},{"id":5678,"bg":"Разрешено ли е допълнителните светлини за мъгла да се използват самостоятелно?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":5,"es":"¿Está permitido usar las luces antiniebla traseras de forma independiente?","explain":"No: la antiniebla trasera no se usa de forma independiente: solo acompaña al alumbrado normal y únicamente con visibilidad muy reducida. Sola confundiría (parece luz de freno permanente) y deslumbra al que sigue.","val":2,"fase":4},{"id":12068,"bg":"При тази ситуация трябва да намалите скоростта и да управлявате с готовност за спиране заради:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":59,"a":[{"t":"синия автомобил","ok":false,"i":null,"es":"el coche azul"},{"t":"зеления автомобил","ok":true,"i":null,"es":"el coche verde"},{"t":"трактора","ok":false,"i":null,"es":"el tractor"}],"f":10,"es":"En esta situación debes reducir la velocidad y conducir con disposición de frenar por: (VIDEO)","explain":"Nieve intensa y visibilidad reducida: el peligro es el coche VERDE que asoma por la derecha hacia mi trayectoria — reduzco y conduzco listo para frenar por él, porque en nieve la distancia de frenado se multiplica. El coche azul sigue por su carril sin cortar mi camino y el tractor no interfiere: distractores. En invierno, vigila al que ENTRA en tu trayectoria, no solo al que ya circula en ella.","val":5,"fase":4},{"id":5710,"bg":"Движението при едни и същи условия, по ежедневно използван маршрут:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"води до привикване с пътната обстановка","ok":true,"i":null,"es":"lleva a familiarizarse con la situación vial"},{"t":"води до отслабване на вниманието при пътуването","ok":true,"i":null,"es":"lleva a la relajación de la atención durante el trayecto"},{"t":"позволява на водача да се движи безопасно, със скорост по-висока от разрешената","ok":false,"i":null,"es":"permite circular con seguridad a velocidad superior a la permitida"}],"f":8,"es":"Conducir diariamente por la misma ruta en condiciones idénticas: (2 correctas)","explain":"La ruta diaria idéntica familiariza con la situación Y relaja la atención: conduces 'en automático'. Lo que jamás justifica es superar el límite de velocidad: conocer la ruta no la hace más segura a más velocidad.","val":4,"fase":4},{"id":5714,"bg":"Причина за по-бързото настъпване на умора у водача на МПС са:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"неправилната стойка на тялото по време на управлението","ok":true,"i":null,"es":"la postura incorrecta del cuerpo al conducir"},{"t":"разговорите с пътниците в автомобила","ok":false,"i":null,"es":"las conversaciones con los pasajeros"},{"t":"рекламните пана край пътя","ok":false,"i":null,"es":"los paneles publicitarios junto a la carretera"}],"f":8,"es":"Una causa de fatiga más rápida en el conductor es:","explain":"La postura incorrecta al volante fatiga más rápido: músculos en tensión constante y circulación dificultada. Conversar o ver carteles son distracciones, pero no causas fisiológicas de fatiga.","val":4,"fase":4},{"id":5723,"bg":"Превозването на предмети върху покрива на автомобила води до:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"увеличаване на разхода на гориво","ok":true,"i":null,"es":"aumentar el consumo de combustible"},{"t":"увеличаване на устойчивостта на автомобила в завой","ok":false,"i":null,"es":"aumentar la estabilidad en curva"},{"t":"увеличаване на стабилността на автомобила при страничен вятър","ok":false,"i":null,"es":"aumentar la estabilidad con viento lateral"}],"f":8,"es":"Transportar objetos sobre el techo del coche lleva a:","explain":"La carga en el techo aumenta el consumo (resistencia aerodinámica) y además SUBE el centro de gravedad: peor estabilidad en curva y con viento lateral, no mejor. Solo la opción del consumo es correcta.","val":4,"fase":4},{"id":5726,"bg":"Разрешено ли е зареждането с гориво да се извършва при работещ двигател на автомобила?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido repostar combustible con el motor en marcha?","explain":"No: se reposta con el motor APAGADO. Un motor en marcha junto a vapores de combustible es fuente de ignición (chispas, calor del escape).","val":4,"fase":4},{"id":5732,"bg":"Оказва ли влияние върху управляемостта на превозното средство намаленото налягане на въздуха в гумите?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"¿La presión baja de los neumáticos afecta a la manejabilidad del vehículo?","explain":"Sí: la presión baja deforma el neumático y degrada la respuesta de la dirección. Es de las preguntas más directas del bloque de mantenimiento.","val":4,"fase":4},{"id":5735,"bg":"Как влияе пониженото налягане на въздуха в автомобилните гуми върху разхода на гориво?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"увеличава го","ok":true,"i":null,"es":"lo aumenta"},{"t":"намалява го","ok":false,"i":null,"es":"lo reduce"},{"t":"не оказва влияние","ok":false,"i":null,"es":"no tiene efecto"}],"f":7,"es":"¿Cómo afecta la presión baja de los neumáticos al consumo de combustible?","explain":"Lo aumenta: el neumático con poca presión se deforma más, tiene más resistencia a la rodadura y el motor gasta más para el mismo avance.","val":4,"fase":4},{"id":11637,"bg":"При предстоящо пътуване на дълго разстояние придвижването ще бъде по-безопасно и улеснено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"ако предварително изберем маршрут","ok":true,"i":null,"es":"si elegimos la ruta con antelación"},{"t":"ако предварително планираме подходящи места за спиране за почивка","ok":true,"i":null,"es":"si planificamos paradas de descanso adecuadas"},{"t":"ако придвижването се извършва с по-малко спирания","ok":false,"i":null,"es":"si hacemos las menos paradas posibles"},{"t":"ако движението се извършва през нощта","ok":false,"i":null,"es":"si viajamos de noche"}],"f":11,"es":"Para un viaje largo la conducción será más segura y fácil: (2 correctas)","explain":"Viaje largo más seguro: ruta elegida con antelación y paradas de descanso planificadas. Minimizar paradas acumula fatiga y viajar de noche añade sueño y menos visibilidad: justo lo contrario.","val":6,"fase":4},{"id":5198,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334669.png","v":null,"a":[{"t":"платно за движение, стеснено отдясно","ok":true,"i":null,"es":"calzada estrecha por la derecha"},{"t":"опасен пътен банкет отдясно","ok":false,"i":null,"es":"arcén peligroso a la derecha"},{"t":"крайпътен обект отдясно","ok":false,"i":null,"es":"instalación junto a la carretera a la derecha"},{"t":"намаляване на броя на пътните ленти","ok":false,"i":null,"es":"reducción del número de carriles"}],"f":4,"es":"Esta señal advierte de:","explain":"Esta señal específica advierte de calzada que se estrecha por el lado derecho. No es arcén peligroso ni reducción de carriles — el estrechamiento es de la calzada.","val":4,"fase":4},{"id":9856,"bg":"На кръстовище, на пешеходците е разрешено да преминават през платното за движение по продължението на тротоара:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270044567.png","v":null,"a":[{"t":"когато продължението е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento está marcado con líneas"},{"t":"когато продължението не е очертано с пътна маркировка","ok":true,"i":null,"es":"cuando el prolongamiento NO está marcado"},{"t":"само когато това е указано с пътен знак","ok":false,"i":null,"es":"solo cuando lo indica una señal"},{"t":"само когато продължението е очертано с пътна маркировка тип “Зебра”","ok":false,"i":null,"es":"solo cuando está marcado tipo 'cebra'"}],"f":5,"es":"En intersección, los peatones pueden cruzar por el prolongamiento de la acera: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: los peatones pueden cruzar tanto si hay marcas como si no las hay. La señal específica o el paso de cebra no son requisitos — el prolongamiento de la acera siempre existe.","val":5,"fase":4},{"id":6068,"bg":"Когато пешеходец подава сигнал с ръка за намерението си да премине по пешеходна пътека, водачът на МПС:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"е длъжен да го пропусне без да създава опасност за движението","ok":true,"i":null,"es":"está obligado a dejarlo pasar sin crear peligro"},{"t":"е длъжен незабавно да спре","ok":false,"i":null,"es":"debe detenerse inmediatamente"},{"t":"не е длъжен да се съобразява с него","ok":false,"i":null,"es":"no tiene que considerarlo"},{"t":"трябва да подаде сигнал, към пешеходеца, че ще го пропусне","ok":false,"i":null,"es":"debe señalizar al peatón que va a cederle el paso"}],"f":5,"es":"Cuando un peatón señala con la mano su intención de cruzar por el paso de peatones, el conductor:","explain":"Cuando el peatón señala su intención de cruzar por el paso, debes DEJARLO PASAR sin crear peligro: reduce y cede con suavidad. 'Detenerse inmediatamente' (frenazo) crearía peligro para el que te sigue, e ignorarlo es infracción grave.","val":5,"fase":4},{"id":12022,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":10,"a":[{"t":"изчаквам преминаването на велосипедиста, за да осигуря достатъчно странично разстояние до него","ok":true,"i":null,"es":"espero al ciclista para garantizar distancia lateral suficiente"},{"t":"продължавам движението си, като намалявам скоростта си","ok":false,"i":null,"es":"continúo reduciendo velocidad"},{"t":"продължавам движението си, без да променям скоростта си","ok":false,"i":null,"es":"continúo sin cambiar velocidad"}],"f":5,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"Calle estrecha adoquinada con un todoterreno blanco estacionado a la derecha y un ciclista delante: si lo adelantara ahora no podría dejarle la separación lateral suficiente en el estrechamiento. Lo correcto es ESPERAR a que el ciclista pase el punto crítico y adelantar solo cuando pueda garantizar esa distancia. Reducir o mantener velocidad sin resolver la separación lateral no protege al ciclista.","val":5,"fase":4},{"id":5837,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че може да премине направо или да завие надясно?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24081.png","v":null,"a":[{"t":"на червения автомобил","ok":true,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":true,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":false,"i":null,"es":"para el coche azul"}],"f":10,"es":"¿Para qué conductores esta posición del cuerpo y los brazos del agente significa que pueden seguir recto o girar a la derecha? (2 correctas)","explain":"MULTIRESPUESTA: el ROJO y el VERDE. Con los brazos BAJADOS, el agente autoriza a pasar recto o girar a la derecha a quienes lo ven DE PERFIL, por su costado izquierdo o derecho. Rojo y verde están en ese eje: ambos le ven de lado. El amarillo y el azul están en el eje perpendicular, de frente al pecho y a la espalda, y para ellos los brazos bajados significan alto. Regla: brazos bajados = pasan los de los costados, se paran los del pecho y la espalda.","val":15,"fase":3},{"id":5841,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, че преминаването е забранено във всички посоки?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/24340.png","v":null,"a":[{"t":"на жълтия автомобил","ok":true,"i":null,"es":"para el coche amarillo"},{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"}],"f":13,"es":"¿Para qué conductores la señal del agente significa paso PROHIBIDO? (2 correctas)","explain":"Prohibido para el AMARILLO y el AZUL: ven el pecho o la espalda del agente = rojo. El rojo y el verde le ven los costados = verde. Es la misma doctrina de la 5839 preguntada desde el lado contrario: domina ambas direcciones.","val":20,"fase":3},{"id":5847,"bg":"Сигналът на регулировчика означава, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/25090.png","v":null,"a":[{"t":"преминаването ми е забранено","ok":true,"i":null,"es":"me está PROHIBIDO pasar"},{"t":"мога да завия надясно","ok":false,"i":null,"es":"puedo girar a la derecha"},{"t":"мога да завия наляво","ok":false,"i":null,"es":"puedo girar a la izquierda"},{"t":"мога да завия в обратна посока","ok":false,"i":null,"es":"puedo dar la vuelta"}],"f":11,"es":"La señal del agente regulador significa que:","explain":"El agente está de cara al conductor con el brazo en alto: la mano levantada significa '¡Atención!' — paso prohibido para TODOS, vengan de donde vengan (solo termina de cruzar quien ya está dentro de la intersección). Con esta señal no existe dirección permitida: ni derecha, ni izquierda, ni giro en U. Brazo en alto = alto total.","val":17,"fase":3},{"id":5857,"bg":"За кой от водачите, това положение на тялото и ръцете на регулировчика е сигнал, значението на който е „Преминаването е разрешено”?","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/36480.png","v":null,"a":[{"t":"на синия автомобил","ok":true,"i":null,"es":"para el coche azul"},{"t":"на червения автомобил","ok":false,"i":null,"es":"para el coche rojo"},{"t":"на зеления автомобил","ok":false,"i":null,"es":"para el coche verde"},{"t":"на жълтия автомобил","ok":false,"i":null,"es":"para el coche amarillo"}],"f":11,"es":"¿Para qué conductor esta posición del cuerpo y los brazos del agente regulador significa 'Paso PERMITIDO'?","explain":"El coche AZUL ve el COSTADO del agente: para él el paso está PERMITIDO (recto o derecha). Rojo, verde y amarillo le ven el pecho o la espalda = 'muro', prohibido. Método para toda la familia 5834–5869: traza el eje de los hombros del agente; los coches situados sobre ese eje pasan, los perpendiculares a él esperan.","val":17,"fase":3},{"id":5925,"bg":"При тази ситуация сигналът от бавно мигаща светлина с луннобял цвят указва на участниците в движението, че:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44495.png","v":null,"a":[{"t":"светофарната уредба е в изправност","ok":true,"i":null,"es":"el semáforo está en funcionamiento correcto"},{"t":"е забранено преминаването през прелеза","ok":false,"i":null,"es":"está prohibido cruzar el paso"},{"t":"бариерите ще започнат да се спускат","ok":false,"i":null,"es":"las barreras empezarán a bajar"},{"t":"че към прелеза се приближава влак","ok":false,"i":null,"es":"se aproxima un tren"}],"f":12,"es":"En esta situación la señal de luz blanca parpadeante lenta indica a los participantes en el tráfico que:","explain":"La luz blanca lenta parpadeante del semáforo ferroviario dice: 'el sistema FUNCIONA correctamente y el paso está libre'. No prohíbe, no anuncia tren ni barreras: es la confirmación tranquilizadora. Blanca lenta = todo bien; roja = tren.","val":18,"fase":3},{"id":6495,"bg":"Водачът на бавнодвижещо се пътно превозно средство задължително се движи в най-дясната пътна лента, освен при:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"завиване","ok":true,"i":null,"es":"girar"},{"t":"заобикаляне","ok":true,"i":null,"es":"rodear un obstáculo"},{"t":"изпреварване","ok":false,"i":null,"es":"adelantar"}],"f":6,"es":"El conductor de vehículo lento circula obligatoriamente en el carril más a la derecha, EXCEPTO para: (2 correctas)","explain":"El vehículo lento va obligatoriamente por el carril derecho, EXCEPTO para girar y para rodear un obstáculo. Adelantar no es excepción válida para él: si es lento, en principio no adelanta.","val":9,"fase":3},{"id":9839,"bg":"На двулентов път с двупосочно движение навлизането в лентата за насрещно движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043211.png","v":null,"a":[{"t":"разрешено при изпреварване","ok":true,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":true,"i":null,"es":"permitido para rodear un obstáculo"},{"t":"забранено във всички случаи","ok":false,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено винаги, когато е свободна","ok":false,"i":null,"es":"permitido siempre que esté libre"}],"f":11,"es":"En vía de dos carriles con doble sentido, entrar en el carril contrario está: (2 correctas)","explain":"MULTIRESPUESTA. Solo puedes pisar el carril contrario para dos maniobras concretas: ADELANTAR y RODEAR un obstáculo. 'Prohibido en todos los casos' es falso: si lo fuera, no existiría el adelantamiento. Y 'siempre que esté libre' es el error de fondo: que esté libre no es una maniobra. El carril contrario no es un carril de uso general que puedas ocupar por comodidad.","val":17,"fase":3},{"id":11585,"bg":"На път с три пътни ленти за движение в една посока, указани с пътен знак, в крайната лява лента е забранено движението на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65145.png","v":null,"a":[{"t":"превозни средства, които не могат да развиват максималната за пътя скорост","ok":true,"i":null,"es":"por vehículos que no pueden alcanzar la velocidad máxima de esa vía"},{"t":"превозни средства, на които е забранено да развиват разрешената за пътя максимална скорост","ok":true,"i":null,"es":"por vehículos a los que está prohibido circular a la velocidad máxima"},{"t":"превозни средства, водачите на които са със стаж по-малко от 1 година","ok":false,"i":null,"es":"por vehículos cuyos conductores tienen menos de 1 año de permiso"}],"f":8,"es":"En vía de 3 carriles en un sentido señalizados, el carril izquierdo NO puede usarse: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril izquierdo está prohibido para los que no pueden alcanzar la velocidad máxima Y para los que tienen prohibida esa velocidad. El tiempo de permiso no es criterio.","val":12,"fase":3},{"id":11684,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62168.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"лентите за двиние да са обозначени с пътна маркировка","ok":true,"i":null,"es":"los carriles están marcados con señalización horizontal"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"общата маса на превозното средство да е не повече от 3,5 тона","ok":false,"i":null,"es":"la masa total del vehículo no supera 3.5 toneladas"}],"f":13,"es":"¿Qué condiciones deben cumplirse para que en zona urbana se pueda circular por carriles distintos al derecho? (3 correctas)","explain":"Para circular en ciudad por carriles distintos del derecho: dos o más carriles por sentido, marcados con señalización horizontal y límite de velocidad de hasta 80 km/h. La masa del vehículo no pinta nada: el distractor cuela un criterio de otra norma.","val":19,"fase":3},{"id":11687,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801986.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitida para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitida para vehículos que no pueden superar 30 km/h"},{"t":"забранено за трактори","ok":false,"i":null,"es":"prohibida para tractores"},{"t":"забранено за товарни автомобили","ok":false,"i":null,"es":"prohibida para camiones"}],"f":9,"es":"En esta situación, la circulación por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril lento es para vehículos con señal de lento Y para los que no superan 30 km/h. Tractores y camiones SÍ pueden usarlo si cumplen esas condiciones.","val":14,"fase":3},{"id":5861,"bg":"След пътния знак движението трябва да се извършва на дистанция от предния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57706.png","v":null,"a":[{"t":"не по-малка от 70 м","ok":true,"i":null,"es":"no menos de 70 m"},{"t":"не по-голяма от 70 м","ok":false,"i":null,"es":"no más de 70 m"}],"f":6,"es":"Después de esta señal, la distancia de seguridad con el vehículo de delante debe ser:","explain":"La señal indica MÍNIMO 70 metros de distancia. No confundas 'no menos de' con 'no más de' — es una distancia mínima obligatoria, no un máximo.","val":9,"fase":3},{"id":6245,"bg":"Коя линия указва правилната траектория за движение при завиване надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69818.png","v":null,"a":[{"t":"червената","ok":true,"i":null,"es":"la roja"},{"t":"синята","ok":false,"i":null,"es":"la azul"}],"f":6,"es":"¿Qué línea indica la trayectoria correcta al girar a la derecha?","explain":"La línea roja muestra la trayectoria correcta para girar a la derecha — pegada al borde derecho, sin cortarla. La azul es demasiado amplia o incorrecta.","val":9,"fase":4},{"id":6247,"bg":"Завиването наляво може да се извършва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от най-лявата пътна лента по посока на движението","ok":true,"i":null,"es":"desde el carril más a la izquierda en el sentido de marcha"},{"t":"от всяка лента, обозначена за завиване наляво","ok":true,"i":null,"es":"desde cualquier carril señalizado para girar a la izquierda"},{"t":"от най-лявата част на еднопосочно пътно платно","ok":true,"i":null,"es":"desde la parte más a la izquierda de una calzada de sentido único"},{"t":"от най-удобната за водача пътна лента","ok":false,"i":null,"es":"desde el carril más cómodo para el conductor"}],"f":7,"es":"Girar a la izquierda puede hacerse: (3 correctas)","explain":"Giro a la izquierda desde: el carril más a la izquierda de tu sentido, cualquier carril señalizado para ello, o la parte más a la izquierda en calzada de sentido único. 'El carril más cómodo' nunca es opción legal.","val":10,"fase":3},{"id":6344,"bg":"При тази ситуация водачът на автомобила задължен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70912.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ — el tranvía tiene prioridad en esta situación. Los tranvías generalmente tienen prioridad sobre los vehículos de motor en intersecciones.","val":9,"fase":4},{"id":6345,"bg":"При тази ситуация водачът на лекия автомобил не е задължен да пропусне трамвая.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70945.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":7,"es":"En esta situación el conductor del turismo no está obligado a dejar pasar al tranvía. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — el conductor SÍ está obligado a ceder al tranvía. Los tranvías tienen prioridad.","val":10,"fase":3},{"id":6358,"bg":"Как се извършва завиването в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"чрез движение със завиване наляво","ok":true,"i":null,"es":"mediante un giro a la izquierda"},{"t":"чрез движение със завиване надясно","ok":false,"i":null,"es":"mediante un giro a la derecha"}],"f":8,"es":"¿Cómo se realiza el cambio de sentido?","explain":"El cambio de sentido se ejecuta siempre mediante un giro a la IZQUIERDA: giras cruzando el eje de la vía hasta quedar en sentido contrario. Un giro a la derecha te saca de la vía, no invierte tu sentido.","val":12,"fase":3},{"id":6372,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на жп прелез","ok":true,"i":null,"es":"en paso a nivel"},{"t":"в тунел","ok":true,"i":null,"es":"en túnel"},{"t":"когато с пътен знак е ограничена скоростта на движение","ok":false,"i":null,"es":"cuando hay señal de limitación de velocidad"},{"t":"на 10 м преди пешеходна пътека","ok":false,"i":null,"es":"a 10 m antes de paso de peatones"}],"f":8,"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"Prohibido cambiar de sentido en paso a nivel y en túnel: en ambos, quedar atravesado es potencialmente mortal. Una señal de límite de velocidad no prohíbe la maniobra, y 10 m antes del paso de peatones tampoco (la prohibición es SOBRE el paso).","val":11,"fase":3},{"id":6383,"bg":"На път с голям надлъжен наклон, когато разминаването е невъзможно и редът за преминаване не е уреден с пътни знаци, предимство има ППС, което:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се изкачва по наклона","ok":true,"i":null,"es":"sube la pendiente"},{"t":"се спуска по наклона","ok":false,"i":null,"es":"baja la pendiente"},{"t":"се движи по-бързо","ok":false,"i":null,"es":"va más rápido"},{"t":"се намира по-близо до стеснения участък","ok":false,"i":null,"es":"está más cerca del tramo estrecho"}],"f":7,"es":"En vía con gran pendiente, cuando no es posible el cruce y no hay norma establecida, tiene prioridad el que:","explain":"Tiene prioridad el que SUBE: si para en plena pendiente, arrancar de nuevo cuesta arriba es difícil (riesgo de calar o retroceder). El que baja retrocede con la gravedad a favor. La velocidad o la cercanía al estrechamiento no son criterios.","val":11,"fase":3},{"id":6393,"bg":"Изпреварването на товарен автомобил е по-рисковано от изпреварването на лек автомобил защото:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"дължината на товарните автомобили е по-голяма от тази на леките автомобили","ok":true,"i":null,"es":"los camiones son más largos que los turismos"},{"t":"видимостта напред при движение зад товарен автомобил е по-ограничена","ok":true,"i":null,"es":"la visibilidad hacia adelante detrás de un camión es más limitada"},{"t":"спирачките на товарните автомобили не са толкова ефективни","ok":false,"i":null,"es":"los frenos de los camiones no son tan eficaces"},{"t":"товарните автомобили изкачват стръмните наклони по-бавно","ok":false,"i":null,"es":"los camiones suben las pendientes más despacio"}],"f":9,"es":"Adelantar un camión es más arriesgado que adelantar un turismo porque: (2 correctas)","explain":"Adelantar un camión es más arriesgado porque es más LARGO (la maniobra dura más metros y segundos) y porque detrás de él NO VES el tráfico que viene de frente. Sus frenos o su lentitud en subida no son la razón: eso hasta facilitaría adelantar.","val":13,"fase":3},{"id":6408,"bg":"Разрешено ли е да изпреварите мотоциклетиста при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71573.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"¿Está permitido adelantar al motorista en esta situación?","explain":"SÍ. La señal prohíbe adelantar, pero deja fuera expresamente a los ciclomotores y a las MOTOCICLETAS DE DOS RUEDAS SIN SIDECAR. El motorista de la imagen es justo eso, así que puedes adelantarle. Es una de las excepciones que más se olvidan: se ve el círculo rojo con los dos coches y se asume prohibición total. Lo que prohíbe es adelantar automóviles, no motos.","val":14,"fase":3},{"id":6448,"bg":"При тази ситуация разрешено ли е да заобиколите трамвая отляво за да не пречите на слизащите и качващите се пътници?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124301.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":10,"es":"En esta situación ¿está permitido rodear el tranvía por la izquierda para no estorbar a los pasajeros que bajan y suben?","explain":"NO. Al tranvía se le rebasa y se le adelanta por la DERECHA: irte por la izquierda te mete en el sentido contrario. Y si el tranvía está parado en una parada sin isleta, la obligación no es esquivarlo sino detenerte y esperar a que suban y bajen los viajeros. La 'buena intención' de no estorbar a los pasajeros es justo el cebo de la pregunta.","val":14,"fase":3},{"id":5878,"bg":"В кой от изброените случаи при този сигнал на светофара е забранено да навлезете в кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102946.png","v":null,"a":[{"t":"когато ще се наложи да остана в кръстовището поради задръстване","ok":true,"i":null,"es":"cuando voy a quedarme dentro por un atasco"},{"t":"когато на платното за движение има стоп-линия","ok":false,"i":null,"es":"cuando hay línea de stop en la calzada"},{"t":"когато на кръстовището са поставени пътни знаци относно предимството","ok":false,"i":null,"es":"cuando hay señales de prioridad en la intersección"}],"f":7,"es":"¿En cuál de los casos enumerados, con esta señal del semáforo, está PROHIBIDO entrar en la intersección?","explain":"Verde pero hay atasco al otro lado = NO entres. No debes bloquear la intersección aunque tengas verde. La línea de stop y las señales de prioridad no cambian el derecho de paso con verde.","val":10,"fase":3},{"id":5924,"bg":"Редът за преминаване на автомобила и мотоциклета през това кръстовище се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48275.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката им на движение","ok":false,"i":null,"es":"la dirección en que van"},{"t":"в зависимост от категорията на превозните средства","ok":false,"i":null,"es":"la categoría del vehículo"}],"f":6,"es":"El orden de paso del coche y la moto en esta intersección lo determina:","explain":"Sin señalización específica entre vehículos similares = regla de la derecha. La dirección o la categoría del vehículo no determinan la prioridad.","val":9,"fase":4},{"id":5927,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48311.png","v":null,"a":[{"t":"ППС, които са на пътя с предимство, трябва да преминат преди ППС от другия път","ok":true,"i":null,"es":"los vehículos de la vía preferente pasan antes que los del otro camino"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":true,"i":null,"es":"los que giran a la izquierda desde la preferente ceden a los de frente"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":false,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"}],"f":6,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: en vía preferente: los preferentes pasan primero + los que giran a la izquierda ceden al tráfico contrario. Entre sí los vehículos preferentes NO aplican la regla de la derecha.","val":9,"fase":3},{"id":5929,"bg":"При тази ситуация, при определяне на реда за преминаване през кръстовището, се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48329.png","v":null,"a":[{"t":"ППС, на пътя с предимство, трябва да преминат преди ППС на другия път","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los del otro camino"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"entre sí los de la preferente aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"f":8,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: preferentes pasan antes + entre ellos aplican la regla de la derecha. En esta variante los que giran a la izquierda NO ceden al contrario (diferencia respecto a la anterior).","val":12,"fase":3},{"id":5940,"bg":"При несъответствие между сигналите на регулировчика, сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51102.png","v":null,"a":[{"t":"със сигналите на регулировчика","ok":true,"i":null,"es":"las señales del agente"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las señales de tráfico"},{"t":"със сигналите на светофара","ok":false,"i":null,"es":"las señales del semáforo"}],"f":9,"es":"Cuando hay conflicto entre agente, semáforo y señales de prioridad debes atenerte a:","explain":"Las señales del AGENTE. El orden de mando es fijo: regulador > semáforo > señales verticales > marcas viales. Por eso, aunque el semáforo esté funcionando y haya un rombo de prioridad en el cruce, mientras el agente dirija el tráfico son sus indicaciones las que valen. Las otras dos opciones invierten esa jerarquía. El agente está por encima de todo lo demás.","val":14,"fase":3},{"id":5949,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51399.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"SÍ. El semáforo está en rojo, pero hay un agente regulando y sus señales anulan al semáforo. Tiene los brazos BAJADOS y lo ves de perfil, por su costado: desde esa posición se autoriza seguir recto o girar a la derecha. Si estuvieras frente a su pecho o a su espalda, con los brazos bajados tendrías que detenerte. Cuando hay agente, el semáforo deja de decidir.","val":13,"fase":3},{"id":6506,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62187.png","v":null,"a":[{"t":"червеният автомобил","ok":true,"i":null,"es":"el coche rojo"},{"t":"жълтият автомобил","ok":false,"i":null,"es":"el coche amarillo"}],"f":4,"es":"En esta situación tiene prioridad:","explain":"El rojo tiene prioridad — está en vía preferente o viene por la derecha del amarillo según la imagen.","val":6,"fase":4},{"id":6518,"bg":"При тази ситуация съм с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63169.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":9,"es":"En esta situación yo tengo prioridad. Esto es:","explain":"INCORRECTO. En tu acceso hay un ceda el paso con el panel del trazado debajo: la vía con prioridad es la transversal y tú vienes por la secundaria. Con esa señal no tienes preferencia sobre nadie que circule por ella. El panel no es decorativo — te dice qué brazo del cruce manda, y en este caso no es el tuyo. Ceda el paso y prioridad nunca van juntos.","val":14,"fase":3},{"id":6520,"bg":"При тази ситуация трябва да пропусна:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62077.png","v":null,"a":[{"t":"двете превозни средства","ok":true,"i":null,"es":"a los dos vehículos"},{"t":"само трамвая","ok":false,"i":null,"es":"solo al tranvía"},{"t":"само автомобила","ok":false,"i":null,"es":"solo al coche"}],"f":8,"es":"En esta situación debo dejar pasar:","explain":"A los dos — tanto el tranvía como el coche tienen prioridad sobre ti en esta configuración específica.","val":12,"fase":3},{"id":6550,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68473.png","v":null,"a":[{"t":"да премина преди двата автомобила","ok":true,"i":null,"es":"pasar antes que los dos coches"},{"t":"да пропусна само червения автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche rojo"},{"t":"да пропусна само синия автомобил","ok":false,"i":null,"es":"dejar pasar solo al coche azul"}],"f":8,"es":"En esta situación debo:","explain":"Tienes prioridad sobre ambos coches — pasas primero que los dos según la situación mostrada.","val":12,"fase":3},{"id":6559,"bg":"При тази ситуация водачът на зеления автомобил трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68404.png","v":null,"a":[{"t":"да пропусне червения автомобил","ok":true,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да пропусне синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да премине преди синия автомобил","ok":false,"i":null,"es":"pasar antes que el azul"},{"t":"да премине преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el rojo"}],"f":8,"es":"En esta situación el conductor del coche verde debe: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el verde debe ceder tanto al rojo como al azul — ambos tienen prioridad sobre él en esta intersección.","val":11,"fase":3},{"id":6562,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67115.png","v":null,"a":[{"t":"лекият автомобил е с предимство, защото е отдясно на мотоциклетиста","ok":true,"i":null,"es":"el turismo tiene prioridad porque está a la derecha del motorista"},{"t":"мотоциклетистът е с предимство, защото се движи направо","ok":false,"i":null,"es":"el motorista tiene prioridad porque va recto"},{"t":"мотоциклетистът е с предимство, защото е двуколесно МПС","ok":false,"i":null,"es":"el motorista tiene prioridad porque es vehículo de dos ruedas"}],"f":9,"es":"En esta situación:","explain":"El TURISMO, porque está a la derecha del motorista. Cruce de vías de igual valor: manda la regla de la derecha y nada más. 'Porque va recto' es el cebo habitual — la dirección nunca reparte preferencias. Y 'porque es un vehículo de dos ruedas' es aún peor: las motos no tienen ninguna prioridad especial, se rigen por las mismas reglas que los coches.","val":13,"fase":3},{"id":6573,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68203.png","v":null,"a":[{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"},{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"}],"f":10,"es":"En esta situación debo pasar después de:","explain":"Después del AZUL. El azul llega por mi derecha y tiene preferencia sobre mí. El rojo llega por mi izquierda, así que él pasa después de mí, no antes. La pregunta invierte el enunciado habitual — pregunta detrás de quién voy, no a quién cedo — pero la respuesta sale del mismo sitio: solo cede el paso quien tiene al otro a su derecha.","val":15,"fase":3},{"id":6597,"bg":"При тази ситуация трябва да пропусна товарния автомобил, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/56964.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación debo dejar pasar al camión porque va recto. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — ir recto no da prioridad automática. La prioridad la determina la señalización y la regla de la derecha, no la dirección de marcha.","val":12,"fase":3},{"id":6606,"bg":"Редът за преминаване на тези автомобили през кръстовището се определя:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48346.png","v":null,"a":[{"t":"с правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"la regla de prioridad a la derecha"},{"t":"в зависимост от посоката на движение на автомобилите","ok":false,"i":null,"es":"la dirección de circulación"}],"f":10,"es":"El orden de paso de estos coches en la intersección lo determinan:","explain":"La regla de la DERECHA. El rombo amarillo va con un panel que dibuja el trazado: la vía con prioridad llega desde mi acceso y gira a la derecha, y tanto el rojo como el azul circulan por ella. Cuando la vía con prioridad cambia de dirección, quienes van por ella lo resuelven entre sí como si el cruce fuera de vías de igual valor. 'Según la dirección de circulación' es el cebo: adónde va cada uno no reparte preferencias.","val":14,"fase":3},{"id":6612,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53713.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar la señal de paso del agente"},{"t":"пропускам синия автомобил и преминавам след него","ok":false,"i":null,"es":"dejo pasar al coche azul y paso después"},{"t":"преминавам преди синия автомобил","ok":false,"i":null,"es":"paso antes que el coche azul"}],"f":11,"es":"En esta situación:","explain":"Paras y esperas a que el regulador te dé la señal de paso: mientras no te habilite, no hay nada que negociar con el coche azul. Por eso son falsas «le cedo y paso después» y «paso antes que él»: las dos dan por hecho que la decisión es entre vosotros, y la decisión es del agente. Girar tampoco te exime — girar también es «pasar».","val":16,"fase":3},{"id":7963,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917897.png","v":null,"a":[{"t":"да, защото се намира на пътя с предимство","ok":true,"i":null,"es":"sí, porque está en la vía preferente"},{"t":"да, защото се намира отдясно","ok":true,"i":null,"es":"sí, porque está a su derecha"},{"t":"не, защото се движа направо","ok":false,"i":null,"es":"no, porque voy recto"}],"f":9,"es":"En esta situación ¿está obligado a dejar pasar al camión? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: sí debes ceder — el camión está en vía preferente Y a tu derecha. Son dos razones independientes que justifican la prioridad del camión.","val":14,"fase":3},{"id":11347,"bg":"При навлизане в тунел, на който началото е обозначено с пътен знак, водачът задължен ли е да включи късите светлини на автомобила?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"Al entrar en un túnel señalizado con señal de tráfico ¿está obligado el conductor a encender las luces?","explain":"Sí: en túnel señalizado con señal de tráfico es obligatorio encender las luces, aunque el túnel esté iluminado. Debes ver y sobre todo SER VISTO en el cambio brusco de luminosidad.","val":9,"fase":4},{"id":5367,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40964.png","v":null,"a":[{"t":"автомобилa, който се движи по автомагистралата","ok":true,"i":null,"es":"coche que circula por la autopista"},{"t":"автомобила отдясно, който навлиза на автомагистралата","ok":false,"i":null,"es":"coche de la derecha que entra en la autopista"},{"t":"автомобилa, който се движи с по-висока скорост","ok":false,"i":null,"es":"coche que va más rápido"}],"f":13,"es":"En esta situación tiene prioridad el conductor del:","explain":"El que ya circula por la autopista tiene prioridad absoluta. Los que entran deben ceder siempre, independientemente de su posición o velocidad.","val":13,"fase":4},{"id":5370,"bg":"При тази ситуация:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41161.png","v":null,"a":[{"t":"червеният автомобил е с предимство, защото се движи по автомагистралата","ok":true,"i":null,"es":"el coche rojo tiene prioridad porque circula por la autopista"},{"t":"синият автомобил, който навлиза на автомагистралата, пропуска червения автомобил","ok":true,"i":null,"es":"el coche azul que entra en la autopista cede el paso al rojo"},{"t":"синия автомобил е с предимство, защото се намира отдясно","ok":false,"i":null,"es":"el azul tiene prioridad porque está a la derecha"},{"t":"червения автомобил е с предимство, защото не променя посоката си на движение","ok":false,"i":null,"es":"el rojo tiene prioridad porque no cambia de dirección"}],"f":8,"es":"En esta situación: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rojo tiene prioridad (autopista) Y el azul debe cederle el paso. Estar a la derecha no da prioridad al entrar en autopista.","val":8,"fase":4},{"id":5406,"bg":"На автомагистрала, преминаването в платното за насрещното движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено на местата, където разделителната ивица между платната за движение е прекъсната","ok":false,"i":null,"es":"permitido donde la mediana está interrumpida"},{"t":"разрешено навсякъде, където е възможно, ако не се пречи на насрещно движещите се ППС","ok":false,"i":null,"es":"permitido donde sea posible sin obstaculizar"}],"f":9,"es":"En autopista, cruzar al carril contrario está:","explain":"Prohibido: en autopista jamás se cruza al carril contrario. Las interrupciones de la mediana existen solo para los servicios de emergencia y mantenimiento, no para los conductores.","val":9,"fase":4},{"id":5407,"bg":"Завиването в обратна посока при движение по автомагистрала е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено във всички случаи","ok":true,"i":null,"es":"prohibido en todos los casos"},{"t":"разрешено само през светлата част от денонощието","ok":false,"i":null,"es":"permitido solo de día"},{"t":"разрешено, но водачът трябва да продължи движението си по лентата за принудително спиране","ok":false,"i":null,"es":"permitido pero continuando por el carril de emergencia"},{"t":"разрешено за напускане на автомагистралата","ok":false,"i":null,"es":"permitido para abandonar la autopista"}],"f":8,"es":"El cambio de sentido en autopista está:","explain":"Prohibido en todos los casos: en autopista jamás se cambia de sentido. Para 'volver' se sale por la siguiente salida y se reentra en sentido contrario. Ni de día, ni por el carril de emergencia, ni para abandonarla.","val":8,"fase":4},{"id":5411,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за паркиране извън обозначените за това места","ok":true,"i":null,"es":"parar para aparcar fuera de lugares señalizados"},{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar en prestoy fuera de lugares señalizados"},{"t":"да спира за отстраняване на неизправност по автомобила","ok":false,"i":null,"es":"parar para eliminar una avería"},{"t":"да се движи с прикачено ремарке","ok":false,"i":null,"es":"circular con remolque"}],"f":8,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (2 correctas)","explain":"En vía rápida está prohibido parar (престой) y aparcar fuera de los lugares señalizados. Parar por avería es la excepción de fuerza mayor, y circular con remolque está permitido: esas dos opciones son las trampas.","val":8,"fase":4},{"id":8274,"bg":"При навлизане на скоростен път, водачът е длъжен да пропусне превозните средства, които се движат по него:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"във всички случаи","ok":true,"i":null,"es":"en todos los casos"},{"t":"само когато е поставен пътен знак за осигуряване на предимство","ok":false,"i":null,"es":"solo cuando hay señal de ceder el paso"},{"t":"само когато те се движат с висока скорост","ok":false,"i":null,"es":"solo cuando van a alta velocidad"}],"f":11,"es":"Al entrar en vía rápida el conductor está obligado a ceder el paso a los que ya circulan:","explain":"En todos los casos: quien se incorpora a la vía rápida cede el paso a quienes ya circulan por ella, haya o no señal. El carril de aceleración sirve para igualar velocidad y buscar hueco, no da prioridad.","val":11,"fase":4},{"id":11349,"bg":"При движение по автомагистрала на водача е забранено да спира в лентата за принудително спиране, освен при:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"повреда на пътното превозно средство","ok":true,"i":null,"es":"avería del vehículo"},{"t":"здравословни проблеми на водача","ok":true,"i":null,"es":"problemas de salud del conductor"},{"t":"здравословни проблеми на пътниците в превозното средство","ok":true,"i":null,"es":"problemas de salud de los pasajeros"},{"t":"необходимост от сън/почивка на водача","ok":false,"i":null,"es":"necesidad de descanso del conductor"}],"f":9,"es":"En autopista ESTÁ PERMITIDO parar en el carril de emergencia por: (3 correctas)","explain":"El carril de emergencia admite parar por avería del vehículo o por problemas de salud del conductor o de los pasajeros: emergencias reales. El simple descanso no es emergencia: para eso están las áreas de servicio.","val":9,"fase":4},{"id":11709,"bg":"Когато няма други ограничения, водачът на състав от ППС от категория ВЕ, при движение по автомагистрала не трябва да превишава:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"100 km/h","ok":true,"i":null,"es":"100 km/h"},{"t":"110 km/h","ok":false,"i":null,"es":"110 km/h"},{"t":"120 km/h","ok":false,"i":null,"es":"120 km/h"},{"t":"130 km/h","ok":false,"i":null,"es":"130 km/h"}],"f":11,"es":"Sin otras restricciones, el conductor de un convoy de categoría BE en autopista puede circular a máximo:","explain":"100 km/h: los conjuntos categoría BE (turismo + remolque) tienen en autopista un límite inferior al de los turismos solos. El remolque alarga la frenada y desestabiliza a alta velocidad.","val":11,"fase":4},{"id":11729,"bg":"При теглене с твърда връзка по скоростен път разрешената максимална скорост за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"70 km/h","ok":true,"i":null,"es":"70 km/h"},{"t":"30 km/h","ok":false,"i":null,"es":"30 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"50 km/h","ok":false,"i":null,"es":"50 km/h"}],"f":12,"es":"Remolcando con barra rígida en vía rápida la velocidad máxima es:","explain":"Remolcando con barra RÍGIDA en vía rápida el máximo es 70 km/h: la barra da control pero el conjunto sigue siendo inestable a alta velocidad. Es uno de los límites especiales de remolcado que hay que memorizar.","val":12,"fase":4},{"id":5563,"bg":"Паркираното превозно средство трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да не пречи на останалите водачи да напуснат мястото си на паркиране","ok":true,"i":null,"es":"no impedir a otros conductores salir de su plaza"},{"t":"да не спира преминаването на другите превозни средства","ok":true,"i":null,"es":"no obstaculizar el paso de otros vehículos"},{"t":"да не остава с включена предавка","ok":false,"i":null,"es":"no dejarse con la marcha puesta"},{"t":"да бъде с изключено радио","ok":false,"i":null,"es":"estar con la radio apagada"}],"f":5,"es":"El vehículo aparcado debe: (2 correctas)","explain":"El vehículo aparcado no debe impedir a otros salir de su plaza ni obstaculizar el paso: sus dos obligaciones hacia los demás. La marcha puesta o la radio no son objeto de esta norma (la marcha puesta en pendiente es incluso recomendable).","val":3,"fase":4},{"id":5580,"bg":"От коя страна на еднопосочен път в населено място е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"от дясната страна","ok":true,"i":null,"es":"por el lado derecho"},{"t":"от лявата страна","ok":false,"i":null,"es":"por el lado izquierdo"},{"t":"от двете страни","ok":false,"i":null,"es":"por los dos lados"}],"f":8,"es":"¿Por qué lado de una calle de sentido único en zona urbana está permitido aparcar?","explain":"APARCAR en calle de sentido único: solo por el lado DERECHO. La tolerancia del lado izquierdo existe para la parada breve, no para el estacionamiento: esa es la diferencia con la pregunta gemela.","val":4,"fase":4},{"id":5611,"bg":"Забранено е спирането за престой пред пешеходна пътека на разстояние по-малко от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"5 м","ok":true,"i":null,"es":"5 m"},{"t":"10 м","ok":false,"i":null,"es":"10 m"},{"t":"15 м","ok":false,"i":null,"es":"15 m"},{"t":"20 м","ok":false,"i":null,"es":"20 m"}],"f":7,"es":"La parada breve (prestoy) está prohibida ante un paso de peatones a una distancia menor de:","explain":"5 m antes del paso de peatones: es la distancia mínima. Más cerca, tu vehículo tapa al peatón que va a entrar en la calzada y te tapa a ti la vista del peatón.","val":3,"fase":4},{"id":5642,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на платното за движение, където разстоянието между ППС и пътната маркировка, забранена за пресичане, е по-малко от 3 метра","ok":true,"i":null,"es":"en calzada donde la distancia al marcaje que prohíbe el adelantamiento sería menos de 3m"},{"t":"на платното за движение, където с пътен знак е забранено изпреварването","ok":true,"i":null,"es":"en calzada donde hay señal que prohíbe el adelantamiento"},{"t":"върху пътна лента, предназначена за движение на бавнодвижещи се ППС, обозначена с пътен знак","ok":true,"i":null,"es":"sobre carril destinado a vehículos lentos señalizado"},{"t":"на участък от пътя с интензивно движение","ok":false,"i":null,"es":"en tramo de intenso tráfico"}],"f":6,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar: a menos de 3 m de una marca infranqueable (obligarías a pisarla), donde una señal prohíbe adelantar (forzarías un adelantamiento ilegal) y sobre el carril de vehículos lentos. El 'tráfico intenso' no es causa legal.","val":3,"fase":4},{"id":5648,"bg":"Престоят върху платното за движение е забранен, ако разстоянието между ППС и пътната маркировка, забранена за пресичане, е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"1 м","ok":true,"i":null,"es":"1 m"},{"t":"2 м","ok":true,"i":null,"es":"2 m"},{"t":"2.5 м","ok":true,"i":null,"es":"2.5 m"},{"t":"3.5 м","ok":false,"i":null,"es":"3.5 m"}],"f":11,"es":"La parada breve (prestoy) en la calzada está prohibida si la distancia entre el vehículo y el marcaje deja: (3 correctas)","explain":"Prohibida la parada breve si entre el vehículo y la marca infranqueable quedan menos de 3 m: obligarías a los demás a pisar la línea. 1 m, 2 m y 2,5 m incumplen; 3,5 m cumple.","val":5,"fase":4},{"id":5705,"bg":"При намалена видимост под 50 м е забранено:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"тегленето","ok":true,"i":null,"es":"remolcar"},{"t":"завиването в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"спирането за престой","ok":false,"i":null,"es":"parar en prestoy"},{"t":"движението назад","ok":false,"i":null,"es":"ir marcha atrás"}],"f":6,"es":"Con visibilidad inferior a 50 m está PROHIBIDO: (2 correctas)","explain":"Con visibilidad bajo 50 m está prohibido remolcar y dar la vuelta: dos maniobras lentas que ocupan la vía cuando nadie te ve llegar. La parada breve y la marcha atrás no entran en esta prohibición específica.","val":3,"fase":4},{"id":5729,"bg":"Как влияе върху управляемостта на превозното средство пониженото налягане на въздуха в гумите?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"влошава управляемостта","ok":true,"i":null,"es":"empeora la manejabilidad"},{"t":"подобрява управляемостта","ok":false,"i":null,"es":"mejora la manejabilidad"},{"t":"не влияе на управляемостта","ok":false,"i":null,"es":"no afecta a la manejabilidad"}],"f":10,"es":"¿Cómo afecta la presión baja de los neumáticos a la manejabilidad del vehículo?","explain":"Empeora la manejabilidad: con poca presión el neumático flexa, la dirección responde tarde y de forma imprecisa, y el vehículo 'flota' en curva. Nunca la mejora ni resulta indiferente.","val":5,"fase":4},{"id":5908,"bg":"Значението на кой от показаните немигащи сигнали на светофара е “Преминаването е разрешено”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":false,"es":"","i":"42530"},{"t":"","ok":true,"es":"","i":"42529"},{"t":"","ok":false,"es":"","i":"42532"},{"t":"","ok":false,"es":"","i":"42531"}],"f":10,"es":"¿Cuál de las señales fijas del semáforo significa 'El paso está PERMITIDO'?","explain":"Busca la imagen con el semáforo VERDE encendido. Verde = paso permitido. Esta es una pregunta visual — las respuestas son imágenes de semáforos.","val":14,"fase":3},{"id":5452,"bg":"По какво се различават зимните от летните гуми?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"по налягането на въздуха","ok":false,"i":null,"es":"en la presión del aire"},{"t":"по материала, от който е изработен протекторът","ok":true,"i":null,"es":"en el material del dibujo del neumático"},{"t":"по шарките на протектора","ok":true,"i":null,"es":"en el dibujo del neumático"},{"t":"по цвета","ok":false,"i":null,"es":"en el color"}],"f":4,"es":"¿En qué se diferencian los neumáticos de invierno de los de verano? (2 correctas)","explain":"Los neumáticos de invierno se diferencian en el MATERIAL (goma que sigue blanda en frío) y en el DIBUJO (laminillas para nieve). La presión de uso es la misma y el color, obviamente, también.","val":2,"fase":4},{"id":5404,"bg":"С този опознавателен знак се обозначават:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334672.png","v":null,"a":[{"t":"ремаркетата","ok":true,"i":null,"es":"los remolques"},{"t":"полуремаркетата","ok":true,"i":null,"es":"los semirremolques"},{"t":"товарните автомобили над 3,5 тона","ok":false,"i":null,"es":"los camiones de más de 3.5 t"},{"t":"товарните автомобили над 7,5 тона","ok":false,"i":null,"es":"los camiones de más de 7.5 t"}],"f":6,"es":"Con esta señal de identificación se marcan: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: esta señal identifica remolques Y semirremolques. No los camiones directamente — es para los vehículos arrastrados.","val":6,"fase":4},{"id":6031,"bg":"При тази ситуация трябва:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/26547.png","v":null,"a":[{"t":"да намаля скоростта","ok":true,"i":null,"es":"reducir la velocidad"},{"t":"да управлявам с готовност за спиране","ok":true,"i":null,"es":"circular listo para frenar"},{"t":"да подам сигнал за маневра и да заобиколя пешеходеца","ok":false,"i":null,"es":"señalizar y rodear al peatón"},{"t":"да подам звуков сигнал и да продължа движението","ok":false,"i":null,"es":"tocar el claxon y continuar"}],"f":6,"es":"En esta situación debes: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: ante peatón en la vía debes reducir velocidad Y circular listo para frenar. Rodearlo con señal o tocar el claxon no son soluciones adecuadas — el peatón tiene prioridad.","val":6,"fase":4},{"id":5932,"bg":"Значението на този светлинен сигнал е:","p":3,"s":"Раздел 3. СРЕДСТВА ЗА ОРГАНИЗАЦИЯ И РЕГУЛИРАНЕ НА ДВИЖЕНИЕТО","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/44686.png","v":null,"a":[{"t":"„Навлизането е забранено” по пътната лента, над която е поставен","ok":true,"i":null,"es":"'Entrada PROHIBIDA' en el carril sobre el que está"},{"t":"„Следва кръстовище на равнозначни пътища”","ok":false,"i":null,"es":"'Sigue intersección de vías equivalentes'"},{"t":"„Навлизането е разрешено” по пътната лента, над която е поставен","ok":false,"i":null,"es":"'Entrada PERMITIDA' en el carril sobre el que está"},{"t":"„Място за задължително спиране”","ok":false,"i":null,"es":"'Lugar de parada obligatoria'"}],"f":9,"es":"El significado de esta señal luminosa es:","explain":"'Entrada PROHIBIDA' en el carril sobre el que está. La X roja de un semáforo de carril cierra ese carril concreto, no toda la calzada: los demás siguen abiertos y hay que salir de este antes de llegar. Las otras opciones describen señales distintas — un cruce de vías iguales o una parada obligatoria — que nada tienen que ver con la señalización por carriles.","val":14,"fase":3},{"id":6070,"bg":"При тази ситуация трябва да се движа:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/59902.png","v":null,"a":[{"t":"в дясната пътна лента","ok":true,"i":null,"es":"en el carril derecho"},{"t":"в по-удобната за мен пътна лента","ok":false,"i":null,"es":"en el carril más cómodo"},{"t":"в лявата пътна лента","ok":false,"i":null,"es":"en el carril izquierdo"}],"f":7,"es":"En esta situación debo circular:","explain":"En el carril DERECHO — la situación mostrada (vía normal, sin condiciones especiales para usar otros carriles) obliga a ir por el derecho.","val":10,"fase":3},{"id":6090,"bg":"При тази ситуация навлизанетo в лентите за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62058.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено, но само при изпреварване","ok":false,"i":null,"es":"permitido solo para adelantar"},{"t":"разрешено, когато са свободни","ok":false,"i":null,"es":"permitido cuando están libres"}],"f":9,"es":"En esta situación entrar en los carriles del sentido contrario está:","explain":"PROHIBIDO. La calzada tiene cuatro carriles o más, y en ese caso está prohibido invadir los del sentido contrario en cualquier circunstancia. No hay excepción por adelantar, que es el cebo de la pregunta: con cuatro carriles adelantas por el carril de tu propio sentido. Que estén libres tampoco cambia nada. Cuenta los carriles antes de pensar en cruzarte.","val":14,"fase":3},{"id":6091,"bg":"На двупосочен път с четири пътни ленти навлизанетo в лента за насрещното движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62094.png","v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"разрешено при изпреварване","ok":false,"i":null,"es":"permitido para adelantar"},{"t":"разрешено при заобикаляне","ok":false,"i":null,"es":"permitido para rodear obstáculos"}],"f":8,"es":"En vía de doble sentido con cuatro carriles, entrar en el carril contrario está:","explain":"PROHIBIDO — en vías con 4 carriles de doble sentido hay línea continua central que prohíbe invadir el sentido contrario. Con 2 carriles de doble sentido sí se permite para adelantar.","val":12,"fase":3},{"id":6468,"bg":"Когато има обозначена с пътен знак пътна лента за бавнодвижещи се ППС, водачите на такива ППС:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"са длъжни да използват за движение тази лента","ok":true,"i":null,"es":"están obligados a usar ese carril"},{"t":"използват тази лента само когато тя е свободна","ok":false,"i":null,"es":"lo usan solo cuando está libre"},{"t":"не са задължени да я използват","ok":false,"i":null,"es":"no están obligados a usarlo"}],"f":5,"es":"Cuando hay un carril señalizado para vehículos lentos, los conductores de esos vehículos:","explain":"Obligados: si existe carril señalizado para vehículos lentos, deben usarlo. No es opcional ni condicionado a que esté libre: su función es precisamente sacar al lento del flujo rápido.","val":8,"fase":4},{"id":9835,"bg":"Разрешено ли е да навлезете и да се движите по BUS-лентата?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043012.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":13,"es":"¿Está permitido entrar y circular por el carril BUS?","explain":"No: el carril BUS (señalizado con la marca correspondiente) está reservado al transporte público de línea: los turismos no entran ni circulan por él. Las excepciones (giros autorizados según señalización) no convierten el carril en tuyo.","val":19,"fase":3},{"id":9840,"bg":"При тази ситуация навлизането в BUS-лентата е разрешено за:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043260.png","v":null,"a":[{"t":"превозни средства от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"vehículos de líneas regulares de transporte público"},{"t":"спиране за престой за всички автобуси","ok":false,"i":null,"es":"parada breve para todos los autobuses"},{"t":"придвижване на повредено МПС","ok":false,"i":null,"es":"traslado de vehículos averiados"},{"t":"движение на бавнодвижещи се МПС","ok":false,"i":null,"es":"vehículos lentos"}],"f":10,"es":"En esta situación entrar en el carril BUS está permitido para:","explain":"Solo los vehículos de LÍNEAS REGULARES de transporte público. La línea amarilla continua reserva ese carril y no se puede pisar. 'Parada breve para todos los autobuses' es falso: manda el servicio de línea regular, no el tamaño del vehículo — un autocar privado no entra. Trasladar un vehículo averiado ni circular despacio dan derecho tampoco: los lentos van a la derecha, pero no en el carril BUS.","val":15,"fase":3},{"id":11688,"bg":"При тази ситуация, движението по обозначената с пътен знак лента за бавнодвижещи се ППС е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/1123801988.png","v":null,"a":[{"t":"разрешено за автомобили обозначени с опознавателен знак „бавнодвижещи се ППС”","ok":true,"i":null,"es":"permitido para vehículos marcados con señal de vehículo lento"},{"t":"разрешено за автомобили, които не могат да се движат със скорост по-висока от 30 km/h","ok":true,"i":null,"es":"permitido para vehículos que no pueden superar 30 km/h"},{"t":"забранено за велосипеди","ok":false,"i":null,"es":"prohibido para bicicletas"},{"t":"забранено за мотопеди","ok":false,"i":null,"es":"prohibido para ciclomotores"}],"f":6,"es":"En esta situación, circular por el carril señalizado para vehículos lentos está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril lento es para vehículos con señal de lento Y para los que no superan 30 km/h. Las bicicletas y ciclomotores también pueden usarlo si cumplen esas condiciones.","val":9,"fase":3},{"id":11871,"bg":"На кои от изброените пътни превозни средства е разрешено движението по пътния банкет?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"велосипеди","ok":true,"i":null,"es":"bicicletas"},{"t":"мотоциклети","ok":false,"i":null,"es":"motocicletas"},{"t":"автомобили с допустима максимална маса до 1,5 t","ok":false,"i":null,"es":"automóviles hasta 1.5 t"}],"f":4,"es":"¿A qué vehículos está permitido circular por el arcén? (2 correctas)","explain":"Por el arcén pueden circular ciclomotores y bicicletas (los lentos de dos ruedas, cuando el arcén derecho es apto). Las motocicletas y los coches circulan por la calzada: el arcén no es su sitio.","val":6,"fase":4},{"id":5817,"bg":"При тази ситуация разрешено ли е движение със скорост, по-висока от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103539.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":3,"es":"En esta situación ¿está permitido circular a velocidad superior a la indicada?","explain":"SÍ — cuando hay una señal de velocidad mínima y las condiciones de la vía lo permiten, puedes superar esa velocidad mínima. La señal es un mínimo, no un máximo.","val":4,"fase":4},{"id":11697,"bg":"Когато няма други ограничения, водачът на автомобил от категория В при движение извън населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"90 km/h","ok":true,"i":null,"es":"90 km/h"},{"t":"80 km/h","ok":false,"i":null,"es":"80 km/h"},{"t":"100 km/h","ok":false,"i":null,"es":"100 km/h"},{"t":"70 km/h","ok":false,"i":null,"es":"70 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de categoría B fuera de población puede circular a máximo:","explain":"90 km/h: límite general de los turismos categoría B fuera de población en vía convencional. Las cifras mayores requieren vía rápida (120) o autopista (140).","val":7,"fase":4},{"id":12030,"bg":"Какво трябва да очаквате в тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":16,"a":[{"t":"синият автомобил да навлезе в моята лента","ok":false,"i":null,"es":"que el coche azul invada mi carril"},{"t":"мотоциклетистът да намали скоростта си","ok":true,"i":null,"es":"que el motorista reduzca velocidad"},{"t":"тракторът да навлезе на пътя пред мен","ok":true,"i":null,"es":"que el tractor entre en la vía delante de mí"}],"f":8,"es":"¿Qué debe esperar en esta situación? (VIDEO) ⚠️ 2 correctas","explain":"Carretera rural: un tractor está a punto de ENTRAR en la vía desde el acceso del campo, delante del motorista que me precede — debo esperar ambas cosas: que el TRACTOR invada la vía delante de mí y que el MOTORISTA reduzca su velocidad al encontrárselo. La opción del coche azul invadiendo mi carril es el distractor: sigue por su trayectoria. Anticipa la cadena: obstáculo → frenada del de delante → tu frenada.","val":12,"fase":3},{"id":6223,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69503.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил","ok":true,"i":null,"es":"debe dejar pasar al coche azul"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"},{"t":"е с предимство защото е подал сигнал за маневра","ok":false,"i":null,"es":"tiene prioridad porque señalizó la maniobra"}],"f":8,"es":"En esta situación el conductor del coche rojo:","explain":"Debe ceder al azul — el rojo se incorpora o cambia de carril invadiendo el espacio del azul. Estar a la derecha o señalizar no da prioridad al que invade el carril ajeno.","val":11,"fase":3},{"id":6233,"bg":"При тази ситуация с предимство е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69669.png","v":null,"a":[{"t":"водачът на синия автомобил","ok":true,"i":null,"es":"el conductor del coche azul"},{"t":"водачът на червения автомобил","ok":false,"i":null,"es":"el conductor del coche rojo"}],"f":7,"es":"En esta situación tiene prioridad:","explain":"El azul tiene prioridad — según la imagen está en vía preferente o a la derecha del rojo.","val":10,"fase":3},{"id":6254,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69917.png","v":null,"a":[{"t":"трябва да пропусна пешеходеца","ok":true,"i":null,"es":"debo dejar pasar al peatón"},{"t":"не съм задължен да пропусна пешеходеца, защото завивам надясно","ok":false,"i":null,"es":"no estoy obligado a ceder al peatón porque giro a la derecha"},{"t":"не съм задължен да пропусна пешеходеца, защото той не е достигнал средата на платното за движение","ok":false,"i":null,"es":"no estoy obligado porque el peatón no ha llegado al centro de la calzada"}],"f":5,"es":"En esta situación:","explain":"⚠️ TRAMPA IMPORTANTE: SIEMPRE debes ceder al peatón en el paso, incluso si giras a la derecha y aunque el peatón no haya llegado al centro. El peatón en el paso tiene prioridad absoluta.","val":8,"fase":4},{"id":6273,"bg":"Как ще постъпите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/84437.png","v":null,"a":[{"t":"пропускам червения автомобил","ok":true,"i":null,"es":"cedo el paso al coche rojo"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el coche rojo"}],"f":6,"es":"¿Cómo actuarás en esta situación?","explain":"Cedes al rojo — según la imagen el rojo tiene prioridad sobre ti (vía preferente o regla de la derecha).","val":9,"fase":4},{"id":6286,"bg":"При тази ситуация съм с предимство пред червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70448.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación tengo prioridad sobre el coche rojo. Esto es:","explain":"INCORRECTO — el rojo tiene prioridad sobre ti, no al revés.","val":12,"fase":3},{"id":6290,"bg":"При тази ситуация червеният автомобил е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70482.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad. Esto es:","explain":"INCORRECTO — a pesar de lo que pueda parecer, el rojo NO tiene prioridad en esta situación específica.","val":12,"fase":3},{"id":6373,"bg":"Завиването в обратна посока е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"при ограничена видимост","ok":true,"i":null,"es":"con visibilidad limitada"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo de vía en obras"},{"t":"на 160 м преди жп прелез","ok":false,"i":null,"es":"a 160 m antes del paso a nivel"}],"f":10,"es":"El cambio de sentido está PROHIBIDO: (2 correctas)","explain":"Prohibido cambiar de sentido sobre paso de peatones y con visibilidad limitada. Las obras no lo prohíben por sí mismas, y la prohibición cerca del paso a nivel es EN el propio paso, no a 160 m (esa cifra es de las señales de aviso).","val":14,"fase":3},{"id":6384,"bg":"При тази ситуация задължен да пропусне насрещно движещото се превозно средство е водачът на:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71342.png","v":null,"a":[{"t":"червения автомобил","ok":true,"i":null,"es":"coche rojo"},{"t":"синия автомобил","ok":false,"i":null,"es":"coche azul"}],"f":6,"es":"En esta situación está obligado a ceder al vehículo que viene de frente el conductor del:","explain":"El rojo cede — viene por el lado donde hay menos espacio o tiene el paso bloqueado por la situación mostrada.","val":9,"fase":4},{"id":6387,"bg":"Как трябва да постъпите при тази ситуация, след като червеният автомобил е навлязъл в стеснения участък?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71408.png","v":null,"a":[{"t":"длъжен съм да пропусна червения автомобил","ok":true,"i":null,"es":"estoy obligado a ceder al rojo"},{"t":"трябва да продължа движението си, защото съм с предимство","ok":false,"i":null,"es":"debo continuar porque tengo prioridad"},{"t":"трябва да подам сигнал към червения автомобил за да ми осигури предимство","ok":false,"i":null,"es":"debo señalizarle que me deje pasar"}],"f":6,"es":"¿Cómo debes actuar cuando el coche rojo ya ha entrado en el tramo estrecho?","explain":"Cedes al rojo — aunque tengas prioridad en teoría, el rojo ya está dentro del tramo estrecho. La prioridad de paso no justifica crear un accidente.","val":9,"fase":3},{"id":6395,"bg":"Този пътен знак забранява изпреварването:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67557.png","v":null,"a":[{"t":"на МПС, с изключение на мотоциклети без кош и мотопеди","ok":true,"i":null,"es":"de vehículos a motor excepto motos sin sidecar y ciclomotores"},{"t":"на всички ППС","ok":false,"i":null,"es":"de todos los vehículos"},{"t":"само на леки автомобили","ok":false,"i":null,"es":"solo de turismos"}],"f":6,"es":"Esta señal prohíbe el adelantamiento:","explain":"Prohíbe adelantar vehículos a motor EXCEPTO motos sin sidecar y ciclomotores. Estos últimos están exentos — pueden seguir adelantando.","val":9,"fase":3},{"id":6397,"bg":"Кое от изброените ППС е разрешено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"велосипед","ok":true,"i":null,"es":"bicicleta"},{"t":"каруца","ok":true,"i":null,"es":"carruaje (carro de caballos)"},{"t":"трактор","ok":false,"i":null,"es":"tractor"},{"t":"товарен автомобил","ok":false,"i":null,"es":"camión"}],"f":8,"es":"¿Qué vehículo está PERMITIDO adelantar después de esta señal? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: puedes adelantar a la bicicleta Y al carruaje — no son vehículos a motor, están exentos de la prohibición. El tractor y el camión son vehículos a motor = prohibido adelantarlos.","val":12,"fase":3},{"id":6411,"bg":"Изпреварването е забранено, когато:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещното движение не е възможно безпрепятственото връщане в напуснатата лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver sin obstaculizar"},{"t":"видимостта е ограничена","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"изпреварващият автомобил е с повредени пътепоказатели","ok":false,"i":null,"es":"el adelantante tiene los intermitentes averiados"},{"t":"се извършва по двулентов двупосочен път","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"f":5,"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"Prohibido adelantar cuando, usando el carril contrario, no podrías reincorporarte sin obstaculizar, y cuando la visibilidad es limitada. Los intermitentes averiados no prohíben la maniobra (se señaliza con la mano) y la vía de dos carriles de doble sentido es el escenario NORMAL del adelantamiento.","val":8,"fase":4},{"id":6415,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на кръстовище на равнозначни пътища","ok":true,"i":null,"es":"en intersección de vías equivalentes"},{"t":"на железопътен прелез без бариери","ok":true,"i":null,"es":"en paso a nivel sin barreras"},{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario cuando no puedes reincorporarte sin peligro"},{"t":"в тунел","ok":false,"i":null,"es":"en túnel"}],"f":5,"es":"El adelantamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido adelantar en intersecciones de vías equivalentes, en pasos a nivel SIN barreras y cuando no puedes reincorporarte sin peligro. En TÚNEL el adelantamiento no está prohibido con carácter general (lo prohibido allí es marcha atrás y cambio de sentido): esa es la trampa.","val":7,"fase":4},{"id":6436,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/128556.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido adelantar en esta situación?","explain":"SÍ — la situación mostrada permite el adelantamiento: línea discontinua, visibilidad suficiente, sin señal prohibitiva.","val":9,"fase":4},{"id":6450,"bg":"Какво трябва да направи водачът на МПС когато видимостта при движение назад е ограничена?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да осигури човек, който да сигнализира за опасност","ok":true,"i":null,"es":"asegurar una persona que señalice el peligro"},{"t":"да отвори вратата и да гледа назад","ok":false,"i":null,"es":"abrir la puerta y mirar hacia atrás"},{"t":"да отвори страничното стъкло за да гледа назад","ok":false,"i":null,"es":"abrir la ventanilla lateral y mirar atrás"}],"f":6,"es":"¿Qué debe hacer el conductor cuando la visibilidad al hacer marcha atrás es limitada?","explain":"Con visibilidad limitada hacia atrás necesitas una persona fuera del vehículo que vigile y señalice. Abrir la puerta o la ventanilla no elimina los ángulos muertos: sigues sin ver lo que queda detrás y abajo.","val":9,"fase":4},{"id":6452,"bg":"Разрешено ли е движение назад при завиване в обратна посока на кръстовище?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":5,"es":"¿Está permitido ir marcha atrás al dar la vuelta en una intersección?","explain":"No: dar la vuelta en una intersección usando marcha atrás está prohibido. La intersección es zona de conflicto de trayectorias; la maniobra debe completarse con giro continuo hacia delante.","val":8,"fase":4},{"id":5887,"bg":"Ще извърши ли нарушение водачът, ако при тази ситуация завие в обратна посока?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/48171.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":9,"es":"¿Cometerá infracción el conductor si en esta situación cambia de sentido (media vuelta)?","explain":"SÍ, comete infracción. El semáforo muestra una FLECHA verde a la izquierda, y una flecha verde autoriza el movimiento únicamente en la dirección que dibuja. Girar a la izquierda no es lo mismo que cambiar de sentido: la media vuelta no está entre lo que la flecha permite, y las flechas pintadas en su carril tampoco la contemplan. Regla: con flecha verde, solo esa dirección y nada más.","val":13,"fase":3},{"id":5931,"bg":"При тази ситуация при определяне на реда за преминаване през кръстовището се прилагат следните правила:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66850.png","v":null,"a":[{"t":"ППС на пътя с предимство, трябва да преминат преди ППС от другите пътища","ok":true,"i":null,"es":"los de la vía preferente pasan antes que los de otros caminos"},{"t":"ППС на пътя с предимство, помежду си прилагат правилото за „предимството на дясностоящия”","ok":true,"i":null,"es":"los de la preferente entre sí aplican la regla de la derecha"},{"t":"завиващите наляво ППС от пътя с предимство пропускат насрещнодвижещите се ППС","ok":false,"i":null,"es":"los que giran a la izquierda desde la preferente ceden al tráfico contrario"}],"f":7,"es":"En esta situación, para determinar el orden de paso por la intersección se aplican las siguientes reglas: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: los preferentes pasan primero + entre ellos aplican la regla de la derecha. Los que giran a la izquierda NO ceden en esta variante.","val":11,"fase":3},{"id":5948,"bg":"При тази ситуация разрешено ли е да преминете през кръстовището?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51366.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да, но след като пропусна синия автомобил","ok":false,"i":null,"es":"sí, pero después de ceder el paso al automóvil azul"}],"f":8,"es":"En esta situación ¿está permitido pasar por la intersección?","explain":"SÍ — el semáforo o la situación mostrada permite el paso en este momento.","val":12,"fase":3},{"id":5950,"bg":"При несъответствие между сигналите на светофара и пътните знаци относно предимството трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51448.png","v":null,"a":[{"t":"със светлинните сигнали","ok":true,"i":null,"es":"las señales luminosas (el semáforo)"},{"t":"с предписанията на пътните знаци","ok":false,"i":null,"es":"las prescripciones de las señales verticales"}],"f":11,"es":"Cuando hay conflicto entre semáforo y señales de prioridad, debes atenerte a:","explain":"Manda el semáforo: cuando las luces funcionan y contradicen a las señales verticales de prioridad, se obedecen las luces. En la imagen tienes las dos cosas a la vez —un STOP y el semáforo en verde— y pasas sin detenerte, porque la luz anula la señal. El STOP y el ceda el paso solo recuperan el mando si el semáforo está apagado o en amarillo intermitente.","val":16,"fase":3},{"id":6338,"bg":"Задължително ли е спирането на ППС пред жп прелеза, ако бариерите са вдигнати, но светофарът подава мигаща червена светлина?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да, във всички случаи","ok":true,"i":null,"es":"sí, en todos los casos"},{"t":"да, но само когато към прелеза приближава влак","ok":false,"i":null,"es":"sí, pero solo cuando se aproxima un tren"},{"t":"не е задължително","ok":false,"i":null,"es":"no es obligatorio"}],"f":10,"es":"¿Es obligatorio parar ante el paso a nivel si las barreras están levantadas pero el semáforo está rojo?","explain":"Sí, en todos los casos: el semáforo rojo del paso a nivel obliga a parar AUNQUE las barreras estén levantadas: puede tratarse de una avería de las barreras con tren aproximándose. La señal luminosa prevalece.","val":15,"fase":3},{"id":6476,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53752.png","v":null,"a":[{"t":"спирам, за да изчакам разрешаващ сигнал от регулировчика","ok":true,"i":null,"es":"paro para esperar señal de paso del agente"},{"t":"спирам за да пропусна червения автомобил и преминавам след него","ok":false,"i":null,"es":"paro para dejar al rojo y paso después"},{"t":"преминавам преди червения автомобил","ok":false,"i":null,"es":"paso antes que el rojo"}],"f":8,"es":"En esta situación:","explain":"Cuando hay agente, esperamos siempre su señal. No decidimos independientemente quién pasa.","val":11,"fase":3},{"id":6477,"bg":"При движение в тунел с дължина над 500 м, дистанцията между леките автомобили, трябва да е равна на разстоянието, изминавано за две секунди с разрешената скорост на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En túnel de más de 500 m la distancia entre turismos debe ser igual a la distancia de seguridad exterior. Esto es:","explain":"Correcto: en túneles de más de 500 m los turismos en marcha mantienen la misma distancia de seguridad que en el exterior. El túnel no reduce la distancia necesaria de frenada: la oscuridad y el encierro la hacen aún más crítica.","val":11,"fase":3},{"id":6483,"bg":"При тази ситуация разрешено ли е да завиете надясно?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/103209.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":10,"es":"En esta situación ¿está permitido girar a la derecha?","explain":"SÍ. El semáforo de la derecha tiene el disco VERDE encendido (ámbar y roja apagadas). Un verde redondo, sin flechas y sin ninguna señal que lo prohíba, permite el giro a la derecha igual que seguir recto. La trampa es creer que hace falta una flecha verde: la flecha solo aparece cuando ese giro se regula aparte con una sección adicional.","val":14,"fase":3},{"id":6513,"bg":"При тази ситуация червеният автомобил, който завива надясно, е с предимство.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63115.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo que gira a la derecha tiene prioridad. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — girar a la derecha no da prioridad automática. La prioridad la determina la señalización y la posición, no la dirección de giro.","val":11,"fase":3},{"id":6543,"bg":"При тази ситуация червеният автомобил е с предимство, защото се движи направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68524.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":8,"es":"En esta situación el coche rojo tiene prioridad porque va recto. Esto es:","explain":"⚠️ TRAMPA CLÁSICA: INCORRECTO — ir recto nunca da prioridad automática. Esta es una de las preguntas trampa más repetidas del examen búlgaro.","val":13,"fase":3},{"id":6544,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/66249.png","v":null,"a":[{"t":"да пропусна синия автомобил","ok":true,"i":null,"es":"dejar pasar al coche azul"},{"t":"да пропусна жълтия автомобил","ok":true,"i":null,"es":"dejar pasar al coche amarillo"},{"t":"да премина преди червения автомобил","ok":false,"i":null,"es":"pasar antes que el coche rojo"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"MULTIRESPUESTA: cedo al AZUL y al AMARILLO. El panel bajo el ceda el paso dibuja la vía con prioridad como una CURVA: entra por el brazo del rojo y sale por el del amarillo. Los dos circulan por ella, así que les cedo a ambos. El azul viene por un brazo secundario como el mío, pero por mi derecha, así que también pasa primero. 'Pasar antes que el rojo' es falso por el mismo motivo. Clave: la preferencia la da la vía por la que LLEGAS, no la dirección que tomas después — el rojo la conserva aunque abandone la curva hacia el brazo del azul.","val":14,"fase":3},{"id":6548,"bg":"При тази ситуация трябва да премина след:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/82756.png","v":null,"a":[{"t":"червения автомобил","ok":false,"i":null,"es":"el coche rojo"},{"t":"синия автомобил","ok":true,"i":null,"es":"el coche azul"}],"f":9,"es":"En esta situación debo pasar después de:","explain":"Después del AZUL. El panel bajo el rombo dibuja el trazado: la vía con prioridad llega desde tu acceso y GIRA A LA DERECHA, que es por donde está el azul. Los dos vais por ella, así que entre vosotros decide la regla de la derecha y el azul la tiene. El rojo sigue recto por la secundaria, de modo que te cede a ti. Un mismo cruce, dos reglas distintas según por dónde vengas.","val":14,"fase":3},{"id":6552,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65693.png","v":null,"a":[{"t":"да премина преди синия автомобил","ok":true,"i":null,"es":"pasar antes que el coche azul"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"},{"t":"да премина преди жълтия автомобил","ok":true,"i":null,"es":"pasar antes que el coche amarillo"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: tienes prioridad sobre el azul Y el amarillo, pero cedes al rojo.","val":10,"fase":3},{"id":6574,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/68169.png","v":null,"a":[{"t":"да пропусна мотоциклетиста","ok":true,"i":null,"es":"dejar pasar al motorista"},{"t":"да премина преди червения автомобил","ok":true,"i":null,"es":"pasar antes que el coche rojo"},{"t":"да премина преди мотоциклетиста","ok":false,"i":null,"es":"pasar antes que el motorista"},{"t":"да пропусна червения автомобил","ok":false,"i":null,"es":"dejar pasar al coche rojo"}],"f":9,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: cedes al motorista (tiene prioridad) y pasas antes que el rojo. Dos acciones simultáneas según la situación de la imagen.","val":13,"fase":3},{"id":6576,"bg":"При тази ситуация трябва:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67906.png","v":null,"a":[{"t":"да пропусна лекия автомобил","ok":true,"i":null,"es":"dejar pasar al turismo"},{"t":"да пропусна товарния автомобил","ok":true,"i":null,"es":"dejar pasar al camión"},{"t":"да премина преди лекия автомобил","ok":false,"i":null,"es":"pasar antes que el turismo"},{"t":"да премина преди товарния автомобил","ok":false,"i":null,"es":"pasar antes que el camión"}],"f":7,"es":"En esta situación debo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: cedes tanto al turismo como al camión — ambos tienen prioridad sobre ti en esta intersección específica.","val":10,"fase":3},{"id":6674,"bg":"Преминавайки през кръстовището при този сигнал на регулировчика няма да извърша нарушение, при условие, че:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/54571.png","v":null,"a":[{"t":"преди подаването на този сигнал е било разрешено преминаването ми","ok":true,"i":null,"es":"antes de la señal me estaba permitido pasar"},{"t":"в момента на подаването на сигнала съм толкова близо, че не мога да спра безопасно","ok":true,"i":null,"es":"en el momento de la señal estoy tan cerca que no puedo parar con seguridad"},{"t":"подам звуков или светлинен сигнал за това, че ще премина през кръстовището","ok":false,"i":null,"es":"doy señal acústica o luminosa"}],"f":8,"es":"Al pasar por la intersección con esta señal del agente no cometo infracción si: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: igual que ID 6668 — puedes continuar si ya tenías paso O si frenar sería peligroso por la distancia. El claxon no te da derecho a continuar.","val":12,"fase":3},{"id":7962,"bg":"При тази ситуация задължени ли сте да пропуснете товарния автомобил?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64917864.png","v":null,"a":[{"t":"да, независимо от посоката, в която ще продължи да се движи","ok":true,"i":null,"es":"sí, independientemente de la dirección en que continúe"},{"t":"зависи от посоката, в която ще продължи да се движи","ok":false,"i":null,"es":"depende de la dirección en que continúe"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":8,"es":"En esta situación ¿está obligado a dejar pasar al camión?","explain":"SÍ, independientemente de su dirección — el camión está en vía preferente y eso es suficiente para tener prioridad en todos los casos.","val":13,"fase":3},{"id":5368,"bg":"При тази ситуация с предимство е водачът на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/40997.png","v":null,"a":[{"t":"червения автомобил, защото се движи по автомагистралата","ok":true,"i":null,"es":"coche rojo porque circula por la autopista"},{"t":"червения автомобил, защото не променя посоката си на движение","ok":false,"i":null,"es":"coche rojo porque no cambia de dirección"},{"t":"синия автомобил, защото се намира от дясната страна на червения автомобил","ok":false,"i":null,"es":"coche azul porque está a la derecha del rojo"},{"t":"синия автомобил, защото навлиза на автомагистралата","ok":false,"i":null,"es":"coche azul porque entra en la autopista"}],"f":9,"es":"En esta situación tiene prioridad el conductor del:","explain":"El rojo circula por la autopista = tiene prioridad. Los que entran siempre ceden a los que ya circulan, independientemente de su posición relativa.","val":9,"fase":4},{"id":5374,"bg":"При тази ситуация разположението на автомобила върху платното за движение е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41406.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcta"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecta"}],"f":8,"es":"En esta situación la posición del vehículo en la calzada es:","explain":"CORRECTA — posicionado correctamente.","val":8,"fase":4},{"id":5376,"bg":"При тази ситуация:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/41507.png","v":null,"a":[{"t":"ако не мога да изпреваря червения автомобил, трябва да премина в дясната пътна лента","ok":true,"i":null,"es":"si no puedo adelantar al rojo debo pasar al carril derecho"},{"t":"мога да продължа да се движа в лявата лента, без да изпреварвам червения автомобил","ok":false,"i":null,"es":"puedo seguir en el carril izquierdo sin adelantar al rojo"},{"t":"мога да използвам най-удобната за мен пътна лента","ok":false,"i":null,"es":"puedo usar el carril más cómodo"}],"f":11,"es":"En esta situación:","explain":"En autopista el carril izquierdo es para adelantar. Si no estás adelantando activamente, debes ceder el carril izquierdo y volver al derecho.","val":11,"fase":4},{"id":5398,"bg":"На автомагистрала е забранено движението на:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"мотопеди","ok":true,"i":null,"es":"ciclomotores"},{"t":"трактори","ok":true,"i":null,"es":"tractores"},{"t":"съчленени пътни превозни средства","ok":false,"i":null,"es":"vehículos articulados"},{"t":"мотоциклети с кош","ok":false,"i":null,"es":"motos con sidecar"}],"f":7,"es":"En autopista está PROHIBIDA la circulación de: (2 correctas)","explain":"Ciclomotores y tractores no entran en autopista: no alcanzan velocidad segura. Los vehículos articulados y las motos con sidecar sí circulan legalmente por ella.","val":7,"fase":4},{"id":5417,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да спира за престой извън местата обозначени за паркиране","ok":true,"i":null,"es":"parar fuera de lugares señalizados"},{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":8,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"Prohibido: parar fuera de lugares señalizados, entrar/cruzar la mediana y dar la vuelta. Remolcar con barra RÍGIDA sí está permitido (máx. 70 km/h): no confundir con el cable flexible, que solo sirve para salir.","val":8,"fase":4},{"id":5418,"bg":"При движение по автомобилен път на водача е забранено:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да навлиза в разделителната ивица или да я пресича, включително и на местата, където тя е прекъсната","ok":true,"i":null,"es":"entrar en la mediana o cruzarla"},{"t":"да завива в обратна посока","ok":true,"i":null,"es":"dar la vuelta"},{"t":"да се движи назад","ok":true,"i":null,"es":"ir marcha atrás"},{"t":"да тегли повредено МПС с твърда връзка","ok":false,"i":null,"es":"remolcar un vehículo averiado con barra rígida"}],"f":11,"es":"Conduciendo por vía rápida al conductor le está PROHIBIDO: (3 correctas)","explain":"En vía rápida está prohibido: entrar en la mediana o cruzarla, dar la vuelta e ir marcha atrás. Remolcar con barra RÍGIDA sí está permitido (a máximo 70 km/h): la trampa está en confundirlo con el cable flexible.","val":11,"fase":4},{"id":11730,"bg":"На автомагистрала движението в лентата за принудително спиране е:","p":2,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibida"},{"t":"разрешено, без ограничения","ok":false,"i":null,"es":"permitida sin restricciones"},{"t":"разрешено само за МПС, движещи се със скорост по-ниска от 30 km/h","ok":false,"i":null,"es":"permitida para vehículos a menos de 30 km/h"}],"f":9,"es":"En autopista la circulación por el carril de emergencia está:","explain":"CIRCULAR por el carril de emergencia está prohibido: es solo para detenciones de emergencia. Tampoco existe excepción para vehículos lentos: si no alcanzas la velocidad mínima, no puedes estar en autopista.","val":9,"fase":4},{"id":5587,"bg":"При тази ситуация, при преминаване покрай автобуса съм задължен да намаля скоростта.","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39170.png","v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"CORRECTO"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":7,"es":"En esta situación, al pasar junto al autobús estoy obligado a reducir velocidad. Esto es:","explain":"CORRECTO — al pasar junto a un autobús parado en parada debes reducir velocidad por la posibilidad de peatones cruzando imprevistamente.","val":3,"fase":4},{"id":5595,"bg":"При тази ситуация, настигайки спиращия на спирката трамвай, трябва:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/39353.png","v":null,"a":[{"t":"да спра","ok":true,"i":null,"es":"parar"},{"t":"да продължа движението с повишено внимание","ok":false,"i":null,"es":"continuar con precaución"},{"t":"да увелича скоростта","ok":false,"i":null,"es":"acelerar"}],"f":5,"es":"En esta situación, alcanzando el tranvía que para en la parada, debo:","explain":"PARAR — cuando el tranvía para en parada debes detenerte detrás para que los pasajeros puedan bajar y subir con seguridad.","val":3,"fase":4},{"id":12064,"bg":"При тази ситуация трябва да намалите скоростта с готовност за спиране, защото:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":55,"a":[{"t":"автобусът потегля","ok":false,"i":null,"es":"el autobús arranca"},{"t":"пешеходец, слязъл от автобуса, може да пресече платното за движение пред автобуса","ok":true,"i":null,"es":"un peatón que baja del autobús puede cruzar la calzada por delante"},{"t":"пешеходец, който се движи по тротоара, може да пресече платното за движение пред автобуса","ok":true,"i":null,"es":"un peatón de la acera puede cruzar la calzada por delante del autobús"}],"f":5,"es":"En esta situación debe reducir velocidad con disposición de frenar porque: (VIDEO) ⚠️ 2 correctas","explain":"Paso junto a un autobús amarillo detenido en su parada a la derecha: el autobús es una pantalla que oculta gente — debo esperar que un pasajero recién bajado cruce la calzada por DELANTE del autobús, o que un peatón de la acera haga lo mismo. Por eso reduzco con disposición de frenar. 'El autobús arranca' no es el riesgo principal: lo invisible detrás de su carrocería sí lo es.","val":3,"fase":4},{"id":5546,"bg":"Този пътен знак забранява :","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42035.png","v":null,"a":[{"t":"паркирането","ok":true,"i":null,"es":"el aparcamiento"},{"t":"спирането за престой","ok":false,"i":null,"es":"la parada breve"},{"t":"престоя и паркирането","ok":false,"i":null,"es":"la parada breve y el aparcamiento"}],"f":8,"es":"Esta señal prohíbe:","explain":"Esta señal (círculo azul con barra o señal específica) prohíbe SOLO el aparcamiento. La parada breve (prestoy) sigue permitida — diferencia importante.","val":4,"fase":4},{"id":5549,"bg":"След този пътен знак:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42231.png","v":null,"a":[{"t":"е разрешено спирането за престой","ok":true,"i":null,"es":"está permitida la parada breve"},{"t":"е забранено паркирането","ok":true,"i":null,"es":"está prohibido aparcar"},{"t":"е забранено спирането за престой","ok":false,"i":null,"es":"está prohibida la parada breve"},{"t":"е разрешено паркирането","ok":false,"i":null,"es":"está permitido aparcar"}],"f":8,"es":"Después de esta señal: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: esta señal permite la parada breve (prestoy) PERO prohíbe el aparcamiento. Son dos normas diferentes que se aplican simultáneamente.","val":4,"fase":4},{"id":5564,"bg":"Кой от автомобилите е спрян неправилно за престой?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42463.png","v":null,"a":[{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":6,"es":"¿Qué vehículo está incorrectamente detenido para una parada breve?","explain":"Los dos infringen las normas de prestoy — cada uno por razones diferentes según la imagen.","val":3,"fase":4},{"id":5566,"bg":"Кой от автомобилите е паркиран в нарушение на правилата за движение?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/42550.png","v":null,"a":[{"t":"само товарният автомобил","ok":false,"i":null,"es":"solo el camión"},{"t":"само лекият автомобил","ok":false,"i":null,"es":"solo el turismo"},{"t":"и двата автомобила","ok":true,"i":null,"es":"los dos vehículos"}],"f":5,"es":"¿Qué vehículo está aparcado infringiendo las normas?","explain":"Los dos están aparcados incorrectamente — probablemente en zona prohibida, bloqueando la circulación o sin respetar la distancia mínima.","val":2,"fase":4},{"id":5574,"bg":"Спирането за престой по еднопосочен път в населено място:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"е разрешено от дясната страна на пътя","ok":true,"i":null,"es":"está permitida en el lado derecho"},{"t":"се допуска от лявата страна на пътя, ако това не пречи на движението на ППС","ok":true,"i":null,"es":"se admite en el lado izquierdo si no impide la circulación"},{"t":"е разрешено от лявата страна на пътя, без ограничения","ok":false,"i":null,"es":"está permitida en el lado izquierdo sin restricciones"}],"f":8,"es":"La parada breve en calle de sentido único en población: (2 correctas)","explain":"En calle de sentido único en población: parada permitida en el lado derecho y también ADMITIDA en el izquierdo si no impide la circulación. 'Sin restricciones' en el izquierdo es la versión falsa: la condición existe.","val":4,"fase":4},{"id":5581,"bg":"На еднопосочен път в населено място паркирането от лявата страна е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"забранено","ok":true,"i":null,"es":"prohibido"},{"t":"разрешено, когато водачът не напуска превозното средство","ok":false,"i":null,"es":"permitido cuando el conductor no abandona el vehículo"},{"t":"разрешено, ако не се пречи на движението","ok":false,"i":null,"es":"permitido si no se obstaculiza"},{"t":"забранено само за товарни автомобили","ok":false,"i":null,"es":"prohibido solo para camiones"}],"f":5,"es":"En calle de sentido único en zona urbana el aparcamiento en el lado izquierdo está:","explain":"APARCAR en el lado izquierdo de una calle de sentido único está prohibido: la tolerancia del lado izquierdo existe solo para la parada breve (престой) y con condiciones. Aparcar es solo a la derecha.","val":3,"fase":4},{"id":5604,"bg":"Къде по пътищата извън населените места е разрешено паркирането?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"извън платното за движение","ok":true,"i":null,"es":"fuera de la calzada"},{"t":"на обозначените за тази цел места","ok":true,"i":null,"es":"en lugares señalizados para ello"},{"t":"най-вдясно на платното за движение","ok":false,"i":null,"es":"en el extremo derecho de la calzada"}],"f":5,"es":"¿Dónde está permitido aparcar fuera de población? (2 correctas)","explain":"Fuera de población se aparca FUERA de la calzada o en lugares señalizados. El 'extremo derecho de la calzada' sigue siendo calzada: dejarías el coche dentro de la zona de circulación a 90 km/h.","val":3,"fase":4},{"id":5605,"bg":"Правилно ли е паркиран товарният автомобил на този път извън населено място?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43796.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está correctamente aparcado el camión en esta carretera fuera de población?","explain":"NO — fuera de población el aparcamiento debe ser fuera de la calzada o en zona señalizada. En la calzada, aunque sea a la derecha, no está permitido.","val":4,"fase":4},{"id":5607,"bg":"Правилно ли е паркиран товарният автомобил на този път извън населено място?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43845.png","v":null,"a":[{"t":"не, защото трябва да е извън платното за движение","ok":true,"i":null,"es":"no, porque debe estar fuera de la calzada"},{"t":"да, защото е възможно най-вдясно на пътното платно","ok":false,"i":null,"es":"sí, porque está todo lo posible a la derecha de la plataforma vial"},{"t":"не, защото участъкът не е сигнализиран като място за паркиране","ok":false,"i":null,"es":"no, porque el tramo no está señalizado como zona de aparcamiento"}],"f":7,"es":"¿Está correctamente aparcado el camión en esta carretera fuera de población?","explain":"NO — fuera de población el aparcamiento debe ser fuera de la calzada. Estar a la derecha del firme no es suficiente fuera de ciudad.","val":4,"fase":4},{"id":5641,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"в стеснен участък от пътя","ok":true,"i":null,"es":"en tramo estrecho de la vía"},{"t":"в участък с ограничена видимост","ok":true,"i":null,"es":"en tramo con visibilidad limitada"},{"t":"върху трамвайна линия","ok":true,"i":null,"es":"sobre vía de tranvía"},{"t":"на участък от пътя с наклон","ok":false,"i":null,"es":"en tramo de la vía con pendiente"}],"f":7,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar en tramos estrechos (bloqueas el paso), con visibilidad limitada (nadie te ve a tiempo) y sobre vía de tranvía (el tranvía no puede esquivar). La simple pendiente no prohíbe aparcar.","val":3,"fase":4},{"id":5651,"bg":"Разрешено ли е паркирането на ППС в участъци от пътя, които са в ремонт?","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":6,"es":"¿Está permitido aparcar en tramos de vía en obras?","explain":"Sí: aparcar en tramos en obras está permitido salvo que una señal lo prohíba expresamente. Las obras restringen por señalización, no por sí mismas.","val":3,"fase":4},{"id":7809,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 м преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 м след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"f":11,"es":"El aparcamiento está PROHIBIDO: (2 correctas)","explain":"El aparcamiento está prohibido sobre el paso de peatones y a menos de 5 m ANTES de él (taparía la visibilidad del peatón que va a cruzar). Después del paso no rige la prohibición.","val":5,"fase":4},{"id":8284,"bg":"Паркирането е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на места, определени за ППС, обслужващи хора с трайни увреждания","ok":true,"i":null,"es":"en plazas reservadas para personas con discapacidad"},{"t":"до паркирано или спряно за престой ППС, от страната на движението","ok":true,"i":null,"es":"al lado de un vehículo parado o en prestoy, por el lado del tráfico"},{"t":"на мост","ok":true,"i":null,"es":"en puente"},{"t":"на участък от пътя в ремонт","ok":false,"i":null,"es":"en tramo de vía en obras"}],"f":8,"es":"El aparcamiento está PROHIBIDO: (3 correctas)","explain":"Prohibido aparcar: en plazas reservadas a personas con discapacidad, en doble fila (junto a otro parado, por el lado del tráfico) y en puente. El tramo en obras solo lo prohíbe si está señalizado: por eso es la falsa.","val":4,"fase":4},{"id":11590,"bg":"Спирането върху платното за движение след този пътен знак е:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43420.png","v":null,"a":[{"t":"разрешено за слизане на пътник от автомобила","ok":false,"i":null,"es":"permitida para que un pasajero baje del coche"},{"t":"забранено за извършване на товарно-разтоварна дейност","ok":true,"i":null,"es":"prohibida para carga y descarga"},{"t":"забранено за паркиране","ok":true,"i":null,"es":"prohibida para aparcar"},{"t":"разрешено за качване на пътник в автомобила","ok":false,"i":null,"es":"permitida para que un pasajero suba al coche"}],"f":7,"es":"La parada sobre la calzada después de esta señal está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: la señal prohíbe la carga/descarga Y el aparcamiento. Las paradas para subir o bajar pasajeros siguen permitidas brevemente.","val":3,"fase":4},{"id":11873,"bg":"Когато паркирането върху тротоара е разрешено, допустимата максимална маса на паркираното превозното средство не трябва да е по-голяма от:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"2,5 t","ok":true,"i":null,"es":"2.5 t"},{"t":"1,0 t","ok":false,"i":null,"es":"1.0 t"},{"t":"1,5 t","ok":false,"i":null,"es":"1.5 t"},{"t":"2,0 t","ok":false,"i":null,"es":"2.0 t"}],"f":11,"es":"Cuando el aparcamiento sobre la acera está permitido, la masa máxima del vehículo aparcado es:","explain":"2,5 t: es la masa máxima del vehículo que puede aparcar sobre la acera donde está permitido y señalizado. Por encima, el peso daña el pavimento peatonal.","val":5,"fase":4},{"id":11892,"bg":"Спирането за престой е забранено:","p":1,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"на пешеходна пътека","ok":true,"i":null,"es":"en paso de peatones"},{"t":"на разстояние по-малко от 5 метра преди пешеходна пътека","ok":true,"i":null,"es":"a menos de 5 m ANTES del paso de peatones"},{"t":"на разстояние по-малко от 5 метра след пешеходна пътека","ok":false,"i":null,"es":"a menos de 5 m DESPUÉS del paso de peatones"}],"f":12,"es":"La parada breve (prestoy) está PROHIBIDA: (2 correctas)","explain":"La parada breve está prohibida SOBRE el paso de peatones y a menos de 5 m ANTES de él: taparías el paso justo donde el peatón aparece. DESPUÉS del paso no hay prohibición: el peatón ya cruzó por detrás de ti.","val":6,"fase":4},{"id":5687,"bg":"През нощта движението зад друго МПС на разстояние по-малко от 50 м се извършва с включени:","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"къси светлини","ok":true,"i":null,"es":"luces cortas"},{"t":"дълги светлини","ok":false,"i":null,"es":"luces largas"},{"t":"само габаритни светлини","ok":false,"i":null,"es":"solo luces de posición"}],"f":5,"es":"De noche, circulando detrás de otro vehículo a menos de 50 m, se circula con:","explain":"Con cortas: a menos de 50 m detrás de otro, las largas lo deslumbran por los tres retrovisores. Solo posición te deja sin ver la vía: las cortas son el equilibrio obligatorio.","val":2,"fase":4},{"id":6685,"bg":"Кое от изброените действия е най-опасно при движение по този заледен пътен участък?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/29191.png","v":null,"a":[{"t":"рязкото подаване на газ","ok":true,"i":null,"es":"dar gas de golpe"},{"t":"задържане натиснат педала на съединителя","ok":false,"i":null,"es":"mantener el pedal del embrague pisado"},{"t":"превключването на скоростния механизъм","ok":false,"i":null,"es":"cambiar de marcha"}],"f":8,"es":"¿Cuál es la acción más peligrosa circulando por este tramo de hielo?","explain":"Dar gas bruscamente en hielo = las ruedas patinan y pierdes el control. En hielo siempre: movimientos suaves y progresivos en todos los pedales y el volante.","val":4,"fase":4},{"id":8285,"bg":"През деня, моторните превозни средства се движат с включени светлини за движение през деня или с къси светлини.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":6,"es":"De día, los vehículos a motor circulan con luces diurnas o luces cortas encendidas. Esto es:","explain":"Correcto: de día es obligatorio circular con luces diurnas o de cruce encendidas: ser visto es la mitad de la seguridad. La norma rige todo el año, no solo en invierno.","val":3,"fase":4},{"id":11634,"bg":"Използването на дългите светлини е забранено, когато при снеговалеж видимостта е намалена.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":false,"i":null,"es":"correcto"},{"t":"не е забранено, но е неправилно","ok":true,"i":null,"es":"no está prohibido pero es incorrecto"}],"f":5,"es":"Usar las luces largas está prohibido cuando la visibilidad es reducida por nevada.","explain":"'No está prohibido pero es incorrecto': con nevada las largas no violan la ley, pero la luz rebota en los copos y ves PEOR: es un error técnico, no jurídico. La distinción legal/técnico es exactamente lo que pregunta.","val":2,"fase":4},{"id":12070,"bg":"Какво е правилното поведение при тази ситуация (поради мъгла видимостта е намалена под 50 m)?","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":62,"a":[{"t":"намалявам скоростта","ok":true,"i":null,"es":"reduzco la velocidad"},{"t":"включвам задните светлини за мъгла","ok":true,"i":null,"es":"enciendo las luces traseras antiniebla"},{"t":"управлявам с допустимата за пътя скорост","ok":false,"i":null,"es":"circulo a la velocidad permitida para esa vía"}],"f":9,"es":"¿Cuál es el comportamiento correcto en esta situación? Visibilidad reducida a menos de 50 m por niebla. (VIDEO) ⚠️ 2 correctas","explain":"Niebla con visibilidad por debajo de 50 m (el vehículo de delante apenas se distingue): REDUZCO la velocidad adaptándola a lo que realmente veo y ENCIENDO las luces traseras antiniebla para que me localicen por detrás. 'Circular a la velocidad permitida de la vía' es la trampa: el límite legal no es un derecho — con visibilidad reducida debes poder detenerte dentro del tramo que ves.","val":5,"fase":4},{"id":5708,"bg":"Движението при едни и същи условия, по ежедневно използван маршрут, води до привикване с пътната обстановка и отслабване на вниманието.","p":1,"s":"Раздел 5. ФАКТОРИТЕ, КОИТО ОКАЗВАТ ВЛИЯНИЕ ВЪРХУ ПОВЕДЕНИЕТО НА ВОДАЧИТЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":11,"es":"Conducir diariamente por la misma ruta en condiciones idénticas lleva a familiarizarse con la situación vial. Esto es:","explain":"Correcto: la ruta diaria idéntica familiariza con la situación... y ahí está el peligro que el banco quiere que reconozcas después: la familiaridad relaja la atención. La afirmación literal es cierta.","val":5,"fase":4},{"id":5995,"bg":"Задължение на водача е превозваният товар:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да е покрит, когато отразява светлината и може да заслепи други участници в движението","ok":true,"i":null,"es":"esté cubierta cuando refleja la luz y puede deslumbrar"},{"t":"да е укрепен","ok":true,"i":null,"es":"esté asegurada"},{"t":"да не закрива светлинните устройства на автомобила","ok":true,"i":null,"es":"no cubra los dispositivos luminosos del vehículo"},{"t":"да е опакован съгласно изискванията на производителя","ok":false,"i":null,"es":"esté embalada según las exigencias del fabricante"}],"f":4,"es":"El conductor está obligado a que la carga transportada: (3 correctas)","explain":"La carga debe: ir cubierta si refleja y puede deslumbrar, estar asegurada (sujeta) y no tapar las luces del vehículo. El 'embalaje según el fabricante' no es requisito del código de circulación: es logística, no seguridad vial.","val":2,"fase":4},{"id":6020,"bg":"Движещите се по пътя три- и четириколесни моторни превозни средства трябва да бъдат оборудвани:","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"с аптечка","ok":true,"i":null,"es":"botiquín de primeros auxilios"},{"t":"със светлоотразителна жилетка","ok":true,"i":null,"es":"chaleco reflectante"},{"t":"с обезопасителен триъгълник","ok":true,"i":null,"es":"triángulo de seguridad"},{"t":"с вериги за движение през зимата","ok":false,"i":null,"es":"cadenas para nieve"}],"f":6,"es":"Los vehículos de motor de 3 y 4 ruedas deben ir equipados con: (3 correctas)","explain":"Equipamiento obligatorio: botiquín, chaleco reflectante y triángulo de seguridad. Las cadenas de nieve solo son obligatorias cuando la señalización o las condiciones lo exigen, no como dotación permanente.","val":3,"fase":4},{"id":11441,"bg":"Разрешено ли е водачът на МПС да използва пътищата, отворени за обществено ползване, за други цели, освен в съответствие с тяхното предназначение?","p":1,"s":"Раздел 6. ЗАДЪЛЖЕНИЯ И ОТГОВОРНОСТИ НА ВОДАЧИТЕ НА ПРЕВОЗНИТЕ СРЕДСТВА","i":null,"v":null,"a":[{"t":"да","ok":false,"i":null,"es":"sí"},{"t":"не","ok":true,"i":null,"es":"no"}],"f":4,"es":"¿Está permitido al conductor usar las vías abiertas al público para otros fines?","explain":"No: las vías públicas son para circular. Usarlas para otros fines (carreras, pruebas, eventos) exige autorización especial: por defecto está prohibido.","val":2,"fase":4},{"id":5912,"bg":"Значенето на кой от показаните немигащи сигнали на светофара е “Внимание спри!”?","p":3,"s":"Раздел 4","i":null,"v":null,"a":[{"t":"","ok":true,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43199.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43200.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43201.png","es":""},{"t":"","ok":false,"i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/43202.png","es":""}],"f":11,"es":"¿Cuál de las señales fijas del semáforo tiene el significado de '¡Atención, para!'?","explain":"Busca la imagen con el semáforo AMARILLO encendido. Amarillo fijo = Atención, para. Esta es una pregunta visual — las respuestas son imágenes de semáforos.","val":16,"fase":3},{"id":6102,"bg":"С какво трябва да се съобразявате при отварянето на капачката на разширителния резервоар на охладителната уредба при загрят двигател?","p":1,"s":"Раздел 1. ОБЩИ СВЕДЕНИЯ ЗА АВТОМОБИЛА","i":null,"v":null,"a":[{"t":"с опасността от заливане с гореща охладителна течност","ok":true,"i":null,"es":"el peligro de quemarse con el líquido refrigerante caliente"},{"t":"с намаляване на количеството на охладителната течност поради изпаряване","ok":false,"i":null,"es":"la reducción del líquido por evaporación"},{"t":"с понижаването на температурата на охладителната течност","ok":false,"i":null,"es":"el enfriamiento del líquido"}],"f":3,"es":"¿Qué debes tener en cuenta al abrir el tapón del depósito de expansión del líquido refrigerante?","explain":"Cuidado con QUEMARTE: el circuito de refrigeración caliente está a presión y por encima de 100 °C: al abrir el tapón puede salir líquido y vapor a chorro. Se abre solo en frío: la evaporación o el enfriamiento no son el peligro.","val":1,"fase":4},{"id":5166,"bg":"Този пътен знак предупреждава за:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334664.png","v":null,"a":[{"t":"опасен завой надясно","ok":true,"i":null,"es":"curva peligrosa a la derecha"},{"t":"опасност ППС да излезе от пътя надясно","ok":false,"i":null,"es":"peligro de salirse de la vía a la derecha"},{"t":"кръстовище, на което задължително трябва да се завие надясно","ok":false,"i":null,"es":"intersección con giro obligatorio a la derecha"},{"t":"място за паркиране край пътя","ok":false,"i":null,"es":"zona de aparcamiento junto a la vía"}],"f":4,"es":"Esta señal advierte de:","explain":"Señal triangular con curva = advertencia de curva peligrosa a la derecha. No es obligación de girar ni peligro de salirse — es aviso preventivo.","val":4,"fase":4},{"id":5189,"bg":"При навлизане в завой, с увеличаването на скоростта, устойчивостта на превозното средство се влошава.","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"правилно","ok":true,"i":null,"es":"correcto"},{"t":"неправилно","ok":false,"i":null,"es":"incorrecto"}],"f":5,"es":"Al entrar en una curva, con el aumento de la velocidad, la estabilidad del vehículo empeora. Esto es:","explain":"Correcto: a más velocidad en la misma curva, más fuerza centrífuga (crece con el cuadrado de la velocidad) y peor estabilidad. Por eso la velocidad se reduce ANTES de entrar en la curva.","val":5,"fase":4},{"id":5193,"bg":"Как се променя устойчивостта на превозното средство, при движение в завой, с намаляване на радиуса на завоя?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"влошава се","ok":true,"i":null,"es":"empeora"},{"t":"подобрява се","ok":false,"i":null,"es":"mejora"},{"t":"не се променя","ok":false,"i":null,"es":"no cambia"}],"f":6,"es":"¿Cómo cambia la estabilidad del vehículo en curva al reducirse el radio de la curva?","explain":"Empeora: a menor radio (curva más cerrada), mayor fuerza centrífuga a igual velocidad, y el vehículo tiende más a salirse o volcar. Radio pequeño exige velocidad pequeña.","val":6,"fase":4},{"id":5196,"bg":"Този пътен знак предупреждава, за приближаване към:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/21171.png","v":null,"a":[{"t":"платно за движение, стеснено от двете страни","ok":true,"i":null,"es":"calzada estrecha por ambos lados"},{"t":"мост","ok":false,"i":null,"es":"puente"},{"t":"тунел","ok":false,"i":null,"es":"túnel"},{"t":"съоръжение за аварийно спиране","ok":false,"i":null,"es":"dispositivo de parada de emergencia"}],"f":5,"es":"Esta señal advierte de la aproximación a:","explain":"Esta señal específica (calzada que se estrecha desde ambos lados) advierte de un estrechamiento bilateral. No es puente ni túnel — aunque se parezcan, tienen señales propias.","val":5,"fase":4},{"id":5258,"bg":"Този пътен знак:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334673.png","v":null,"a":[{"t":"предупреждава за кръстовище с път отдясно, който е без предимство","ok":true,"i":null,"es":"advierte de intersección con vía a la derecha sin prioridad"},{"t":"указва посоки за преминаване на следващото кръстовище","ok":false,"i":null,"es":"indica direcciones en la próxima intersección"},{"t":"сигнализира място за спиране край пътя","ok":false,"i":null,"es":"señaliza zona de parada junto a la vía"},{"t":"сигнализира за уширение на платното за движение","ok":false,"i":null,"es":"señaliza ensanchamiento de la calzada"}],"f":4,"es":"Esta señal:","explain":"Señal de advertencia de intersección con vía a la derecha sin prioridad — informa de que habrá una vía secundaria incorporándose. No es una señal de dirección.","val":4,"fase":4},{"id":5296,"bg":"На показаната схема с буква „в” е означен пътният знак, който сигнарлизира, че разстоянието до железопътния прелез е:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/27779.png","v":null,"a":[{"t":"80 м","ok":false,"i":null,"es":"80 m"},{"t":"160 м","ok":false,"i":null,"es":"160 m"},{"t":"240 м","ok":true,"i":null,"es":"240 m"}],"f":5,"es":"En el esquema mostrado, con la letra \"в\" está indicada la señal que informa de que la distancia hasta el paso a nivel es:","explain":"En Bulgaria las señales previas al paso a nivel se colocan a 240m (tres barras), 160m (dos barras) y 80m (una barra). La 'в' indica la más alejada = 240 metros.","val":5,"fase":4},{"id":5540,"bg":"При коя от изброените височини автомобилът е извънгабаритен:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"височина 4,5 м","ok":true,"i":null,"es":"altura 4.5 m"},{"t":"височина 4,3 м","ok":true,"i":null,"es":"altura 4.3 m"},{"t":"височина 4,1 м","ok":true,"i":null,"es":"altura 4.1 m"},{"t":"височина 3,9 м","ok":false,"i":null,"es":"altura 3.9 m"}],"f":4,"es":"¿A qué altura es un vehículo fuera de gálibo? (3 correctas)","explain":"El límite de altura es 4 m: 4,1, 4,3 y 4,5 m lo superan y son fuera de gálibo; 3,9 m queda dentro. Basta comparar cada cifra con el umbral de 4.","val":4,"fase":4},{"id":5807,"bg":"Слизането на деца до 12 години от автомобил, спрял на платното за движение, се извършва от:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"страната на тротоара","ok":true,"i":null,"es":"el lado de la acera"},{"t":"страната на пътния банкет","ok":true,"i":null,"es":"el lado del arcén"},{"t":"страната на водача на МПС","ok":false,"i":null,"es":"el lado del conductor"},{"t":"от по-удобната за водача страна","ok":false,"i":null,"es":"el lado más cómodo para el conductor"}],"f":3,"es":"La bajada de niños menores de 12 años de un vehículo parado en la calzada se realiza por: (2 correctas)","explain":"Los menores de 12 años bajan por el lado de la ACERA o del ARCÉN: nunca hacia el tráfico. El lado del conductor da a la calzada: justo donde pasan los coches.","val":3,"fase":4},{"id":6040,"bg":"Сигналът за извършване на маневра се подава:","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":null,"a":[{"t":"преди започване на маневрата","ok":true,"i":null,"es":"antes de iniciar la maniobra"},{"t":"със започване на маневрата","ok":false,"i":null,"es":"al inicio de la maniobra"},{"t":"след започване на маневрата","ok":false,"i":null,"es":"después de iniciar la maniobra"}],"f":4,"es":"La señal de maniobra se da:","explain":"La señal se da ANTES de iniciar la maniobra: su función es avisar con antelación para que los demás reaccionen. Señalizar al inicio o después ya no avisa nada: solo describe lo que ya está pasando.","val":4,"fase":4},{"id":12023,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":2,"s":"Раздел 2. ЗАПОЗНАВАНЕ С ПЪТИЩАТА, ПРЕВОЗНИТЕ СРЕДСТВА И УЧАСТНИЦИТЕ В ПЪТНОТО ДВИЖЕНИЕ","i":null,"v":7,"a":[{"t":"продължавам да се движа с ниска скорост/бавно, тъй като няма признаци, че някой пешеходец иска да премине по пътеката","ok":false,"i":null,"es":"continúo lentamente porque no hay indicios de que nadie vaya a cruzar"},{"t":"спирам, защото детето на левия тротоар ще слезе на платното за движение","ok":false,"i":null,"es":"paro porque el niño de la acera izquierda bajará a la calzada"},{"t":"спирам, защото човекът, който приближава отдясно бягайки, ще премине по пешеходната пътека","ok":true,"i":null,"es":"paro porque la persona que corre por la derecha cruzará el paso de peatones"}],"f":4,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"🎬 VIDEO: la persona que corre desde la derecha se dirige al paso de peatones — debes parar. El niño de la izquierda está en la acera sin señales de cruzar. La persona corriendo es la prioridad.","val":4,"fase":4},{"id":6076,"bg":"Разположението върху пътя на червения автомобил, движещ се извън населено място е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/60500.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":9,"es":"La posición del coche rojo que circula fuera de población es:","explain":"INCORRECTA. Circula por el carril izquierdo teniendo libre el derecho, y fuera de población hay que ir lo más a la derecha posible. El carril izquierdo se ocupa para adelantar y se abandona al terminar; no es un carril de viaje. Que no moleste a nadie en ese momento no lo legaliza: la obligación de ir a la derecha no depende de que haya tráfico o no.","val":14,"fase":3},{"id":6096,"bg":"При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63543.png","v":null,"a":[{"t":"е разрешено да използвам за движение най-удобната за мен пътна лента","ok":true,"i":null,"es":"está permitido usar el carril que me resulte más cómodo"},{"t":"длъжен съм да се движа възможно най-вдясно на платното за движение","ok":false,"i":null,"es":"estoy obligado a circular lo más a la derecha posible de la calzada"},{"t":"трябва да се движа в най-дясната свободна лента","ok":false,"i":null,"es":"debo circular por el carril libre situado más a la derecha"}],"f":11,"es":"En esta situación:","explain":"En población y con varios carriles marcados para tu sentido (mira el panel bajo el «60»: indica los carriles), la ley te deja usar el que te resulte más cómodo. Ir «lo más a la derecha posible» o «por el carril libre más a la derecha» es la regla de FUERA de población o de calzada sin carriles marcados. Palabras clave para decidir: ¿población + carriles marcados en mi sentido? → elijo carril libremente.","val":16,"fase":3},{"id":6099,"bg":"При тази ситуация водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/63839.png","v":null,"a":[{"t":"може да продължи да се движи в лявата лента","ok":true,"i":null,"es":"puede continuar en el carril izquierdo"},{"t":"може да използва за движение по-удобната за него пътна лента","ok":true,"i":null,"es":"puede usar el carril más cómodo"},{"t":"трябва да премине в дясната лента","ok":false,"i":null,"es":"debe pasar al carril derecho"},{"t":"трябва да се движи в най-дясната свободна лента","ok":false,"i":null,"es":"debe circular por el carril libre situado más a la derecha"}],"f":9,"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"MULTIRESPUESTA: puede seguir en el carril izquierdo y puede usar el que le resulte más cómodo. Estamos EN POBLACIÓN, y con dos o más carriles en el mismo sentido el conductor elige por cuál circula. Las otras dos exigen bajarse al carril más a la derecha, que es la regla de FUERA de población. La misma maniobra es correcta en ciudad e infracción en carretera.","val":14,"fase":3},{"id":6404,"bg":"При тази ситуация няма да извърша нарушение ако:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64182.png","v":null,"a":[{"t":"премина в дясната пътна лента","ok":true,"i":null,"es":"paso al carril derecho"},{"t":"продължа движението си в същата пътна лента","ok":true,"i":null,"es":"continúo en el mismo carril"},{"t":"премина в лявата пътна лента","ok":false,"i":null,"es":"paso al carril izquierdo"},{"t":"спра пред светофара, в лентата, над която е поставен","ok":false,"i":null,"es":"paro ante el semáforo, en el carril sobre el que está colocado"}],"f":9,"es":"En esta situación no cometo infracción si: (2 correctas)","explain":"MULTIRESPUESTA: pasar al carril derecho o seguir en el mismo. El pórtico lleva semáforos de carril: la flecha VERDE hacia abajo indica que ese carril está abierto, y la X marca el carril cerrado. Por eso no puedes irte al izquierdo. Y detenerte ante el pórtico tampoco: la flecha verde ordena continuar, y pararse en un carril abierto crea el peligro que la señal quiere evitar.","val":14,"fase":3},{"id":6438,"bg":"При тази ситуация, на водача на червения автомобил е разрешено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64417.png","v":null,"a":[{"t":"да продължи движението си в същата пътна лента","ok":true,"i":null,"es":"continuar en el mismo carril"},{"t":"да премине в дясната пътна лента","ok":true,"i":null,"es":"pasar al carril derecho"},{"t":"да премине в лявата пътна лента","ok":false,"i":null,"es":"pasar al carril izquierdo"}],"f":8,"es":"En esta situación, al conductor del coche rojo le está PERMITIDO: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rojo puede quedarse en su carril actual O pasar al derecho. El izquierdo no está permitido en esta situación.","val":13,"fase":3},{"id":6446,"bg":"На кои ППС е разрешено движението в BUS - лентата след този знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/64672.png","v":null,"a":[{"t":"на ППС от редовните линии за обществен превоз на пътници","ok":true,"i":null,"es":"a los vehículos de líneas regulares de transporte público"},{"t":"на всички автобуси","ok":false,"i":null,"es":"a todos los autobuses"},{"t":"на таксиметровите автомобили","ok":false,"i":null,"es":"a los taxis"},{"t":"на бавнодвижещите се превозни средства","ok":false,"i":null,"es":"a los vehículos lentos"}],"f":9,"es":"¿A qué vehículos está permitido circular por el carril BUS después de esta señal?","explain":"Solo los vehículos de LÍNEAS REGULARES de transporte público. El carril BUS está reservado al servicio de línea, y ese es el criterio: no el tamaño ni el tipo de vehículo. Por eso 'todos los autobuses' es falso — un autocar privado no entra. Los taxis tampoco, salvo que una señal lo autorice expresamente. Y los vehículos lentos van a la derecha, pero fuera del carril BUS.","val":14,"fase":3},{"id":6455,"bg":"При тази ситуация в средната пътна лента е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/65112.png","v":null,"a":[{"t":"разрешено движението на автобуси с ремаркета","ok":false,"i":null,"es":"permitida la circulación de autobuses con remolque"},{"t":"разрешено движението на леки автомобили с ремаркета","ok":false,"i":null,"es":"permitida la circulación de turismos con remolque"},{"t":"забранено движението на товарни автомобили с ремаркета","ok":true,"i":null,"es":"prohibida la circulación de camiones con remolque"},{"t":"забранено движението на товарни автомобили с полуремаркета","ok":true,"i":null,"es":"prohibida la circulación de camiones con semirremolque"}],"f":8,"es":"En esta situación en el carril central está: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el carril central prohíbe camiones con remolque Y con semirremolque. Los autobuses y turismos con remolque SÍ pueden usar ese carril.","val":12,"fase":3},{"id":6462,"bg":"Мотопедистите могат да използват за движение пътния банкет, който:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"се намира отдясно по посока на движението им","ok":true,"i":null,"es":"está a la derecha en su sentido de marcha"},{"t":"се намира отляво по посока на движението им","ok":false,"i":null,"es":"está a la izquierda en su sentido de marcha"},{"t":"е по-удобен за тях, независимо от коя страна на пътя се намира","ok":false,"i":null,"es":"sea más cómodo independientemente de su lado"}],"f":9,"es":"Los ciclomotores pueden usar el arcén que:","explain":"Solo el arcén DERECHO en su sentido de marcha: los ciclomotores circulan siempre pegados a la derecha. Usar el arcén izquierdo significaría circular a contramano del flujo, y la 'comodidad' no es criterio legal.","val":13,"fase":3},{"id":9838,"bg":"При тази ситуация разположението на червения автомобил върху платното за движение е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/270043160.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"incorrecta"},{"t":"правилно","ok":false,"i":null,"es":"correcta"}],"f":9,"es":"En esta situación la posición del coche rojo en la calzada es:","explain":"INCORRECTA — el coche rojo no está en el carril correcto o circula de forma que no cumple con las normas de posicionamiento.","val":14,"fase":3},{"id":11685,"bg":"Кои от посочените условия е необходимо да бъдат налице за да може при движение в населено място водачът да използва най-удобната за него пътна лента?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/62284.png","v":null,"a":[{"t":"пътното платно да е с две и повече пътни ленти за движение в една посока","ok":true,"i":null,"es":"la calzada tiene dos o más carriles en una dirección"},{"t":"броят на пътните ленти и посоките за движение по тях да са обозначени с пътен знак","ok":true,"i":null,"es":"el número de carriles y las direcciones están señalizados"},{"t":"разрешената скорост за движение да е не по-голяма от 80 km/h","ok":true,"i":null,"es":"la velocidad máxima permitida es no superior a 80 km/h"},{"t":"пътят да е с две платна за движение","ok":false,"i":null,"es":"la vía tiene dos calzadas de circulación"}],"f":9,"es":"¿Qué condiciones deben cumplirse para que, circulando en poblado, el conductor pueda usar el carril más cómodo para él? (3 correctas)","explain":"⚠️ MULTIRESPUESTA: 2+ carriles + señalización de carriles + máximo 80 km/h. Tener dos calzadas separadas NO es una condición para esto.","val":14,"fase":3},{"id":5797,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334711.png","v":null,"a":[{"t":"сигнализира за край на ограничението на скоростта, въведено с пътен знак","ok":true,"i":null,"es":"señaliza el final de la limitación de velocidad impuesta por señal"},{"t":"забранява движението на МПС, които не могат да развият скорост, по-голяма от означената","ok":false,"i":null,"es":"prohíbe circular a vehículos que no pueden alcanzar la velocidad indicada"},{"t":"забрананява движението със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"забрананява движението със скорост, по-ниска от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad inferior a la indicada"}],"f":6,"es":"Esta señal:","explain":"Esta señal (velocidad tachada o fin de zona) señaliza el FIN de la limitación de velocidad establecida por la señal anterior. No es nueva restricción.","val":9,"fase":4},{"id":5798,"bg":"След този пътен знак няма ограничение за скоростта на движение.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/53963.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":6,"es":"Después de esta señal no hay ninguna limitación de velocidad. Esto es:","explain":"⚠️ TRAMPA: INCORRECTO — aunque haya terminado la restricción específica señalizada, siguen aplicando los límites generales de la vía (50 en ciudad, 90 en carretera, etc.).","val":9,"fase":4},{"id":5821,"bg":"Този пътен знак:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/334713.png","v":null,"a":[{"t":"указва задължителна минимална скорост за движение","ok":true,"i":null,"es":"indica velocidad mínima obligatoria"},{"t":"забранява движение със скорост, по-висока от означената","ok":false,"i":null,"es":"prohíbe circular a velocidad superior a la indicada"},{"t":"указва препоръчителна скорост за движение","ok":false,"i":null,"es":"indica velocidad recomendada"}],"f":5,"es":"Esta señal:","explain":"Señal de velocidad mínima obligatoria (número en círculo azul) — debes circular AL MENOS a esa velocidad. Diferente del límite máximo (círculo rojo).","val":7,"fase":4},{"id":5827,"bg":"При тази ситуация разрешено ли е движение със скорост по-ниска от означената?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/57482.png","v":null,"a":[{"t":"да, когато няма необходимите условия за безопасност","ok":true,"i":null,"es":"sí, cuando no hay las condiciones necesarias de seguridad"},{"t":"да, във всички случаи","ok":false,"i":null,"es":"sí, en todos los casos"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":5,"es":"En esta situación ¿está permitido circular a velocidad inferior a la indicada?","explain":"SÍ pero solo cuando la seguridad lo requiere — lluvia, hielo, niebla, obstáculos. La velocidad mínima cede ante la seguridad. No puedes ir más lento por comodidad.","val":8,"fase":4},{"id":5905,"bg":"При тази ситуация, за да осигуря по-голяма безопасност за децата, е достатъчно само да увелича страничната дистанция.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58320.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":3,"es":"En esta situación, para dar mayor seguridad a los niños, es suficiente con solo aumentar la distancia lateral. Esto es:","explain":"INCORRECTO — ante niños en la vía no basta con prestar más atención. Debes reducir velocidad. La atención sin reducción de velocidad no garantiza la capacidad de frenar a tiempo.","val":4,"fase":4},{"id":5907,"bg":"При тази ситуация, за да осигуря безопасността за велосипедиста при изпреварването, е достатъчно само да намаля скоростта.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/58514.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación, para garantizar la seguridad del ciclista al adelantarlo, es suficiente con solo reducir la velocidad. Esto es:","explain":"INCORRECTO — al adelantar a un ciclista necesitas tanto atención como distancia lateral mínima de 1.5 metros. Solo la atención sin distancia suficiente no es seguro.","val":7,"fase":4},{"id":6696,"bg":"Най-силно влияние върху големината на коефициента на сцепление на автомобилните гуми с пътя оказват:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"състоянието на пътната настилка","ok":true,"i":null,"es":"el estado del pavimento"},{"t":"състоянието на автомобилната гума","ok":true,"i":null,"es":"el estado del neumático"},{"t":"видът на окачването на автомобила","ok":false,"i":null,"es":"el tipo de suspensión del vehículo"},{"t":"диаметърът на автомобилните гуми","ok":false,"i":null,"es":"el diámetro de los neumáticos"}],"f":3,"es":"¿Qué factor influye más en el coeficiente de rozamiento de los neumáticos con el pavimento? (2 correctas)","explain":"Los dos factores dominantes del rozamiento: estado del PAVIMENTO (seco/mojado/hielo) y estado del NEUMÁTICO (dibujo, desgaste). La suspensión y el diámetro no determinan la adherencia.","val":5,"fase":4},{"id":11699,"bg":"Когато няма други ограничения, водачът на автомобил от категория В1 при движение в населено място не трябва да превишава:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"50 km/h","ok":true,"i":null,"es":"50 km/h"},{"t":"40 km/h","ok":false,"i":null,"es":"40 km/h"},{"t":"60 km/h","ok":false,"i":null,"es":"60 km/h"},{"t":"55 km/h","ok":false,"i":null,"es":"55 km/h"}],"f":5,"es":"Sin otras restricciones, el conductor de vehículo categoría B1 en zona urbana puede circular a máximo:","explain":"50 km/h: los B1 (cuadriciclos pesados) siguen el límite urbano general. En población, 50 km/h es el techo para todos los vehículos de motor salvo señal.","val":8,"fase":4},{"id":12003,"bg":"Какво трябва да направите при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":12,"a":[{"t":"да намаля скоростта и да управлявам с готовност за спиране","ok":true,"i":null,"es":"reducir velocidad y circular listo para frenar"},{"t":"да продължа движението си, без да променям скоростта си","ok":false,"i":null,"es":"continuar sin cambiar la velocidad"},{"t":"да навляза в лявата пътна лента","ok":false,"i":null,"es":"cambiar al carril izquierdo"}],"f":7,"es":"¿Qué debes hacer en esta situación? (VIDEO)","explain":"🎬 VIDEO: ante obstáculo en la vía siempre reduces velocidad y te preparas para frenar. Cambiar de carril sin visibilidad es peligroso. Continuar igual tampoco.","val":10,"fase":3},{"id":6226,"bg":"При тази ситуация, водачът на червения автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69536.png","v":null,"a":[{"t":"трябва да пропусне синия автомобил, защото навлиза в лентата, по която той се движи","ok":true,"i":null,"es":"debe dejar pasar al azul porque entra en su carril"},{"t":"преди да се включи в движението трябва да се убеди, че няма да създаде опасност за другите участници в него","ok":true,"i":null,"es":"antes de incorporarse debe asegurarse de no crear peligro"},{"t":"е с предимство защото се намира отдясно","ok":false,"i":null,"es":"tiene prioridad porque está a la derecha"}],"f":7,"es":"En esta situación el conductor del coche rojo: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: el rojo cede porque invade el carril del azul Y porque al incorporarse siempre debes verificar la seguridad. Estar a la derecha no da prioridad al incorporarse.","val":11,"fase":3},{"id":6231,"bg":"Кой от водачите е с предимство при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/69569.png","v":null,"a":[{"t":"водачът на лекия автомобил","ok":true,"i":null,"es":"el conductor del turismo"},{"t":"водачът на товарния автомобил","ok":false,"i":null,"es":"el conductor del camión"}],"f":7,"es":"¿Qué conductor tiene prioridad en esta situación?","explain":"El turismo tiene prioridad — según la imagen está en vía preferente o a la derecha del camión.","val":10,"fase":3},{"id":6261,"bg":"При тази ситуация съм с предимство и не съм задължен да пропусна пешеходеца:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70018.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación tengo prioridad y no estoy obligado a dejar pasar al peatón. Esto es:","explain":"⚠️ TRAMPA IMPORTANTE: INCORRECTO — los peatones en paso de peatones tienen SIEMPRE prioridad, independientemente de tu prioridad de paso vehicular. El peatón en el paso siempre manda.","val":8,"fase":4},{"id":6301,"bg":"При тази ситуация трябва да премина преди червения автомобил.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70581.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":5,"es":"En esta situación debo pasar antes que el coche rojo. Esto es:","explain":"INCORRECTO — el rojo tiene prioridad sobre ti en esta situación. Debes cederle el paso.","val":8,"fase":4},{"id":6305,"bg":"При тази ситуация водачът на товарния автомобил:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70647.png","v":null,"a":[{"t":"трябва да пропусне двата автомобила, защото излиза от гараж","ok":true,"i":null,"es":"debe dejar pasar a los dos coches porque sale de un garaje"},{"t":"трябва да пропусне пешеходците","ok":true,"i":null,"es":"debe dejar pasar a los peatones"},{"t":"е с предимство пред синия автомобил, защото се намира от дясната му страна","ok":false,"i":null,"es":"tiene prioridad sobre el azul porque está a su derecha"}],"f":4,"es":"En esta situación, el conductor del camión: (2 correctas)","explain":"⚠️ MULTIRESPUESTA: al salir de un garaje siempre cedes a TODO el tráfico de la calle + a los peatones. El camión no tiene prioridad sobre nadie al salir de una propiedad privada.","val":5,"fase":4},{"id":6334,"bg":"При тази ситуация съм с предимство, защото се движа направо.","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70713.png","v":null,"a":[{"t":"неправилно","ok":true,"i":null,"es":"INCORRECTO"},{"t":"правилно","ok":false,"i":null,"es":"correcto"}],"f":9,"es":"En esta situación tengo prioridad porque voy recto. Esto es:","explain":"INCORRECTO. En tu acceso hay un ceda el paso, así que debes dejar pasar a quien circula por la vía con prioridad, y además el tranvía tiene preferencia sobre los vehículos sin carriles. Ir recto no otorga preferencia a nadie: la dirección que lleves no entra en el reparto de prioridad. Es un cebo que se repite mucho en el examen — desconfía siempre de 'porque voy recto'.","val":13,"fase":3},{"id":6343,"bg":"При тази ситуация водачът на автомобила длъжен ли е да пропусне трамвая?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/70879.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"En esta situación ¿está obligado el conductor del coche a dejar pasar al tranvía?","explain":"SÍ — el tranvía tiene prioridad. En la mayoría de situaciones los tranvías tienen prioridad sobre los vehículos de motor.","val":11,"fase":3},{"id":6378,"bg":"При тази ситуация водачът на червения автомобил извършва ли нарушение?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71309.png","v":null,"a":[{"t":"да","ok":true,"i":null,"es":"sí"},{"t":"не","ok":false,"i":null,"es":"no"}],"f":7,"es":"En esta situación ¿comete infracción el conductor del coche rojo?","explain":"SÍ — el coche rojo está infringiendo alguna norma en la situación mostrada (adelantamiento indebido, invasión de carril, etc.).","val":10,"fase":3},{"id":6380,"bg":"Когато, при голям надлъжен наклон, за разминаване на единично ППС със състав от ППС е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"единичното превозно средство","ok":true,"i":null,"es":"el vehículo individual"},{"t":"ППС, което се изкачва по наклона","ok":false,"i":null,"es":"el vehículo que sube"},{"t":"ППС, което се спуска по наклона","ok":false,"i":null,"es":"el vehículo que baja"},{"t":"състава от ППС","ok":false,"i":null,"es":"el convoy"}],"f":7,"es":"Cuando en pendiente pronunciada un vehículo individual debe ceder el paso a un convoy, ¿quién retrocede?","explain":"Retrocede el vehículo INDIVIDUAL: hacer retroceder un convoy (vehículo + remolque) es mucho más difícil y peligroso. La regla general sube/baja solo se aplica entre vehículos de condiciones equivalentes.","val":10,"fase":3},{"id":6381,"bg":"Когато, на път с голям надлъжен наклон, за разминаването на лек с товарен автомобил е необходимо движение назад, то се извършва от:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"лекия автомобил","ok":true,"i":null,"es":"el turismo"},{"t":"товарния автомобил","ok":false,"i":null,"es":"el camión"},{"t":"автомобила, който се изкачва по наклона","ok":false,"i":null,"es":"el que sube"},{"t":"автомобила, който се спуска по наклона","ok":false,"i":null,"es":"el que baja"}],"f":7,"es":"Cuando en pendiente pronunciada un turismo debe ceder el paso a un camión, ¿quién retrocede?","explain":"Retrocede el TURISMO: es más corto, más maniobrable y con mejor visibilidad trasera que el camión. Entre vehículos de distinta categoría decide la facilidad de la maniobra, no quién sube o baja.","val":10,"fase":3},{"id":6399,"bg":"Кое от изброените ППС е забранено да изпреварвате след този пътен знак?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/67607.png","v":null,"a":[{"t":"лек автомобил","ok":true,"i":null,"es":"turismo"},{"t":"съчленен автобус","ok":true,"i":null,"es":"autobús articulado"},{"t":"мотоциклет без кош","ok":false,"i":null,"es":"moto sin sidecar"},{"t":"каруца","ok":false,"i":null,"es":"carruaje"}],"f":5,"es":"¿Qué vehículo está PROHIBIDO adelantar después de esta señal? (2 correctas)","explain":"⚠️ MULTIRESPUESTA: la señal de prohibición de adelantamiento afecta a turismos Y autobuses articulados (vehículos a motor). Las motos sin sidecar y los carruajes están EXENTOS de esta prohibición.","val":7,"fase":4},{"id":6413,"bg":"Изпреварването на МПС, с изключение на мотопеди и мотоциклети без кош, е забранено:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"при използване на пътна лента за насрещно движение, когато изпреварващият не може да се върне безпрепятствено в напуснатата пътна лента","ok":true,"i":null,"es":"usando el carril contrario no es posible volver al carril sin obstaculizar"},{"t":"пред и върху сигнализирана пешеходна пътека","ok":true,"i":null,"es":"la visibilidad es limitada"},{"t":"в стеснен участък от пътя","ok":false,"i":null,"es":"el vehículo adelantante tiene los intermitentes averiados"},{"t":"на железопътен прелез с бариери","ok":false,"i":null,"es":"se realiza en vía de dos carriles de doble sentido"}],"f":5,"es":"El adelantamiento está PROHIBIDO cuando: (2 correctas)","explain":"Igual que su gemela: prohibido si no puedes volver a tu carril sin obstaculizar y con visibilidad limitada. La avería del intermitente se suple con señales de mano, y adelantar en vía de doble sentido es legal cuando hay visibilidad y espacio.","val":8,"fase":4},{"id":6418,"bg":"Разрешено ли е изпреварването при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/71819.png","v":null,"a":[{"t":"не","ok":true,"i":null,"es":"no"},{"t":"да","ok":false,"i":null,"es":"sí"}],"f":8,"es":"¿Está permitido adelantar en esta situación?","explain":"NO — la situación mostrada (curva, cima, paso a nivel, señal prohibitiva) impide el adelantamiento con seguridad.","val":12,"fase":3},{"id":6434,"bg":"Как ще постъпите при тази ситуация, когато автомобилът зад вас е подал сигнал за отклонение вляво?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/124384.png","v":null,"a":[{"t":"намалявам скоростта и пропускам автомобила зад мен","ok":true,"i":null,"es":"reduzco velocidad y dejo pasar al coche de detrás"},{"t":"подавам сигнал и заобикалям повредения автомобил, преди автомобила, който се движи зад мен","ok":false,"i":null,"es":"señalizo y rodeo el coche averiado antes que el de detrás"}],"f":8,"es":"¿Cómo actuarás en esta situación cuando el coche detrás señaliza desplazarse a la izquierda?","explain":"Reduces velocidad y dejas pasar al de detrás — él ya ha señalizado que va a adelantar. Adelantarte tú cuando él ya señalizó crearía un peligro real.","val":13,"fase":3},{"id":6451,"bg":"Движението назад при ограничена видимост е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":null,"a":[{"t":"разрешено само ако е осигурено лице, което да сигнализира при поява на опасност","ok":true,"i":null,"es":"permitida solo si hay alguien que señalice el peligro"},{"t":"разрешено, ако има огледало за виждане назад","ok":false,"i":null,"es":"permitida si hay espejo retrovisor"},{"t":"забранено","ok":false,"i":null,"es":"prohibida"}],"f":7,"es":"La marcha atrás con visibilidad limitada está:","explain":"Con visibilidad limitada, la marcha atrás solo está permitida si alguien desde fuera vigila y señaliza el peligro. El espejo retrovisor no cubre los ángulos muertos precisamente cuando la visibilidad ya es mala; prohibida del todo no está.","val":10,"fase":3},{"id":12036,"bg":"Какъв е правилният начин на действие при тази ситуация?","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":22,"a":[{"t":"продължавам движението си, без да променям скоростта си","ok":false,"i":null,"es":"continúo sin cambiar velocidad"},{"t":"продължавам движението си в лентата за паркиране","ok":false,"i":null,"es":"continúo por el carril de estacionamiento"},{"t":"продължавам движението си, като увеличавам скоростта си","ok":false,"i":null,"es":"acelero"},{"t":"намалявам скоростта си","ok":true,"i":null,"es":"reduzco la velocidad"}],"f":2,"es":"¿Cuál es la actuación correcta en esta situación? (VIDEO)","explain":"🎬 VIDEO: reduce velocidad. Sea cual sea el obstáculo o situación mostrada, la reducción de velocidad es siempre la respuesta correcta ante la incertidumbre.","val":2,"fase":4},{"id":12051,"bg":"Искате да изпреварите. При тази ситуация:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":null,"v":43,"a":[{"t":"изпреварвам трите превозни средства, които се движат пред мен, наведнъж (с една маневра)","ok":false,"i":null,"es":"adelanto los tres vehículos de una vez"},{"t":"не предприемам изпреварване, преди да се убедя, че водачът на синия автомобил няма да изпреварва","ok":true,"i":null,"es":"no adelanto hasta confirmar que el coche azul no va a adelantar"},{"t":"когато синият автомобил започне изпреварването, изпреварвам, като се движа зад него","ok":false,"i":null,"es":"cuando el azul empiece a adelantar, me pongo detrás de él"}],"f":6,"es":"Quiere adelantar. En esta situación: (VIDEO)","explain":"🎬 VIDEO: NO adelantes hasta confirmar que el azul no va a hacer lo mismo. Adelantar por encima de otro que ya adelanta es una maniobra peligrosísima.","val":9,"fase":4},{"id":5884,"bg":"При този сигнал на светофара навлизането в кръстовището е:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/102995.png","v":null,"a":[{"t":"разрешено, освен когато водачът може да остане в кръстовището поради задръстване","ok":true,"i":null,"es":"permitido, excepto si quedaras bloqueado dentro por retención"},{"t":"разрешено без ограничения","ok":false,"i":null,"es":"permitido sin restricciones"},{"t":"забранено","ok":false,"i":null,"es":"prohibido"}],"f":9,"es":"Con esta señal del semáforo entrar en la intersección está:","explain":"Permitido, SALVO que la retención vaya a dejarte parado dentro. Con verde puedes entrar, pero no si el tráfico de delante te va a inmovilizar en mitad del cruce bloqueando a los demás. 'Sin restricciones' es el error clásico: el verde autoriza a pasar, no a atascar el cruce. 'Prohibido' descarta el verde. Antes de entrar, comprueba que tienes salida al otro lado.","val":14,"fase":3},{"id":5952,"bg":"При тази ситуация, при преминаване през кръстовището, трябва да се съобразявате:","p":3,"s":"Раздел 4. ПРАВИЛА ЗА ДВИЖЕНИЕТО ПО ПЪТИЩАТА","i":"https://rta.government.bg/services/proekt-masiv-2024/B/assets/51499.png","v":null,"a":[{"t":"със сигнала на светофара","ok":true,"i":null,"es":"la señal del semáforo"},{"t":"с пьтния знак забраняващ завиването надясно","ok":true,"i":null,"es":"la señal que prohíbe girar a la derecha"},{"t":"с пьтния знак относно предимството","ok":false,"i":null,"es":"la señal de prioridad"}],"f":9,"es":"En esta situación al pasar por la intersección debes atenerte a: (2 correctas)","explain":"MULTIRESPUESTA: el SEMÁFORO y la señal que prohíbe girar a la derecha. El verde está encendido y anula al STOP, porque un semáforo en funcionamiento deja sin efecto las señales de prioridad. Pero no anula las de prohibición: la de giro a la derecha sigue vigente y el verde no te habilita esa maniobra. Por eso la de prioridad es la única que no cuenta aquí.","val":14,"fase":3}];